import React, { createContext, useContext, useState, ReactNode, useEffect, useCallback, useMemo } from 'react';
import { UserProfile, StoreData, CardDefinition, CardInstance, LocationDefinition, CardRarity, SeasonPassData, SeasonRewardType, ProgressionData, ActivityLogEntry, ProgressionRewardType } from '../types';
import { audio } from '../services/audio';
import { api } from '../services/api';
import { CARDS } from '../constants';
import { generateInstanceId } from '../utils/id';

export type CollectionSortOption = 'Cost' | 'Power' | 'Name' | 'Newest';

interface BoxReward {
    type: 'box';
    boxType: 'MYSTERY' | 'MEGA';
    title: string;
    description: string;
}

export interface SeasonRewardInfo {
    type: 'level_info';
    level: number;
    rewardType: SeasonRewardType | ProgressionRewardType;
    rewardAmount: string | number;
    isClaimed?: boolean;
    cardDef?: CardDefinition;
}

interface InspectingCard {
    data: CardInstance | CardDefinition;
    borderOverride?: string;
}

interface UserContextType {
    user: UserProfile;
    // Store State
    storeData: StoreData | null;
    isStoreLoading: boolean;
    storeScrollTarget: string | null;
    setStoreScrollTarget: (id: string | null) => void;
    // Season Pass State
    seasonPassData: SeasonPassData | null;
    isSeasonLoading: boolean;
    syncSeasonPass: () => Promise<void>;
    debugSwitchSeason: () => Promise<void>; 
    // Progression State
    progressionData: ProgressionData | null;
    activityLog: ActivityLogEntry[];
    isProgressionLoading: boolean;
    syncProgression: (showLoading?: boolean) => Promise<void>;
    claimProgressionReward: (type: ProgressionRewardType) => Promise<boolean>;
    // Inspect State
    inspectingCard: InspectingCard | null;
    inspectingLocation: LocationDefinition | null;
    inspectingCurrency: { type: 'gold' | 'credits', amount: number } | null;
    inspectingBox: BoxReward | null;
    inspectingReward: SeasonRewardInfo | null;
    // Collection UI State
    collectionSort: CollectionSortOption;
    setCollectionSort: (s: CollectionSortOption) => void;
    collectionFilterSearch: string;
    setCollectionFilterSearch: (s: string) => void;
    collectionFilterTags: string[];
    toggleCollectionFilterTag: (tag: string) => void;
    // Actions
    addCredits: (amount: number) => void;
    spendCredits: (amount: number) => boolean;
    addGold: (amount: number) => void;
    spendGold: (amount: number) => boolean;
    setActiveDeck: (id: number) => Promise<void>;
    updateDeck: (deckId: number, cardIds: string[]) => void;
    upgradeCard: (cardId: string) => boolean;
    processPurchase: (offerId: string) => Promise<boolean>;
    syncStore: () => Promise<void>;
    // Inspector Methods
    inspect: (item: any, options?: { borderOverride?: string }) => void;
    closeInspector: () => void;
    // Derived
    activeDeck: string[];
}

const UserContext = createContext<UserContextType | null>(null);

export const UserProvider: React.FC<{ children: ReactNode; initialUser: UserProfile }> = ({ children, initialUser }) => {
    const [user, setUser] = useState<UserProfile>(initialUser);
    const [storeData, setStoreData] = useState<StoreData | null>(null);
    const [isStoreLoading, setIsStoreLoading] = useState(false);
    const [storeScrollTarget, setStoreScrollTarget] = useState<string | null>(null);
    const [seasonPassData, setSeasonPassData] = useState<SeasonPassData | null>(null);
    const [isSeasonLoading, setIsSeasonLoading] = useState(false);

    // Progression State
    const [progressionData, setProgressionData] = useState<ProgressionData | null>(null);
    const [activityLog, setActivityLog] = useState<ActivityLogEntry[]>([]);
    const [isProgressionLoading, setIsProgressionLoading] = useState(false);

    const [inspectingCard, setInspectingCard] = useState<InspectingCard | null>(null);
    const [inspectingLocation, setInspectingLocation] = useState<LocationDefinition | null>(null);
    const [inspectingCurrency, setInspectingCurrency] = useState<{ type: 'gold' | 'credits', amount: number } | null>(null);
    const [inspectingBox, setInspectingBox] = useState<BoxReward | null>(null);
    const [inspectingReward, setInspectingReward] = useState<SeasonRewardInfo | null>(null);
    const [collectionSort, setCollectionSort] = useState<CollectionSortOption>('Cost');
    const [collectionFilterSearch, setCollectionFilterSearch] = useState('');
    const [collectionFilterTags, setCollectionFilterTags] = useState<string[]>([]);

    const toggleCollectionFilterTag = useCallback((tag: string) => {
        setCollectionFilterTags(prev => prev.includes(tag) ? prev.filter(t => t !== tag) : [...prev, tag]);
    }, []);

    const syncSeasonPass = useCallback(async () => {
        setIsSeasonLoading(true);
        try {
            const data = await api.getSeasonPass(user);
            setSeasonPassData(data);
        } catch (e) {
            console.error("Season Sync Failed", e);
        } finally {
            setIsSeasonLoading(false);
        }
    }, [user]);

    const syncProgression = useCallback(async (showLoading = false) => {
        if (showLoading) setIsProgressionLoading(true);
        try {
            const data = await api.getProgression(user);
            const logs = await api.getActivityLog();
            setProgressionData(data);
            setActivityLog(logs);
        } catch (e) {
            console.error("Progression Sync Failed", e);
        } finally {
            setIsProgressionLoading(false);
        }
    }, [user]);

    const claimProgressionReward = async (type: ProgressionRewardType): Promise<boolean> => {
        try {
            const result = await api.claimProgressionReward(user, type);
            if (result.success && result.updatedProfile) {
                audio.play('sfx_victory');
                setUser(result.updatedProfile);
                // Background sync (Silent)
                await syncProgression(false);
                return true;
            }
        } catch (e) {
            console.error("Claim failed", e);
        }
        return false;
    };

    const debugSwitchSeason = useCallback(async () => {
        await api.debugNextSeason();
        await syncSeasonPass();
    }, [syncSeasonPass]);

    const syncStore = useCallback(async (showLoading = false) => {
        if (showLoading) setIsStoreLoading(true);
        try {
            const data = await api.getStoreOffers(user);
            setStoreData(data);
        } catch (e) {
            console.error("Store Sync Failed", e);
        } finally {
            setIsStoreLoading(false);
        }
    }, [user]);

    // Initial background sync for store and season pass (the user is already provided)
    useEffect(() => {
        syncStore(true);
        syncSeasonPass();
        syncProgression(true);
        let timeout: any;
        const poll = () => {
            const delay = (storeData?.refreshHintSeconds || 60) * 1000;
            timeout = setTimeout(async () => {
                await syncStore();
                poll();
            }, delay);
        };
        poll();
        return () => clearTimeout(timeout);
    }, [user.id, syncStore, syncSeasonPass, syncProgression]);

    const inspect = (item: any, options?: { borderOverride?: string }) => {
        if (!item) return; 
        audio.playUiClick();
        setInspectingCurrency(null); setInspectingCard(null); setInspectingLocation(null); setInspectingBox(null); setInspectingReward(null);
        if ('type' in item) {
            if (item.type === 'gold' || item.type === 'credits') setInspectingCurrency(item);
            else if (item.type === 'box') setInspectingBox(item);
            else if (item.type === 'level_info') setInspectingReward(item);
        } 
        else if (('instanceId' in item) || ('basePower' in item) || ('definitionId' in item)) setInspectingCard({ data: item, borderOverride: options?.borderOverride });
        else if ('description' in item) setInspectingLocation(item);
    };

    const closeInspector = () => { setInspectingCard(null); setInspectingLocation(null); setInspectingCurrency(null); setInspectingBox(null); setInspectingReward(null); };
    const addCredits = (amount: number) => { setUser(prev => ({ ...prev, credits: prev.credits + amount })); };
    const spendCredits = (amount: number): boolean => {
        if (user.credits >= amount) { setUser(prev => ({ ...prev, credits: prev.credits - amount })); return true; }
        return false;
    };
    const addGold = (amount: number) => { setUser(prev => ({ ...prev, gold: prev.gold + amount })); };
    const spendGold = (amount: number): boolean => {
        if (user.gold >= amount) { setUser(prev => ({ ...prev, gold: prev.gold - amount })); return true; }
        return false;
    };
    const setActiveDeck = async (id: number) => {
        audio.playUiClick();
        try { const updatedUser = await api.updateActiveDeck(user, id); setUser(updatedUser); }
        catch (e) { console.error("Failed to update active deck on server:", e); }
    };
    const updateDeck = (deckId: number, cardIds: string[]) => {
        setUser(prev => ({
            ...prev, decks: { ...prev.decks, [deckId]: cardIds },
            deckStats: { ...prev.deckStats, [deckId]: { ...(prev.deckStats[deckId] || { conquestWinRate: 0, ladderWinRate: 0, conquestWins: 0, conquestTotal: 0, ladderWins: 0, ladderLosses: 0 }), lastModified: new Date().toISOString() } }
        }));
    };
    const upgradeCard = (cardId: string): boolean => {
        const currentRarity = user.cardRarities[cardId] || "Common";
        const rarityPath: CardRarity[] = ["Common", "Rare", "Epic", "Legendary"];
        const currentIndex = rarityPath.indexOf(currentRarity);
        if (currentIndex === -1 || currentIndex === rarityPath.length - 1) return false;
        const nextRarity = rarityPath[currentIndex + 1];
        const costMap: Record<string, number> = { "Rare": 100, "Epic": 400, "Legendary": 1000 };
        const cost = costMap[nextRarity];
        if (user.credits >= cost) {
            setUser(prev => ({ ...prev, credits: prev.credits - cost, level: prev.level + (currentIndex + 1), cardRarities: { ...prev.cardRarities, [cardId]: nextRarity } }));
            audio.play('sfx_victory'); return true;
        }
        return false;
    };
    const processPurchase = async (offerId: string): Promise<boolean> => {
        const transactionId = `txn_${generateInstanceId()}`;
        try {
            const response = await api.purchaseOffer(user, offerId, transactionId);
            if (response.success && response.updatedProfile) { audio.play('sfx_victory'); setUser(response.updatedProfile); return true; }
            else { audio.play('sfx_ui_hover'); return false; }
        } catch (err) { console.error("Network Exception:", err); return false; }
    };

    const activeDeck = useMemo(() => user.decks[user.activeDeckId] || [], [user.decks, user.activeDeckId]);

    return (
        <UserContext.Provider value={{ 
            user, storeData, isStoreLoading, storeScrollTarget, setStoreScrollTarget,
            seasonPassData, isSeasonLoading, syncSeasonPass, debugSwitchSeason,
            progressionData, activityLog, isProgressionLoading, syncProgression, claimProgressionReward,
            inspectingCard, inspectingLocation, inspectingCurrency, inspectingBox, inspectingReward,
            collectionSort, setCollectionSort, collectionFilterSearch, setCollectionFilterSearch,
            collectionFilterTags, toggleCollectionFilterTag,
            addCredits, spendCredits, addGold, spendGold, setActiveDeck, updateDeck, upgradeCard, processPurchase, syncStore, inspect, closeInspector, activeDeck
        }}>{children}</UserContext.Provider>
    );
};

export const useUser = () => {
    const context = useContext(UserContext);
    if (!context) throw new Error('useUser must be used within a UserProvider');
    return context;
};

import React, { useMemo, useState } from 'react';
import { StandardHeader } from '../ui/StandardHeader';
import { ScreenKey, ActivityLogEntry, ProgressionRewardType, ProgressionTrack } from '../../types';
import { useUser } from '../../contexts/UserContext';
import { RewardIconGraphic } from '../ui/RewardItemVisual';
import { GameText } from '../ui/GameText';
import { HexBadge } from '../ui/HexBadge';
import { SlantedButton } from '../ui/SlantedButton';
import { CreditIcon, GoldIcon, CardIcon, BoosterIcon, OmegaBoxIcon } from '../../components/ui/CurrencyIcons';

type LogCategory = 'all' | 'credits' | 'gold' | 'booster' | 'box' | 'card';

const ActivityLogItem: React.FC<{ item: ActivityLogEntry }> = ({ item }) => {
    let iconScale = 'scale-[1.82]'; 
    if (item.type === 'card') iconScale = 'scale-75';
    else if (item.type === 'credits' || item.type === 'gold') iconScale = 'scale-[1.94]';

    return (
        <div className="flex items-center justify-between py-1 px-3 bg-slate-800/80 border border-slate-500 rounded-lg shadow-sm hover:border-slate-400 transition-colors cursor-default group">
            <div className="flex items-center gap-3">
                <div className="w-12 h-12 flex items-center justify-center overflow-visible">
                    <div className={iconScale}>
                        <RewardIconGraphic type={item.type as any} size="sm" cardDef={item.cardDef} />
                    </div>
                </div>
                <div>
                    <div className="font-black text-[0.8rem] tracking-tight text-white uppercase italic leading-tight">{item.title}</div>
                    <div className="text-[0.6rem] text-slate-300/80 font-bold uppercase tracking-widest mt-0.5">
                        {item.type === 'card' ? 'Unit Unlocked' : 'Manifest Claim'}
                    </div>
                </div>
            </div>
            <div className="text-right flex flex-col items-end">
                 <div className="text-[0.75rem] font-black text-white uppercase tracking-tighter tabular-nums leading-none mb-1">{item.date}</div>
                 <div className="text-[0.65rem] font-bold text-slate-300/80 uppercase tracking-widest tabular-nums">{item.time}</div>
            </div>
        </div>
    );
};

export const ProgressionScreen: React.FC<{ onNavigate: (screen: ScreenKey) => void }> = ({ onNavigate }) => {
    const { user, progressionData, activityLog, isProgressionLoading, claimProgressionReward, inspect } = useUser();
    const [logFilter, setLogFilter] = useState<LogCategory>('all');
    const [claimingType, setClaimingType] = useState<ProgressionRewardType | null>(null);

    const filteredLog = useMemo(() => {
        if (logFilter === 'all') return activityLog;
        return activityLog.filter(item => item.type === logFilter);
    }, [activityLog, logFilter]);

    const nextHero = useMemo(() => {
        if (!progressionData) return null;
        return [...progressionData.tracks].sort((a, b) => (a.targetXP - a.currentXP) - (b.targetXP - b.currentXP))[0];
    }, [progressionData]);

    const handleInspect = (track: ProgressionTrack) => {
        inspect({
            type: track.type === 'box' ? 'box' : 'level_info',
            level: user.level + (track.targetXP - track.currentXP),
            rewardType: track.type,
            rewardAmount: track.nextRewardAmount,
            cardDef: track.nextRewardCardDef,
            boxType: 'MEGA',
            title: track.label,
            description: 'Acquired through progression.'
        });
    };

    const handleClaim = async (type: ProgressionRewardType) => {
        if (claimingType) return;
        setClaimingType(type);
        await claimProgressionReward(type);
        setClaimingType(null);
    };

    const getScale = (type: string) => {
        if (type === 'gold' || type === 'credits') return 'scale-[0.48]'; 
        if (type === 'booster') return 'scale-[0.68]'; 
        if (type === 'card') return 'scale-[0.60]'; 
        return 'scale-[1.0]';
    };

    const getVariant = (type: ProgressionRewardType) => {
        switch(type) {
            case 'booster': return 'success';
            case 'credits': return 'blue';
            case 'gold': return 'warning';
            case 'box': return 'primary';
            case 'card': return 'secondary';
            default: return 'secondary';
        }
    };

    const getColors = (type: ProgressionRewardType) => {
        switch(type) {
            case 'booster': return { color: 'from-emerald-400 to-emerald-600', bgTrack: 'bg-[#064e3b]', borderColor: 'border-emerald-400/50' };
            case 'credits': return { color: 'from-blue-400 to-blue-600', bgTrack: 'bg-[#1e3a8a]', borderColor: 'border-blue-400/50' };
            case 'gold': return { color: 'from-amber-400 to-amber-600', bgTrack: 'bg-[#78350f]', borderColor: 'border-amber-400/50' };
            case 'box': return { color: 'from-indigo-400 to-indigo-600', bgTrack: 'bg-[#1e1b4b]', borderColor: 'border-indigo-400/50' };
            case 'card': return { color: 'from-white to-slate-400', bgTrack: 'bg-[#334155]', borderColor: 'border-white/50' };
        }
    };

    const renderFilterIcon = (cat: LogCategory) => {
        switch(cat) {
            case 'all': return <span className="font-black text-[0.65rem] -skew-x-[9deg]">ALL</span>;
            case 'credits': return <CreditIcon size="sm" />;
            case 'gold': return <GoldIcon size="sm" />;
            case 'card': return <CardIcon size="sm" />;
            case 'box': return <OmegaBoxIcon size="sm" />;
            case 'booster': return <BoosterIcon size="sm" />;
            default: return null;
        }
    };

    // DECOUPLED LOADING: Only show full-page loader on initial zero-data state
    if (!progressionData && isProgressionLoading) {
        return (
            <div className="w-full h-full flex flex-col items-center justify-center bg-slate-950">
                <div className="w-8 h-8 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mb-4" />
                <span className="text-[0.6rem] font-black text-indigo-400 uppercase tracking-[0.3em] animate-pulse">Syncing Sector Data...</span>
            </div>
        );
    }

    if (!progressionData) return null;

    return (
        <div className="w-full h-full flex flex-col bg-slate-950 overflow-hidden relative">
            <StandardHeader 
                title="CAREER" 
                leftContent={
                    <button 
                        onClick={() => onNavigate('DECK')}
                        className="w-8 h-8 rounded-full bg-white/5 border border-white/10 flex items-center justify-center text-white active:scale-90 transition-transform"
                    >
                        <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 19l-7-7 7-7" /></svg>
                    </button>
                }
            />

            <div className="shrink-0 pt-6 pb-2 flex flex-col items-center">
                <span className="text-[0.6rem] font-black text-slate-500 uppercase tracking-[0.4em] mb-1">Collection Level</span>
                <div className="h-10 w-full px-4">
                    <GameText text={progressionData.collectionLevel.toLocaleString()} baseFontSize={3.2} className="text-white font-black italic tracking-tighter drop-shadow-lg" />
                </div>
            </div>

            <div className="flex-1 overflow-y-auto px-4 space-y-12 pb-32 pt-6">

                {/* HERO SECTION */}
                {nextHero && (
                    <div className="space-y-4">
                        <h3 className="text-[0.6rem] font-black text-indigo-400 uppercase tracking-[0.3em] px-1 text-center">Next Objective</h3>
                        <div 
                            className="relative h-24 flex items-center cursor-pointer group active:scale-[0.99] transition-transform"
                            onClick={() => handleInspect(nextHero)}
                        >
                            <div className="absolute top-[0.1em] left-[2.8rem] right-0 h-6 z-50 pointer-events-none">
                                <GameText 
                                    text={nextHero.type === 'card' ? 'new card' : `${nextHero.nextRewardAmount} ${nextHero.type}`} 
                                    baseFontSize={1.0} 
                                    className="text-white font-black italic uppercase drop-shadow-[0_2px_4px_rgba(0,0,0,1)] tracking-widest text-left"
                                />
                            </div>

                            <div className="absolute left-0 z-50 drop-shadow-[0_0_25px_rgba(79,70,229,0.4)]">
                                <HexBadge variant={getVariant(nextHero.type)} size="xl" glow>
                                    <div className="relative w-full h-full overflow-visible">
                                        <div className={`absolute inset-0 flex items-center justify-center ${getScale(nextHero.type)}`}>
                                            <RewardIconGraphic 
                                                type={nextHero.type as any} 
                                                size="xl" 
                                                cardDef={nextHero.nextRewardCardDef} 
                                            />
                                        </div>
                                    </div>
                                </HexBadge>
                            </div>

                            {(() => {
                                const styles = getColors(nextHero.type)!;
                                const percent = (nextHero.currentXP / nextHero.targetXP) * 100;
                                return (
                                    <div className={`absolute left-10 right-2 h-10 ${styles.bgTrack} border-2 ${styles.borderColor} rounded-full overflow-hidden shadow-[inset_0_2px_8px_rgba(0,0,0,0.8)] z-10 transition-colors duration-500`}>
                                        <div className={`h-full bg-gradient-to-r ${styles.color} transition-all duration-1000 ease-out relative shadow-[0_0_15px_rgba(255,255,255,0.2)]`} style={{ width: `${percent}%` }}>
                                            <div className="absolute inset-0 bg-white/10 animate-[pulse_2s_infinite]" />
                                        </div>
                                        <div className="absolute inset-0 flex items-center justify-center pl-12 pr-4 py-0 pointer-events-none">
                                            <GameText 
                                                text={`${nextHero.currentXP} / ${nextHero.targetXP} XP`} 
                                                baseFontSize={1.3} 
                                                className="text-white font-black italic tracking-widest uppercase drop-shadow-[0_2px_4px_rgba(0,0,0,1)]"
                                            />
                                        </div>
                                    </div>
                                );
                            })()}
                        </div>
                    </div>
                )}

                <div className="h-px w-full bg-white/10 relative">
                    <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 w-2 h-2 bg-slate-950 border border-white/20 rotate-45" />
                </div>

                {/* TRACKS MATRIX */}
                <div className="space-y-16">
                    {progressionData.tracks.map(track => {
                        const styles = getColors(track.type)!;
                        const variant = getVariant(track.type);
                        const percent = (track.currentXP / track.targetXP) * 100;
                        const canClaim = track.unclaimedCount > 0;
                        const isClaimingThis = claimingType === track.type;

                        return (
                            <div key={track.type} className="grid grid-cols-[1fr_6rem] gap-2 items-end">
                                <div className="relative h-16 flex items-center cursor-pointer group" onClick={() => handleInspect(track)}>
                                    <div className="absolute top-[0.1em] left-[2.4rem] right-0 h-5 z-50 pointer-events-none">
                                        <GameText 
                                            text={track.type === 'card' ? 'new card' : `${track.nextRewardAmount} ${track.type}`} 
                                            baseFontSize={0.7} 
                                            className="text-white/90 font-black italic uppercase drop-shadow-[0_2px_4px_rgba(0,0,0,1)] tracking-tighter text-left"
                                        />
                                    </div>

                                    <div className="absolute left-0 z-40 transition-transform group-hover:scale-110 origin-center drop-shadow-xl">
                                        <HexBadge variant={variant} size="lg">
                                            <div className="relative w-full h-full overflow-visible">
                                                <div className={`absolute inset-0 flex items-center justify-center ${getScale(track.type)}`}>
                                                    <RewardIconGraphic 
                                                        type={track.type as any} 
                                                        size="lg" 
                                                        cardDef={track.nextRewardCardDef} 
                                                    />
                                                </div>
                                            </div>
                                        </HexBadge>
                                    </div>

                                    <div className={`absolute left-8 right-0 h-7 ${styles.bgTrack} border-2 ${styles.borderColor} rounded-full overflow-hidden z-10 shadow-[inset_0_2px_4px_rgba(0,0,0,0.5)] group-hover:border-white/40 transition-colors`}>
                                        <div className={`h-full bg-gradient-to-r ${styles.color} transition-all duration-1000 ease-out`} style={{ width: `${percent}%` }} />
                                        <div className="absolute inset-0 flex items-center justify-center pl-10 pr-2 py-0 pointer-events-none">
                                            <GameText 
                                                text={`${track.currentXP} / ${track.targetXP} XP`} 
                                                baseFontSize={0.9} 
                                                className="text-white font-black italic tracking-widest drop-shadow-md"
                                            />
                                        </div>
                                    </div>
                                </div>

                                <div className="flex flex-col items-center gap-1.5 pb-0.5">
                                    <SlantedButton 
                                        variant={canClaim ? variant : 'secondary'}
                                        size="xs"
                                        className={`!w-24 !h-9 shadow-lg ${(!canClaim || isClaimingThis) ? 'opacity-40 grayscale' : ''}`}
                                        disabled={!canClaim || isClaimingThis}
                                        onClick={(e) => { e.stopPropagation(); handleClaim(track.type); }}
                                    >
                                        {isClaimingThis ? "CLAIMING..." : `CLAIM\n${track.type === 'box' ? 'box' : track.type}`}
                                    </SlantedButton>
                                    <span className={`text-[0.45rem] font-black uppercase tracking-[0.2em] leading-none drop-shadow-sm whitespace-nowrap ${canClaim ? 'text-slate-300' : 'text-slate-600'}`}>
                                        {track.unclaimedCount} UNCLAIMED
                                    </span>
                                </div>
                            </div>
                        );
                    })}
                </div>

                {/* CLAIM ACTIVITY LOG SECTION */}
                <div className="pt-12 pb-12">
                    <div className="flex flex-col gap-4 mb-6 px-1">
                        <div className="flex items-center gap-3">
                            <h3 className="text-[0.65rem] font-black text-slate-500 uppercase tracking-[0.4em] whitespace-nowrap">Activity Log</h3>
                            <div className="flex-1 h-px bg-white/10" />
                        </div>

