                                        <div className={`h-full bg-gradient-to-r ${styles.color} transition-all duration-1000 ease-out relative shadow-[0_0_15px_rgba(255,255,255,0.2)]`} style={{ width: `${percent}%` }}>
                                            <div className="absolute inset-0 bg-white/10 animate-[pulse_2s_infinite]" />
                                        </div>
                                        <div className="absolute inset-0 flex items-center justify-center pl-12 pr-4 py-0 pointer-events-none">
                                            <GameText 
                                                text={`${nextHero.currentXP} / ${nextHero.targetXP} XP`} 
                                                baseFontSize={1.3} 
                                                className="text-white font-black italic tracking-widest uppercase drop-shadow-[0_2px_4px_rgba(0,0,0,1)]"
                                            />
                                        </div>
                                    </div>
                                );
                            })()}
                        </div>
                    </div>
                )}

                <div className="h-px w-full bg-white/10 relative">
                    <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 w-2 h-2 bg-slate-950 border border-white/20 rotate-45" />
                </div>

                {/* TRACKS MATRIX */}
                <div className="space-y-16">
                    {progressionData.tracks.map(track => {
                        const styles = getColors(track.type)!;
                        const variant = getVariant(track.type);
                        const percent = (track.currentXP / track.targetXP) * 100;
                        const canClaim = track.unclaimedCount > 0;
                        const isClaimingThis = claimingType === track.type;

                        return (
                            <div key={track.type} className="grid grid-cols-[1fr_6rem] gap-2 items-end">
                                <div className="relative h-16 flex items-center cursor-pointer group" onClick={() => handleInspect(track)}>
                                    <div className="absolute top-[0.1em] left-[2.4rem] right-0 h-5 z-50 pointer-events-none">
                                        <GameText 
                                            text={track.type === 'card' ? 'new card' : `${track.nextRewardAmount} ${track.type}`} 
                                            baseFontSize={0.7} 
                                            className="text-white/90 font-black italic uppercase drop-shadow-[0_2px_4px_rgba(0,0,0,1)] tracking-tighter text-left"
                                        />
                                    </div>

                                    <div className="absolute left-0 z-40 transition-transform group-hover:scale-110 origin-center drop-shadow-xl">
                                        <HexBadge variant={variant} size="lg">
                                            <div className="relative w-full h-full overflow-visible">
                                                <div className={`absolute inset-0 flex items-center justify-center ${getScale(track.type)}`}>
                                                    <RewardIconGraphic 
                                                        type={track.type as any} 
                                                        size="lg" 
                                                        cardDef={track.nextRewardCardDef} 
                                                    />
                                                </div>
                                            </div>
                                        </HexBadge>
                                    </div>

                                    <div className={`absolute left-8 right-0 h-7 ${styles.bgTrack} border-2 ${styles.borderColor} rounded-full overflow-hidden z-10 shadow-[inset_0_2px_4px_rgba(0,0,0,0.5)] group-hover:border-white/40 transition-colors`}>
                                        <div className={`h-full bg-gradient-to-r ${styles.color} transition-all duration-1000 ease-out`} style={{ width: `${percent}%` }} />
                                        <div className="absolute inset-0 flex items-center justify-center pl-10 pr-2 py-0 pointer-events-none">
                                            <GameText 
                                                text={`${track.currentXP} / ${track.targetXP} XP`} 
                                                baseFontSize={0.9} 
                                                className="text-white font-black italic tracking-widest drop-shadow-md"
                                            />
                                        </div>
                                    </div>
                                </div>

                                <div className="flex flex-col items-center gap-1.5 pb-0.5">
                                    <SlantedButton 
                                        variant={canClaim ? variant : 'secondary'}
                                        size="xs"
                                        className={`!w-24 !h-9 shadow-lg ${(!canClaim || isClaimingThis) ? 'opacity-40 grayscale' : ''}`}
                                        disabled={!canClaim || isClaimingThis}
                                        onClick={(e) => { e.stopPropagation(); handleClaim(track.type); }}
                                    >
                                        {isClaimingThis ? "CLAIMING..." : `CLAIM\n${track.type === 'box' ? 'box' : track.type}`}
                                    </SlantedButton>
                                    <span className={`text-[0.45rem] font-black uppercase tracking-[0.2em] leading-none drop-shadow-sm whitespace-nowrap ${canClaim ? 'text-slate-300' : 'text-slate-600'}`}>
                                        {track.unclaimedCount} UNCLAIMED
                                    </span>
                                </div>
                            </div>
                        );
                    })}
                </div>

                {/* CLAIM ACTIVITY LOG SECTION */}
                <div className="pt-12 pb-12">
                    <div className="flex flex-col gap-4 mb-6 px-1">
                        <div className="flex items-center gap-3">
                            <h3 className="text-[0.65rem] font-black text-slate-500 uppercase tracking-[0.4em] whitespace-nowrap">Activity Log</h3>
                            <div className="flex-1 h-px bg-white/10" />
                        </div>

                        <div className="flex gap-1.5 overflow-x-auto scrollbar-hide py-1 px-1">
                            {(['all', 'credits', 'gold', 'booster', 'box', 'card'] as LogCategory[]).map(cat => (
                                <SlantedButton 
                                    key={cat}
                                    variant={logFilter === cat ? 'primary' : 'secondary'}
                                    size="xs"
                                    onClick={() => setLogFilter(cat)}
                                    className="!w-[14vw] max-w-[3.5rem] shadow-lg"
                                >
                                    {renderFilterIcon(cat)}
                                </SlantedButton>
                            ))}
                        </div>
                    </div>

                    <div className="space-y-2 opacity-90 scale-95 origin-top min-h-[10rem]">
                        {filteredLog.length > 0 ? (
                            <>
                                <div className="pb-2 text-center">
                                    <span className="text-[0.55rem] font-bold text-slate-300 uppercase tracking-[0.2em]">
                                        Showing latest 500 entries
                                    </span>
                                </div>
                                {filteredLog.map((item) => (
                                    <ActivityLogItem key={item.id} item={item} />
                                ))}
                            </>
                        ) : (
                            <div className="h-24 flex items-center justify-center border border-dashed border-white/10 rounded-xl bg-white/5">
                                <span className="text-[0.6rem] font-black text-slate-700 uppercase tracking-[0.4em]">Archive Empty</span>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

import React, { useMemo, useState } from 'react';
import { StandardHeader } from '../ui/StandardHeader';
import { ScreenKey, ActivityLogEntry, ProgressionRewardType, ProgressionTrack } from '../../types';
import { useUser } from '../../contexts/UserContext';
import { RewardIconGraphic } from '../ui/RewardItemVisual';
import { GameText } from '../ui/GameText';
import { HexBadge } from '../ui/HexBadge';
import { SlantedButton } from '../ui/SlantedButton';
import { CreditIcon, GoldIcon, CardIcon, BoosterIcon, OmegaBoxIcon } from '../../components/ui/CurrencyIcons';

type LogCategory = 'all' | 'credits' | 'gold' | 'booster' | 'box' | 'card';

const ActivityLogItem: React.FC<{ item: ActivityLogEntry }> = ({ item }) => {
    let iconScale = 'scale-[1.82]'; 
    if (item.type === 'card') iconScale = 'scale-75';
    else if (item.type === 'credits' || item.type === 'gold') iconScale = 'scale-[1.94]';

    return (
        <div className="flex items-center justify-between py-1 px-3 bg-slate-800/80 border border-slate-500 rounded-lg shadow-sm hover:border-slate-400 transition-colors cursor-default group">
            <div className="flex items-center gap-3">
                <div className="w-12 h-12 flex items-center justify-center overflow-visible">
                    <div className={iconScale}>
                        <RewardIconGraphic type={item.type as any} size="sm" cardDef={item.cardDef} />
                    </div>
                </div>
                <div>
                    <div className="font-black text-[0.8rem] tracking-tight text-white uppercase italic leading-tight">{item.title}</div>
                    <div className="text-[0.6rem] text-slate-300/80 font-bold uppercase tracking-widest mt-0.5">
                        {item.type === 'card' ? 'Unit Unlocked' : 'Manifest Claim'}
                    </div>
                </div>
            </div>
            <div className="text-right flex flex-col items-end">
                 <div className="text-[0.75rem] font-black text-white uppercase tracking-tighter tabular-nums leading-none mb-1">{item.date}</div>
                 <div className="text-[0.65rem] font-bold text-slate-300/80 uppercase tracking-widest tabular-nums">{item.time}</div>
            </div>
        </div>
    );
};

export const ProgressionScreen: React.FC<{ onNavigate: (screen: ScreenKey) => void }> = ({ onNavigate }) => {
    const { user, progressionData, activityLog, isProgressionLoading, claimProgressionReward, inspect } = useUser();
    const [logFilter, setLogFilter] = useState<LogCategory>('all');
    const [claimingType, setClaimingType] = useState<ProgressionRewardType | null>(null);

    const filteredLog = useMemo(() => {
        const base = logFilter === 'all' ? activityLog : activityLog.filter(item => item.type === logFilter);
        return base.slice(0, 500);
    }, [activityLog, logFilter]);

    const nextHero = useMemo(() => {
        if (!progressionData) return null;
        return [...progressionData.tracks].sort((a, b) => (a.targetXP - a.currentXP) - (b.targetXP - b.currentXP))[0];
    }, [progressionData]);

    const handleInspect = (track: ProgressionTrack) => {
        inspect({
            type: track.type === 'box' ? 'box' : 'level_info',
            level: user.level + (track.targetXP - track.currentXP),
            rewardType: track.type,
            rewardAmount: track.nextRewardAmount,
            cardDef: track.nextRewardCardDef,
            boxType: 'MEGA',
            title: track.label,
            description: 'Acquired through progression.'
        });
    };

    const handleClaim = async (type: ProgressionRewardType) => {
        if (claimingType) return;
        setClaimingType(type);
        await claimProgressionReward(type);
        setClaimingType(null);
    };

    const getScale = (type: string) => {
        if (type === 'gold' || type === 'credits') return 'scale-[0.48]'; 
        if (type === 'booster') return 'scale-[0.68]'; 
        if (type === 'card') return 'scale-[0.60]'; 
        return 'scale-[1.0]';
    };

    const getVariant = (type: ProgressionRewardType) => {
        switch(type) {
            case 'booster': return 'success';
            case 'credits': return 'blue';
            case 'gold': return 'warning';
            case 'box': return 'primary';
            case 'card': return 'secondary';
            default: return 'secondary';
        }
    };

    const getColors = (type: ProgressionRewardType) => {
        switch(type) {
            case 'booster': return { color: 'from-emerald-400 to-emerald-600', bgTrack: 'bg-[#064e3b]', borderColor: 'border-emerald-400/50' };
            case 'credits': return { color: 'from-blue-400 to-blue-600', bgTrack: 'bg-[#1e3a8a]', borderColor: 'border-blue-400/50' };
            case 'gold': return { color: 'from-amber-400 to-amber-600', bgTrack: 'bg-[#78350f]', borderColor: 'border-amber-400/50' };
            case 'box': return { color: 'from-indigo-400 to-indigo-600', bgTrack: 'bg-[#1e1b4b]', borderColor: 'border-indigo-400/50' };
            case 'card': return { color: 'from-white to-slate-400', bgTrack: 'bg-[#334155]', borderColor: 'border-white/50' };
        }
    };

    const renderFilterIcon = (cat: LogCategory) => {
        switch(cat) {
            case 'all': return <span className="font-black text-[0.65rem] -skew-x-[9deg]">ALL</span>;
            case 'credits': return <CreditIcon size="sm" />;
            case 'gold': return <GoldIcon size="sm" />;
            case 'card': return <CardIcon size="sm" />;
            case 'box': return <OmegaBoxIcon size="sm" />;
            case 'booster': return <BoosterIcon size="sm" />;
            default: return null;
        }
    };

    if (!progressionData && isProgressionLoading) {
        return (
            <div className="w-full h-full flex flex-col items-center justify-center bg-slate-950">
                <div className="w-8 h-8 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mb-4" />
                <span className="text-[0.6rem] font-black text-indigo-400 uppercase tracking-[0.3em] animate-pulse">Syncing Sector Data...</span>
            </div>
        );
