import { api } from '../services/api';
import { CARDS } from '../constants';
import { generateInstanceId } from '../utils/id';

export type CollectionSortOption = 'Cost' | 'Power' | 'Name' | 'Newest';

interface BoxReward {
    type: 'box';
    boxType: 'MYSTERY' | 'MEGA';
    title: string;
    description: string;
}

export interface SeasonRewardInfo {
    type: 'level_info';
    level: number;
    rewardType: SeasonRewardType | ProgressionRewardType;
    rewardAmount: string | number;
    isClaimed?: boolean;
    cardDef?: CardDefinition;
}

interface InspectingCard {
    data: CardInstance | CardDefinition;
    borderOverride?: string;
}

interface UserContextType {
    user: UserProfile;
    // Store State
    storeData: StoreData | null;
    isStoreLoading: boolean;
    storeScrollTarget: string | null;
    setStoreScrollTarget: (id: string | null) => void;
    // Season Pass State
    seasonPassData: SeasonPassData | null;
    isSeasonLoading: boolean;
    syncSeasonPass: () => Promise<void>;
    debugSwitchSeason: () => Promise<void>; 
    // Progression State
    progressionData: ProgressionData | null;
    activityLog: ActivityLogEntry[];
    isProgressionLoading: boolean;
    syncProgression: (showLoading?: boolean) => Promise<void>;
    claimProgressionReward: (type: ProgressionRewardType) => Promise<boolean>;
    // Inspect State
    inspectingCard: InspectingCard | null;
    inspectingLocation: LocationDefinition | null;
    inspectingCurrency: { type: 'gold' | 'credits', amount: number } | null;
    inspectingBox: BoxReward | null;
    inspectingReward: SeasonRewardInfo | null;
    // Collection UI State
    collectionSort: CollectionSortOption;
    setCollectionSort: (s: CollectionSortOption) => void;
    collectionFilterSearch: string;
    setCollectionFilterSearch: (s: string) => void;
    collectionFilterTags: string[];
    toggleCollectionFilterTag: (tag: string) => void;
    // Actions
    addCredits: (amount: number) => void;
    spendCredits: (amount: number) => boolean;
    addGold: (amount: number) => void;
    spendGold: (amount: number) => boolean;
    addTokens: (amount: number) => void;
    setActiveDeck: (id: number) => Promise<void>;
    updateDeck: (deckId: number, cardIds: string[]) => void;
    upgradeCard: (cardId: string) => boolean;
    processPurchase: (offerId: string) => Promise<boolean>;
    syncStore: () => Promise<void>;
    // Inspector Methods
    inspect: (item: any, options?: { borderOverride?: string }) => void;
    closeInspector: () => void;
    // Derived
    activeDeck: string[];
}

const UserContext = createContext<UserContextType | null>(null);

export const UserProvider: React.FC<{ children: ReactNode; initialUser: UserProfile }> = ({ children, initialUser }) => {
    const [user, setUser] = useState<UserProfile>(initialUser);
    const [storeData, setStoreData] = useState<StoreData | null>(null);
    const [isStoreLoading, setIsStoreLoading] = useState(false);
    const [storeScrollTarget, setStoreScrollTarget] = useState<string | null>(null);
    const [seasonPassData, setSeasonPassData] = useState<SeasonPassData | null>(null);
    const [isSeasonLoading, setIsSeasonLoading] = useState(false);

    // Progression State
    const [progressionData, setProgressionData] = useState<ProgressionData | null>(null);
    const [activityLog, setActivityLog] = useState<ActivityLogEntry[]>([]);
    const [isProgressionLoading, setIsProgressionLoading] = useState(false);

    const [inspectingCard, setInspectingCard] = useState<InspectingCard | null>(null);
    const [inspectingLocation, setInspectingLocation] = useState<LocationDefinition | null>(null);
    const [inspectingCurrency, setInspectingCurrency] = useState<{ type: 'gold' | 'credits', amount: number } | null>(null);
    const [inspectingBox, setInspectingBox] = useState<BoxReward | null>(null);
    const [inspectingReward, setInspectingReward] = useState<SeasonRewardInfo | null>(null);
    const [collectionSort, setCollectionSort] = useState<CollectionSortOption>('Cost');
    const [collectionFilterSearch, setCollectionFilterSearch] = useState('');
    const [collectionFilterTags, setCollectionFilterTags] = useState<string[]>([]);

    const toggleCollectionFilterTag = useCallback((tag: string) => {
        setCollectionFilterTags(prev => prev.includes(tag) ? prev.filter(t => t !== tag) : [...prev, tag]);
    }, []);

    const syncSeasonPass = useCallback(async () => {
        setIsSeasonLoading(true);
        try {
            const data = await api.getSeasonPass(user);
            setSeasonPassData(data);
        } catch (e) {
            console.error("Season Sync Failed", e);
        } finally {
            setIsSeasonLoading(false);
        }
    }, [user]);

    const syncProgression = useCallback(async (showLoading = false) => {
        if (showLoading) setIsProgressionLoading(true);
        try {
            const data = await api.getProgression(user);
            const logs = await api.getActivityLog();
            setProgressionData(data);
            setActivityLog(logs);
        } catch (e) {
            console.error("Progression Sync Failed", e);
        } finally {
            setIsProgressionLoading(false);
        }
    }, [user]);

    const claimProgressionReward = async (type: ProgressionRewardType): Promise<boolean> => {
        try {
            // Atomic API call
            const result = await api.claimProgressionReward(user, type);
            if (result.success && result.updatedProfile) {
                audio.play('sfx_victory');

                // Simultaneous update of all relevant state slices
                setUser(result.updatedProfile);
                if (result.progressionData) setProgressionData(result.progressionData);
                if (result.activityLog) setActivityLog(result.activityLog);

                return true;
            }
        } catch (e) {
            console.error("Claim failed", e);
        }
        return false;
    };

    const debugSwitchSeason = useCallback(async () => {
        await api.debugNextSeason();
        await syncSeasonPass();
    }, [syncSeasonPass]);

    const syncStore = useCallback(async (showLoading = false) => {
        if (showLoading) setIsStoreLoading(true);
        try {
            const data = await api.getStoreOffers(user);
            setStoreData(data);
        } catch (e) {
            console.error("Store Sync Failed", e);
        } finally {
            setIsStoreLoading(false);
        }
    }, [user]);

    // Initial background sync for store and season pass (the user is already provided)
    useEffect(() => {
        syncStore(true);
        syncSeasonPass();
        syncProgression(true);
        let timeout: any;
        const poll = () => {
            const delay = (storeData?.refreshHintSeconds || 60) * 1000;
            timeout = setTimeout(async () => {
                await syncStore();
                poll();
            }, delay);
        };
        poll();
        return () => clearTimeout(timeout);
    }, [user.id, syncStore, syncSeasonPass, syncProgression]);

    const inspect = (item: any, options?: { borderOverride?: string }) => {
        if (!item) return; 
        audio.playUiClick();
        setInspectingCurrency(null); setInspectingCard(null); setInspectingLocation(null); setInspectingBox(null); setInspectingReward(null);
        if ('type' in item) {
            if (item.type === 'gold' || item.type === 'credits') setInspectingCurrency(item);
            else if (item.type === 'box') setInspectingBox(item);
            else if (item.type === 'level_info') setInspectingReward(item);
        } 
        else if (('instanceId' in item) || ('basePower' in item) || ('definitionId' in item)) setInspectingCard({ data: item, borderOverride: options?.borderOverride });
        else if ('description' in item) setInspectingLocation(item);
    };

    const closeInspector = () => { setInspectingCard(null); setInspectingLocation(null); setInspectingCurrency(null); setInspectingBox(null); setInspectingReward(null); };
    const addCredits = (amount: number) => { setUser(prev => ({ ...prev, credits: prev.credits + amount })); };
    const spendCredits = (amount: number): boolean => {
        if (user.credits >= amount) { setUser(prev => ({ ...prev, credits: prev.credits - amount })); return true; }
        return false;
    };
    const addGold = (amount: number) => { setUser(prev => ({ ...prev, gold: prev.gold + amount })); };
    const spendGold = (amount: number): boolean => {
        if (user.gold >= amount) { setUser(prev => ({ ...prev, gold: prev.gold - amount })); return true; }
        return false;
    };
    const addTokens = (amount: number) => { setUser(prev => ({ ...prev, tokens: prev.tokens + amount })); };
    const setActiveDeck = async (id: number) => {
        audio.playUiClick();
        try { const updatedUser = await api.updateActiveDeck(user, id); setUser(updatedUser); }
        catch (e) { console.error("Failed to update active deck on server:", e); }
    };
    const updateDeck = (deckId: number, cardIds: string[]) => {
        setUser(prev => ({
            ...prev, decks: { ...prev.decks, [deckId]: cardIds },
            deckStats: { ...prev.deckStats, [deckId]: { ...(prev.deckStats[deckId] || { conquestWinRate: 0, ladderWinRate: 0, conquestWins: 0, conquestTotal: 0, ladderWins: 0, ladderLosses: 0 }), lastModified: new Date().toISOString() } }
        }));
    };
    const upgradeCard = (cardId: string): boolean => {
        const currentRarity = user.cardRarities[cardId] || "Common";
        const rarityPath: CardRarity[] = ["Common", "Rare", "Epic", "Legendary"];
        const currentIndex = rarityPath.indexOf(currentRarity);
        if (currentIndex === -1 || currentIndex === rarityPath.length - 1) return false;
        const nextRarity = rarityPath[currentIndex + 1];
        const costMap: Record<string, number> = { "Rare": 100, "Epic": 400, "Legendary": 1000 };
        const cost = costMap[nextRarity];
        if (user.credits >= cost) {
            setUser(prev => ({ ...prev, credits: prev.credits - cost, level: prev.level + (currentIndex + 1), cardRarities: { ...prev.cardRarities, [cardId]: nextRarity } }));
            audio.play('sfx_victory'); return true;
        }
        return false;
    };
    const processPurchase = async (offerId: string): Promise<boolean> => {
        const transactionId = `txn_${generateInstanceId()}`;
        try {
            const response = await api.purchaseOffer(user, offerId, transactionId);
            if (response.success && response.updatedProfile) { audio.play('sfx_victory'); setUser(response.updatedProfile); return true; }
            else { audio.play('sfx_ui_hover'); return false; }
        } catch (err) { console.error("Network Exception:", err); return false; }
    };

    const activeDeck = useMemo(() => user.decks[user.activeDeckId] || [], [user.decks, user.activeDeckId]);

    return (
        <UserContext.Provider value={{ 
            user, storeData, isStoreLoading, storeScrollTarget, setStoreScrollTarget,
            seasonPassData, isSeasonLoading, syncSeasonPass, debugSwitchSeason,
            progressionData, activityLog, isProgressionLoading, syncProgression, claimProgressionReward,
            inspectingCard, inspectingLocation, inspectingCurrency, inspectingBox, inspectingReward,
            collectionSort, setCollectionSort, collectionFilterSearch, setCollectionFilterSearch,
            collectionFilterTags, toggleCollectionFilterTag,
            addCredits, spendCredits, addGold, spendGold, addTokens, setActiveDeck, updateDeck, upgradeCard, processPurchase, syncStore, inspect, closeInspector, activeDeck
        }}>{children}</UserContext.Provider>
    );
};

export const useUser = () => {
    const context = useContext(UserContext);
    if (!context) throw new Error('useUser must be used within a UserProvider');
    return context;
};

import React, { useEffect, useState } from 'react';
import { SlantedButton } from '../ui/SlantedButton';
import { GameText } from '../ui/GameText';
import { useUser } from '../../contexts/UserContext';
import { usePurchaseOffer } from '../../hooks/usePurchaseOffer';
import { CreditIcon, GoldIcon, TokenIcon } from '../ui/CurrencyIcons';

interface StoreResourceItemProps {
    type: 'gold' | 'credits' | 'tokens';
    amount: number;
    costLabel: string;
    costAmount?: number;
    costType: 'gold' | 'real' | 'free';
    offerId?: string;
    availableAt?: string;
}

export const StoreResourceItem: React.FC<StoreResourceItemProps> = ({ 
    type, amount, costLabel, costAmount, costType, offerId, availableAt 
}) => {
    const { user, spendGold, addCredits, addGold, addTokens, processPurchase, syncStore } = useUser();
    const [timeLeft, setTimeLeft] = useState<number>(0);

    const isFree = costType === 'free';
    const hasEnoughCurrency = isFree || costType === 'real' || (costType === 'gold' && user.gold >= (costAmount || 0));

    // Time-based locking (Daily rewards)
    useEffect(() => {
        if (!availableAt) return;
        const updateTimer = () => {
            const now = Date.now();
            const target = new Date(availableAt).getTime();
            const diff = Math.max(0, Math.floor((target - now) / 1000));
            setTimeLeft(diff);
        };
        updateTimer();
        const interval = setInterval(updateTimer, 1000);
        return () => clearInterval(interval);
    }, [availableAt]);

    const handleAction = async () => {
        if (!hasEnoughCurrency) {
            syncStore();
            return false;
        }

        // If an offerId is provided (especially for free items), use processPurchase 
        // to handle "Claimed" state persistence via the backend mock.
        if (offerId) {
            return await processPurchase(offerId);
        } else if (costType === 'gold' && costAmount) {
            if (spendGold(costAmount)) {
                if (type === 'credits') addCredits(amount);
                else if (type === 'tokens') addTokens(amount);
                else addGold(amount);
                return true;
            }
        } else if (costType === 'real') {
            if (type === 'gold') addGold(amount);
            else if (type === 'tokens') addTokens(amount);
            else addCredits(amount);
            return true;
        }
        return false;
    };

    const { status, holdProgress, isHolding, setHoldProgress, setIsHolding, executePurchase } = usePurchaseOffer({
        onPurchase: handleAction
    });

    const isLocked = timeLeft > 0;
    const isSuccess = status === 'success';
    const isProcessing = status === 'processing';

    // Persist "CLAIMED" state based on purchasedOfferIds in profile
    const hasBeenClaimed = offerId && user.purchasedOfferIds.includes(offerId);

    const getColors = () => {
        if (type === 'gold') return { text: 'text-amber-500', bg: 'bg-amber-400/30' };
        if (type === 'tokens') return { text: 'text-red-500', bg: 'bg-red-400/30' };
        return { text: 'text-blue-400', bg: 'bg-blue-400/30' };
    };

    const colors = getColors();

    return (
        <div className={`
            bg-gradient-to-b from-slate-800 via-slate-900 to-black border-2 transition-all duration-300 rounded p-2 flex flex-col items-center justify-between h-[10.5rem] relative overflow-hidden shadow-2xl
            ${(isSuccess || hasBeenClaimed) ? 'border-emerald-400 ring-2 ring-emerald-500/50 bg-emerald-950' : 'border-slate-700'}
        `}>
            {/* Success Flash */}
            {isSuccess && <div className="absolute inset-0 bg-white/20 animate-pulse z-40 pointer-events-none" />}

            {/* Hold Progress Bar Overlay */}
            {holdProgress > 0 && status === 'idle' && !isLocked && !hasBeenClaimed && (
                <div 
                    className={`absolute inset-y-0 left-0 z-0 pointer-events-none ${colors.bg}`}
                    style={{ width: `${holdProgress}%` }}
                />
            )}

            {/* Amount & Label */}
            <div className="relative z-10 text-center w-full px-1">
                <div className="h-6 w-full mb-0.5">
                    <GameText 
                        text={amount.toLocaleString()} 
                        baseFontSize={1.1} 
                        className="text-white drop-shadow-md"
                    />
                </div>
                <div className={`text-[0.45rem] font-black uppercase tracking-[0.2em] leading-none ${colors.text}`}>
                    {type}
                </div>
            </div>

            {/* Resource Icon Visual */}
            <div className="relative z-10 flex-1 flex items-center justify-center">
                <div className={`
                    w-12 h-12 rounded-full flex items-center justify-center border-2 transition-all duration-500
                    ${(isSuccess || hasBeenClaimed) ? 'bg-emerald-500 border-emerald-300 scale-110 shadow-[0_0_20px_rgba(16,185,129,0.8)]' : 'bg-slate-900 border-slate-700'}
                `}>
                    {(isSuccess || hasBeenClaimed) ? (
                        <svg className="w-7 h-7 text-white animate-pop" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" /></svg>
                    ) : (
                        type === 'gold' ? <GoldIcon size="md" /> : (type === 'tokens' ? <TokenIcon size="md" /> : <CreditIcon size="md" />)
                    )}
                </div>
            </div>

            {/* Bottom Status / Timer / Button */}
            <div className="w-full relative z-10">
                <div className="h-3 flex items-center justify-center mb-0.5 overflow-visible">
                    {isHolding && status === 'idle' && !isLocked && !hasBeenClaimed && (
                        <span className="text-[0.45rem] font-black text-white uppercase tracking-wider animate-pulse drop-shadow-[0_2px_2px_rgba(0,0,0,1)] whitespace-nowrap">Hold to acquire</span>
                    )}
                    {isProcessing && (
                        <span className="text-[0.45rem] font-black text-white animate-pulse uppercase tracking-wider drop-shadow-[0_2px_2px_rgba(0,0,0,1)] whitespace-nowrap">Processing...</span>
                    )}
                    {(isSuccess || hasBeenClaimed) && (
                        <span className="text-[0.45rem] font-black text-white animate-bounce uppercase tracking-wider drop-shadow-[0_2px_2px_rgba(0,0,0,1)] whitespace-nowrap">Acquired!</span>
                    )}
                </div>

                {isLocked ? (
                    <div className="h-8 w-full bg-slate-900 border border-slate-700 rounded flex items-center justify-center gap-1.5 grayscale opacity-60">
                         <svg className="w-2.5 h-2.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                         <span className="text-[0.6rem] font-black tabular-nums">{Math.floor(timeLeft / 60)}:{(timeLeft % 60).toString().padStart(2, '0')}</span>
                    </div>
                ) : (
                    <SlantedButton 
                        variant={(isSuccess || hasBeenClaimed) ? 'success' : (type === 'gold' ? 'primary' : (type === 'tokens' ? 'danger' : 'blue'))} 
                        size="sm" 
                        fullWidth
                        holdDuration={(isFree || hasBeenClaimed) ? 0 : 800}
                        onHoldChange={setIsHolding}
                        onProgressChange={setHoldProgress}
                        onClick={executePurchase}
                        disabled={isProcessing || isSuccess || !!hasBeenClaimed}
                    >
                        {(isSuccess || hasBeenClaimed) ? 'READY' : costLabel}
                    </SlantedButton>
                )}
            </div>
        </div>
    );
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { StandardHeader } from '../ui/StandardHeader';
import { StoreResourceItem } from '../store/StoreResourceItem';
import { StoreSection } from '../store/StoreSection';
import { DailyOfferCard } from '../store/DailyOfferCard';
import { StoreOfferDetailOverlay } from '../store/StoreOfferDetailOverlay';
import { StoreOffer } from '../../types';
import { useUser } from '../../contexts/UserContext';

export const StoreScreen: React.FC = () => {
    const { storeData, isStoreLoading, storeScrollTarget, setStoreScrollTarget } = useUser();
    const [selectedOffer, setSelectedOffer] = useState<StoreOffer | null>(null);
    const scrollContainerRef = useRef<HTMLDivElement>(null);

    const handleJumpToSection = useCallback((id: string) => {
        const el = document.getElementById(id);
        const container = scrollContainerRef.current;
        if (el && container) {
            const targetTop = el.offsetTop - 8;
            container.scrollTo({ 
                top: targetTop, 
                behavior: 'smooth' 
            });
        }
    }, []);

    useEffect(() => {
        if (storeScrollTarget) {
            const t = setTimeout(() => {
                handleJumpToSection(storeScrollTarget);
                setStoreScrollTarget(null);
            }, 150);
            return () => clearTimeout(t);
        }
    }, [storeScrollTarget, setStoreScrollTarget, handleJumpToSection]);

    const offers = storeData?.offers || [];
    const dailyFreeCredits = offers.find(o => o.id === 'daily_free_credits');
    const dailyFreeTokens = offers.find(o => o.id === 'token_50_free');

    return (
        <div className="w-full h-full flex flex-col bg-transparent overflow-hidden relative">
            <StandardHeader 
                title="Store" 
                showCurrency={true}
                onCreditClick={() => handleJumpToSection('store-credits')}
                onGoldClick={() => handleJumpToSection('store-gold')}
                onTokenClick={() => handleJumpToSection('store-tokens')}
            />

            <div 
                ref={scrollContainerRef}
                className="flex-1 overflow-y-auto p-4 pb-32 space-y-10 relative"
            >
                {/* 1. FEATURED */}
                <StoreSection id="store-featured" title="Featured" colorClass="text-indigo-400">
                    <div className="space-y-4">
                        {offers.filter(o => o.category === 'featured').map(offer => (
                            <DailyOfferCard 
                                key={offer.id}
                                title={offer.title}
                                description={offer.description}
                                price={offer.price}
                                discount={offer.discountLabel}
                                backgroundImage={offer.imageUrl}
                                onClick={() => setSelectedOffer(offer)}
                            />
                        ))}
                    </div>
                </StoreSection>

                {/* 2. CREDITS */}
                <StoreSection id="store-credits" title="Credits" colorClass="text-blue-400">
                    <div className="grid grid-cols-3 gap-2">
                        <StoreResourceItem 
                            type="credits"
                            amount={25}
                            costLabel="FREE"
                            costType="free"
                            offerId="daily_free_credits"
                            availableAt={dailyFreeCredits?.availableAt}
                        />
                        <StoreResourceItem type="credits" amount={500} costLabel={`400\nGOLD`} costAmount={400} costType="gold" />
                        <StoreResourceItem type="credits" amount={1500} costLabel={`1200\nGOLD`} costAmount={1200} costType="gold" />
                    </div>
                </StoreSection>

                {/* 3. GOLD */}
                <StoreSection id="store-gold" title="Gold" colorClass="text-amber-400">
                    <div className="grid grid-cols-3 gap-2">
                        <StoreResourceItem type="gold" amount={300} costLabel="$4.99" costType="real" />
                        <StoreResourceItem type="gold" amount={700} costLabel="$9.99" costType="real" />
                        <StoreResourceItem type="gold" amount={1450} costLabel="$19.99" costType="real" />
                        <StoreResourceItem type="gold" amount={2600} costLabel="$34.99" costType="real" />
                        <StoreResourceItem type="gold" amount={3850} costLabel="$49.99" costType="real" />
                        <StoreResourceItem type="gold" amount={8000} costLabel="$99.99" costType="real" />
                    </div>
                </StoreSection>

                {/* 4. TOKENS */}
                <StoreSection id="store-tokens" title="Tokens" colorClass="text-red-400">
                    <div className="grid grid-cols-3 gap-2">
                        <StoreResourceItem 
                            type="tokens" 
                            amount={50} 
                            costLabel="FREE" 
                            costType="free" 
                            offerId="token_50_free"
                            availableAt={dailyFreeTokens?.availableAt}
                        />
                        <StoreResourceItem 
                            type="tokens" 
                            amount={1000} 
                            costLabel={`1300\nGOLD`} 
                            costAmount={1300} 
                            costType="gold" 
                            offerId="tokens_1000_gold"
                        />
                        <StoreResourceItem 
                            type="tokens" 
                            amount={2500} 
                            costLabel={`3250\nGOLD`} 
                            costAmount={3250} 
                            costType="gold" 
                            offerId="tokens_2500_gold"
                        />
                        <StoreResourceItem 
                            type="tokens" 
                            amount={5000} 
                            costLabel={`6500\nGOLD`} 
                            costAmount={6500} 
                            costType="gold" 
                            offerId="tokens_5000_gold"
                        />
                        <StoreResourceItem 
                            type="tokens" 
                            amount={8000} 
                            costLabel={`10.4k\nGOLD`} 
                            costAmount={10400} 
                            costType="gold" 
                            offerId="tokens_8000_gold"
                        />
                        <StoreResourceItem 
                            type="tokens" 
                            amount={12000} 
                            costLabel={`15.6k\nGOLD`} 
                            costAmount={15600} 
                            costType="gold" 
                            offerId="tokens_12000_gold"
                        />
                    </div>
                </StoreSection>

                <div className="text-center text-[0.55rem] font-bold text-white/10 py-6 uppercase tracking-[0.5em]">
                    End of Transmissions
                </div>
            </div>

            {selectedOffer && (
                <StoreOfferDetailOverlay 
                    offer={selectedOffer} 
                    onClose={() => setSelectedOffer(null)} 
                />
            )}
        </div>
    );
};

import React, { useEffect, useState } from 'react';
import { SlantedButton } from '../ui/SlantedButton';
import { GameText } from '../ui/GameText';
import { useUser } from '../../contexts/UserContext';
import { usePurchaseOffer } from '../../hooks/usePurchaseOffer';
import { CreditIcon, GoldIcon, TokenIcon } from '../ui/CurrencyIcons';

interface StoreResourceItemProps {
    type: 'gold' | 'credits' | 'tokens';
    amount: number;
    costLabel: string;
    costAmount?: number;
    costType: 'gold' | 'real' | 'free';
    offerId?: string;
    availableAt?: string;
}

export const StoreResourceItem: React.FC<StoreResourceItemProps> = ({ 
    type, amount, costLabel, costAmount, costType, offerId, availableAt 
}) => {
    const { user, spendGold, addCredits, addGold, addTokens, processPurchase, syncStore } = useUser();
    const [timeLeft, setTimeLeft] = useState<number>(0);

    const isFree = costType === 'free';
    const hasEnoughCurrency = isFree || costType === 'real' || (costType === 'gold' && user.gold >= (costAmount || 0));

    // Time-based locking (Daily rewards)
    useEffect(() => {
        if (!availableAt) return;
        const updateTimer = () => {
            const now = Date.now();
            const target = new Date(availableAt).getTime();
            const diff = Math.max(0, Math.floor((target - now) / 1000));
            setTimeLeft(diff);
        };
        updateTimer();
        const interval = setInterval(updateTimer, 1000);
        return () => clearInterval(interval);
    }, [availableAt]);

    const handleAction = async () => {
        if (!hasEnoughCurrency) {
            syncStore();
            return false;
        }

        // If an offerId is provided (especially for free items), use processPurchase 
        // to handle "Claimed" state persistence via the backend mock.
        if (offerId) {
            return await processPurchase(offerId);
        } else if (costType === 'gold' && costAmount) {
            if (spendGold(costAmount)) {
                if (type === 'credits') addCredits(amount);
                else if (type === 'tokens') addTokens(amount);
                else addGold(amount);
                return true;
            }
        } else if (costType === 'real') {
            if (type === 'gold') addGold(amount);
            else if (type === 'tokens') addTokens(amount);
            else addCredits(amount);
            return true;
        }
        return false;
    };

    const { status, holdProgress, isHolding, setHoldProgress, setIsHolding, executePurchase } = usePurchaseOffer({
        onPurchase: handleAction
    });

    const isLocked = timeLeft > 0;
    const isSuccess = status === 'success';
    const isProcessing = status === 'processing';

    // Persist "CLAIMED" state based on purchasedOfferIds in profile
    const hasBeenClaimed = offerId && user.purchasedOfferIds.includes(offerId);

    const getColors = () => {
        if (type === 'gold') return { text: 'text-amber-500', bg: 'bg-amber-400/30', accent: 'text-amber-400' };
        if (type === 'tokens') return { text: 'text-red-500', bg: 'bg-red-400/30', accent: 'text-red-400' };
