    const [inspectingLocation, setInspectingLocation] = useState<LocationDefinition | null>(null);
    const [inspectingCurrency, setInspectingCurrency] = useState<{ type: 'gold' | 'credits', amount: number } | null>(null);
    const [inspectingBox, setInspectingBox] = useState<BoxReward | null>(null);
    const [inspectingReward, setInspectingReward] = useState<SeasonRewardInfo | null>(null);
    const [collectionSort, setCollectionSort] = useState<CollectionSortOption>('Cost');
    const [collectionFilterSearch, setCollectionFilterSearch] = useState('');
    const [collectionFilterTags, setCollectionFilterTags] = useState<string[]>([]);

    const toggleCollectionFilterTag = useCallback((tag: string) => {
        setCollectionFilterTags(prev => prev.includes(tag) ? prev.filter(t => t !== tag) : [...prev, tag]);
    }, []);

    const syncSeasonPass = useCallback(async () => {
        setIsSeasonLoading(true);
        try {
            const data = await api.getSeasonPass(user);
            setSeasonPassData(data);
        } catch (e) {
            console.error("Season Sync Failed", e);
        } finally {
            setIsSeasonLoading(false);
        }
    }, [user]);

    const syncProgression = useCallback(async (showLoading = false) => {
        if (showLoading) setIsProgressionLoading(true);
        try {
            const data = await api.getProgression(user);
            const logs = await api.getActivityLog();
            setProgressionData(data);
            setActivityLog(logs);
        } catch (e) {
            console.error("Progression Sync Failed", e);
        } finally {
            setIsProgressionLoading(false);
        }
    }, [user]);

    const claimProgressionReward = async (type: ProgressionRewardType): Promise<boolean> => {
        try {
            const result = await api.claimProgressionReward(user, type);
            if (result.success && result.updatedProfile) {
                // Instant claim sound for direct progression rewards
                audio.play('sfx_victory');
                setUser(result.updatedProfile);
                if (result.progressionData) setProgressionData(result.progressionData);
                if (result.activityLog) setActivityLog(result.activityLog);
                return true;
            }
        } catch (e) {
            console.error("Claim failed", e);
        }
        return false;
    };

    const debugSwitchSeason = useCallback(async () => {
        await api.debugNextSeason();
        await syncSeasonPass();
    }, [syncSeasonPass]);

    const syncStore = useCallback(async (showLoading = false) => {
        if (showLoading) setIsStoreLoading(true);
        try {
            const data = await api.getStoreOffers(user);
            setStoreData(data);
        } catch (e) {
            console.error("Store Sync Failed", e);
        } finally {
            setIsStoreLoading(false);
        }
    }, [user]);

    useEffect(() => {
        syncStore(true);
        syncSeasonPass();
        syncProgression(true);
        let timeout: any;
        const poll = () => {
            const delay = (storeData?.refreshHintSeconds || 60) * 1000;
            timeout = setTimeout(async () => {
                await syncStore();
                poll();
            }, delay);
        };
        poll();
        return () => clearTimeout(timeout);
    }, [user.id, syncStore, syncSeasonPass, syncProgression]);

    const inspect = (item: any, options?: { borderOverride?: string }) => {
        if (!item) return; 
        audio.playUiClick();
        setInspectingCurrency(null); setInspectingCard(null); setInspectingLocation(null); setInspectingBox(null); setInspectingReward(null);
        if ('type' in item) {
            if (item.type === 'gold' || item.type === 'credits') setInspectingCurrency(item);
            else if (item.type === 'box') setInspectingBox(item);
            else if (item.type === 'level_info') setInspectingReward(item);
        } 
        else if (('instanceId' in item) || ('basePower' in item) || ('definitionId' in item)) setInspectingCard({ data: item, borderOverride: options?.borderOverride });
        else if ('description' in item) setInspectingLocation(item);
    };

    const closeInspector = () => { setInspectingCard(null); setInspectingLocation(null); setInspectingCurrency(null); setInspectingBox(null); setInspectingReward(null); };
    const addCredits = (amount: number) => { setUser(prev => ({ ...prev, credits: prev.credits + amount })); };
    const spendCredits = (amount: number): boolean => {
        if (user.credits >= amount) { setUser(prev => ({ ...prev, credits: prev.credits - amount })); return true; }
        return false;
    };
    const addGold = (amount: number) => { setUser(prev => ({ ...prev, gold: prev.gold + amount })); };
    const spendGold = (amount: number): boolean => {
        if (user.gold >= amount) { setUser(prev => ({ ...prev, gold: prev.gold - amount })); return true; }
        return false;
    };
    const addTokens = (amount: number) => { setUser(prev => ({ ...prev, tokens: prev.tokens + amount })); };
    const setActiveDeck = async (id: number) => {
        audio.playUiClick();
        try { const updatedUser = await api.updateActiveDeck(user, id); setUser(updatedUser); }
        catch (e) { console.error("Failed to update active deck on server:", e); }
    };
    const updateDeck = (deckId: number, cardIds: string[]) => {
        setUser(prev => ({
            ...prev, decks: { ...prev.decks, [deckId]: cardIds },
            deckStats: { ...prev.deckStats, [deckId]: { ...(prev.deckStats[deckId] || { conquestWinRate: 0, ladderWinRate: 0, conquestWins: 0, conquestTotal: 0, ladderWins: 0, ladderLosses: 0 }), lastModified: new Date().toISOString() } }
        }));
    };
    const upgradeCard = (cardId: string): boolean => {
        const currentRarity = user.cardRarities[cardId] || "Common";
        const rarityPath: CardRarity[] = ["Common", "Rare", "Epic", "Legendary"];
        const currentIndex = rarityPath.indexOf(currentRarity);
        if (currentIndex === -1 || currentIndex === rarityPath.length - 1) return false;
        const nextRarity = rarityPath[currentIndex + 1];
        const costMap: Record<string, number> = { "Rare": 100, "Epic": 400, "Legendary": 1000 };
        const cost = costMap[nextRarity];
        if (user.credits >= cost) {
            setUser(prev => ({ ...prev, credits: prev.credits - cost, level: prev.level + (currentIndex + 1), cardRarities: { ...prev.cardRarities, [cardId]: nextRarity } }));
            audio.play('sfx_victory'); return true;
        }
        return false;
    };

    /**
     * Authoritative Purchase Flow
     * Blocks global state commitment until the theatrical window has passed.
     */
    const processPurchase = async (offerId: string, options?: { visualDelay?: number }): Promise<boolean> => {
        const transactionId = `txn_${generateInstanceId()}`;
        try {
            // 1. Authoritative Server Call
            const response = await api.purchaseOffer(user, offerId, transactionId);

            if (response.success && response.updatedProfile) { 
                // 2. State Suspension: 
                // We have the new profile in memory, but we don't apply it yet.
                // We wait for the theatrical "Authorizing" pulse to finish.
                if (options?.visualDelay) {
                    await new Promise(resolve => setTimeout(resolve, options.visualDelay));
                }

                // 3. Atomic Commitment:
                // The header numbers update and the UI success flag flip in the same render batch.
                setUser(response.updatedProfile); 
                return true; 
            }
            else { return false; }
        } catch (err) { console.error("Network Exception:", err); return false; }
    };

    const activeDeck = useMemo(() => user.decks[user.activeDeckId] || [], [user.decks, user.activeDeckId]);

    return (
        <UserContext.Provider value={{ 
            user, storeData, isStoreLoading, storeScrollTarget, setStoreScrollTarget,
            seasonPassData, isSeasonLoading, syncSeasonPass, debugSwitchSeason,
            progressionData, activityLog, isProgressionLoading, syncProgression, claimProgressionReward,
            inspectingCard, inspectingLocation, inspectingCurrency, inspectingBox, inspectingReward,
            collectionSort, setCollectionSort, collectionFilterSearch, setCollectionFilterSearch,
            collectionFilterTags, toggleCollectionFilterTag,
            addCredits, spendCredits, addGold, spendGold, addTokens, setActiveDeck, updateDeck, upgradeCard, processPurchase, syncStore, inspect, closeInspector, activeDeck
        }}>{children}</UserContext.Provider>
    );
};

export const useUser = () => {
    const context = useContext(UserContext);
    if (!context) throw new Error('useUser must be used within a UserProvider');
    return context;
};

import { useState, useCallback } from 'react';

export type PurchaseStatus = 'idle' | 'processing' | 'success' | 'error';

interface UsePurchaseOfferProps {
    onPurchase: () => Promise<boolean>;
    resetDelay?: number;
}

export const usePurchaseOffer = ({ 
    onPurchase, 
    resetDelay = 4000 
}: UsePurchaseOfferProps) => {
    const [status, setStatus] = useState<PurchaseStatus>('idle');
    const [holdProgress, setHoldProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);

    const executePurchase = useCallback(async () => {
        if (status !== 'idle') return;

        setStatus('processing');

        // The purchase call now internally handles the visual delay sync.
        // We strictly wait for it to resolve before showing the success UI.
        const success = await onPurchase();

        if (success) {
            // Once the context commits the new state, we flip to success immediately.
            setStatus('success');

            // Auto-reset button state after user sees results
            setTimeout(() => {
                setStatus('idle');
                setHoldProgress(0);
            }, resetDelay);
        } else {
            // Revert on failure
            setStatus('idle');
            setHoldProgress(0);
        }
    }, [onPurchase, status, resetDelay]);

    return {
        status,
        holdProgress,
        isHolding,
        setHoldProgress,
        setIsHolding,
        executePurchase
    };
};

import React, { useEffect, useState, useMemo } from 'react';
import { SlantedButton } from '../ui/SlantedButton';
import { GameText } from '../ui/GameText';
import { useUser } from '../../contexts/UserContext';
import { usePurchaseOffer } from '../../hooks/usePurchaseOffer';
import { CreditIcon, GoldIcon, TokenIcon } from '../ui/CurrencyIcons';
import { audio } from '../../services/audio';

interface StoreResourceItemProps {
    type: 'gold' | 'credits' | 'tokens';
    amount: number;
    costLabel: string;
    costAmount?: number;
    costType: 'gold' | 'real' | 'free';
    offerId?: string;
    availableAt?: string;
}

// Global visual timing constant for the "Authorizing" pulse phase
const SUCCESS_ANIMATION_DELAY = 800;

export const StoreResourceItem: React.FC<StoreResourceItemProps> = ({ 
    type, amount, costLabel, costAmount, costType, offerId, availableAt 
}) => {
    const { user, storeData, spendGold, addCredits, addGold, addTokens, processPurchase, syncStore } = useUser();
    const [timeLeft, setTimeLeft] = useState<number>(0);

    const isFree = costType === 'free';
    const hasEnoughCurrency = isFree || costType === 'real' || (costType === 'gold' && user.gold >= (costAmount || 0));

    const offerMeta = useMemo(() => {
        return storeData?.offers.find(o => o.id === offerId);
    }, [storeData, offerId]);

    useEffect(() => {
        if (!availableAt) return;
        const updateTimer = () => {
            const now = Date.now();
            const target = new Date(availableAt).getTime();
            const diff = Math.max(0, Math.floor((target - now) / 1000));
            setTimeLeft(diff);
        };
        updateTimer();
        const interval = setInterval(updateTimer, 1000);
        return () => clearInterval(interval);
    }, [availableAt]);

    const handleAction = async () => {
        if (!hasEnoughCurrency) {
            syncStore();
            return false;
        }

        if (offerId) {
            // We pass the visual delay to the context so it waits to update the numbers in the header
            return await processPurchase(offerId, { visualDelay: SUCCESS_ANIMATION_DELAY });
        } 

        // Manual fallbacks
        if (costType === 'gold' && costAmount) {
            if (spendGold(costAmount)) {
                if (type === 'credits') addCredits(amount);
                else if (type === 'tokens') addTokens(amount);
                else addGold(amount);
                return true;
            }
        } else if (costType === 'real') {
            if (type === 'gold') addGold(amount);
            else if (type === 'tokens') addTokens(amount);
            else addCredits(amount);
            return true;
        }
        return false;
    };

    const { status, holdProgress, isHolding, setHoldProgress, setIsHolding, executePurchase } = usePurchaseOffer({
        onPurchase: handleAction
    });

    const isLocked = timeLeft > 0;
    const isSuccess = status === 'success';
    const isProcessing = status === 'processing';

    // Play victory sound EXACTLY once when the isSuccess visual flag flips
    useEffect(() => {
        if (isSuccess) {
            audio.play('sfx_victory', 0.5);
        }
    }, [isSuccess]);

    const isPermanentlyClaimed = useMemo(() => {
        if (!offerId || !offerMeta?.isOneTime) return false;
        return user.purchasedOfferIds.includes(offerId);
    }, [user.purchasedOfferIds, offerId, offerMeta]);

    const getColors = () => {
        if (type === 'gold') return { text: 'text-amber-500', bg: 'bg-amber-400/30' };
        if (type === 'tokens') return { text: 'text-red-500', bg: 'bg-red-400/30' };
        return { text: 'text-blue-400', bg: 'bg-blue-400/30' };
    };

    const colors = getColors();
    const showSuccess = isSuccess || isPermanentlyClaimed;

    return (
        <div className={`
            bg-gradient-to-b from-slate-800 via-slate-900 to-black border-2 transition-all duration-300 rounded p-2 flex flex-col items-center justify-between h-[10.5rem] relative overflow-hidden shadow-2xl
            ${showSuccess ? 'border-emerald-400 ring-2 ring-emerald-500/50 bg-emerald-950' : 'border-slate-700'}
        `}>
            {/* Success Flash */}
            {isSuccess && <div className="absolute inset-0 bg-white/20 animate-pulse z-40 pointer-events-none" />}

            {/* Hold Progress Bar Overlay */}
            {holdProgress > 0 && status === 'idle' && !isLocked && !isPermanentlyClaimed && (
                <div 
                    className={`absolute inset-y-0 left-0 z-0 pointer-events-none ${colors.bg}`}
                    style={{ width: `${holdProgress}%` }}
                />
            )}

            {/* Amount & Label */}
            <div className="relative z-10 text-center w-full px-1">
                <div className="h-6 w-full mb-0.5">
                    <GameText 
                        text={amount.toLocaleString()} 
                        baseFontSize={1.1} 
                        className="text-white drop-shadow-md"
                    />
                </div>
                <div className={`text-[0.45rem] font-black uppercase tracking-[0.2em] leading-none ${colors.text}`}>
                    {type}
                </div>
            </div>

            {/* Resource Icon Visual */}
            <div className="relative z-10 flex-1 flex items-center justify-center">
                <div className={`
                    w-12 h-12 rounded-full flex items-center justify-center border-2 transition-all duration-500
                    ${showSuccess ? 'bg-emerald-500 border-emerald-300 scale-110 shadow-[0_0_20px_rgba(16,185,129,0.8)]' : 'bg-slate-900 border-slate-700'}
                `}>
                    {showSuccess ? (
                        <svg className="w-7 h-7 text-white animate-pop" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" /></svg>
                    ) : (
                        type === 'gold' ? <GoldIcon size="md" /> : (type === 'tokens' ? <TokenIcon size="md" /> : <CreditIcon size="md" />)
                    )}
                </div>
            </div>

            {/* Bottom Status / Timer / Button */}
            <div className="w-full relative z-10">
                <div className="h-3 flex items-center justify-center mb-0.5 overflow-visible">
                    {isHolding && status === 'idle' && !isLocked && !isPermanentlyClaimed ? (
                         <span className="text-[0.45rem] font-black text-white uppercase tracking-widest animate-pulse drop-shadow-[0_2px_2px_rgba(0,0,0,1)] whitespace-nowrap">Hold to Buy</span>
                    ) : isProcessing ? (
                         <span className="text-[0.45rem] font-black text-cyan-300 uppercase tracking-[0.3em] leading-none animate-pulse drop-shadow-[0_0_5px_rgba(34,211,238,0.8)] whitespace-nowrap">Syncing...</span>
                    ) : showSuccess ? (
                         <span className="text-[0.45rem] font-black text-emerald-400 uppercase tracking-[0.3em] leading-none animate-bounce drop-shadow-[0_0_5px_rgba(52,211,153,0.8)] whitespace-nowrap">Deposited</span>
                    ) : null}
                </div>

                {isLocked ? (
                    <div className="h-8 w-full bg-slate-900 border border-slate-700 rounded flex items-center justify-center gap-1.5 grayscale opacity-60">
                         <svg className="w-2.5 h-2.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                         <span className="text-[0.6rem] font-black tabular-nums">{Math.floor(timeLeft / 60)}:{(timeLeft % 60).toString().padStart(2, '0')}</span>
                    </div>
                ) : (
                    <SlantedButton 
                        variant={showSuccess ? 'success' : (type === 'gold' ? 'primary' : (type === 'tokens' ? 'danger' : 'blue'))} 
                        size="sm" 
                        fullWidth
                        holdDuration={(isFree || isPermanentlyClaimed) ? 0 : 800}
                        onHoldChange={setIsHolding}
                        onProgressChange={setHoldProgress}
                        onClick={executePurchase}
                        disabled={isProcessing || showSuccess}
                    >
                        {isProcessing ? 'AUTHORIZING' : (showSuccess ? 'SYNCED' : costLabel)}
                    </SlantedButton>
                )}
            </div>
        </div>
    );
};

import React, { createContext, useContext, useState, ReactNode, useEffect, useCallback, useMemo } from 'react';
import { UserProfile, StoreData, CardDefinition, CardInstance, LocationDefinition, CardRarity, SeasonPassData, SeasonRewardType, ProgressionData, ActivityLogEntry, ProgressionRewardType, PurchaseResponse } from '../types';
import { audio } from '../services/audio';
import { api } from '../services/api';
import { CARDS } from '../constants';
import { generateInstanceId } from '../utils/id';

export type CollectionSortOption = 'Cost' | 'Power' | 'Name' | 'Newest';

interface BoxReward {
    type: 'box';
    boxType: 'MYSTERY' | 'MEGA';
    title: string;
    description: string;
}

export interface SeasonRewardInfo {
    type: 'level_info';
    level: number;
    rewardType: SeasonRewardType | ProgressionRewardType;
    rewardAmount: string | number;
    isClaimed?: boolean;
    cardDef?: CardDefinition;
}

interface InspectingCard {
    data: CardInstance | CardDefinition;
    borderOverride?: string;
}

interface UserContextType {
    user: UserProfile;
    storeData: StoreData | null;
    isStoreLoading: boolean;
    storeScrollTarget: string | null;
    setStoreScrollTarget: (id: string | null) => void;
    seasonPassData: SeasonPassData | null;
    isSeasonLoading: boolean;
    syncSeasonPass: () => Promise<void>;
    debugSwitchSeason: () => Promise<void>; 
    progressionData: ProgressionData | null;
    activityLog: ActivityLogEntry[];
    isProgressionLoading: boolean;
    syncProgression: (showLoading?: boolean) => Promise<void>;

    // UI State
    inspectingCard: InspectingCard | null;
    inspectingLocation: LocationDefinition | null;
    inspectingCurrency: { type: 'gold' | 'credits', amount: number } | null;
    inspectingBox: BoxReward | null;
    inspectingReward: SeasonRewardInfo | null;
    collectionSort: CollectionSortOption;
    setCollectionSort: (s: CollectionSortOption) => void;
    collectionFilterSearch: string;
    setCollectionFilterSearch: (s: string) => void;
    collectionFilterTags: string[];
    toggleCollectionFilterTag: (tag: string) => void;

    // AUTHORITATIVE ACTIONS
    performSynchronizedAction: (apiCall: () => Promise<PurchaseResponse>, options?: { visualDelay?: number, sfx?: string }) => Promise<boolean>;
    syncStore: () => Promise<void>;

    // Inspector Methods
    inspect: (item: any, options?: { borderOverride?: string }) => void;
    closeInspector: () => void;
    activeDeck: string[];
}

const UserContext = createContext<UserContextType | null>(null);

export const UserProvider: React.FC<{ children: ReactNode; initialUser: UserProfile }> = ({ children, initialUser }) => {
    const [user, setUser] = useState<UserProfile>(initialUser);
    const [storeData, setStoreData] = useState<StoreData | null>(null);
    const [isStoreLoading, setIsStoreLoading] = useState(false);
    const [storeScrollTarget, setStoreScrollTarget] = useState<string | null>(null);
    const [seasonPassData, setSeasonPassData] = useState<SeasonPassData | null>(null);
    const [isSeasonLoading, setIsSeasonLoading] = useState(false);
    const [progressionData, setProgressionData] = useState<ProgressionData | null>(null);
    const [activityLog, setActivityLog] = useState<ActivityLogEntry[]>([]);
    const [isProgressionLoading, setIsProgressionLoading] = useState(false);

    const [inspectingCard, setInspectingCard] = useState<InspectingCard | null>(null);
    const [inspectingLocation, setInspectingLocation] = useState<LocationDefinition | null>(null);
    const [inspectingCurrency, setInspectingCurrency] = useState<{ type: 'gold' | 'credits', amount: number } | null>(null);
    const [inspectingBox, setInspectingBox] = useState<BoxReward | null>(null);
    const [inspectingReward, setInspectingReward] = useState<SeasonRewardInfo | null>(null);
    const [collectionSort, setCollectionSort] = useState<CollectionSortOption>('Cost');
    const [collectionFilterSearch, setCollectionFilterSearch] = useState('');
    const [collectionFilterTags, setCollectionFilterTags] = useState<string[]>([]);

    const toggleCollectionFilterTag = useCallback((tag: string) => {
        setCollectionFilterTags(prev => prev.includes(tag) ? prev.filter(t => t !== tag) : [...prev, tag]);
    }, []);

    const syncSeasonPass = useCallback(async () => {
        setIsSeasonLoading(true);
        try {
            const data = await api.getSeasonPass(user);
            setSeasonPassData(data);
        } catch (e) {
            console.error("Season Sync Failed", e);
        } finally {
            setIsSeasonLoading(false);
        }
    }, [user]);

    const syncProgression = useCallback(async (showLoading = false) => {
        if (showLoading) setIsProgressionLoading(true);
        try {
            const data = await api.getProgression(user);
            const logs = await api.getActivityLog();
            setProgressionData(data);
            setActivityLog(logs);
        } catch (e) {
            console.error("Progression Sync Failed", e);
        } finally {
            setIsProgressionLoading(false);
        }
    }, [user]);

    const syncStore = useCallback(async (showLoading = false) => {
        if (showLoading) setIsStoreLoading(true);
        try {
            const data = await api.getStoreOffers(user);
            setStoreData(data);
        } catch (e) {
            console.error("Store Sync Failed", e);
        } finally {
            setIsStoreLoading(false);
        }
    }, [user]);

    /**
     * UNIFIED SYNCHRONIZED ACTION ENGINE
     * Handles the generic: Request -> Wait for Animation -> Atomic Update pattern.
     */
    const performSynchronizedAction = async (
        apiCall: () => Promise<PurchaseResponse | any>, 
        options?: { visualDelay?: number, sfx?: string }
    ): Promise<boolean> => {
        try {
            // 1. Logic: Call server and get the full authoritative result
            const result = await apiCall();

            if (result.success && result.updatedProfile) {
                // 2. Suspension: Wait for visual delay (theatrical authorize phase)
                if (options?.visualDelay) {
                    await new Promise(resolve => setTimeout(resolve, options.visualDelay));
                }

                // 3. Commitment: Atomic profile update
                setUser(result.updatedProfile);

                // Update secondary states if returned
                if ('progressionData' in result && result.progressionData) setProgressionData(result.progressionData);
                if ('activityLog' in result && result.activityLog) setActivityLog(result.activityLog);

                // 4. Feedback: Trigger success audio perfectly in sync with the commit
                if (options?.sfx) {
                    audio.play(options.sfx as any, 0.5);
                } else {
                    audio.play('sfx_victory', 0.5);
                }

                return true;
            }
        } catch (err) {
            console.error("Synchronized Action Failed:", err);
        }
        return false;
    };

    useEffect(() => {
        syncStore(true);
        syncSeasonPass();
        syncProgression(true);
        let timeout: any;
        const poll = () => {
            const delay = (storeData?.refreshHintSeconds || 60) * 1000;
            timeout = setTimeout(async () => {
                await syncStore();
                poll();
            }, delay);
        };
        poll();
        return () => clearTimeout(timeout);
    }, [user.id, syncStore, syncSeasonPass, syncProgression]);

    const inspect = (item: any, options?: { borderOverride?: string }) => {
        if (!item) return; 
        audio.playUiClick();
        setInspectingCurrency(null); setInspectingCard(null); setInspectingLocation(null); setInspectingBox(null); setInspectingReward(null);
        if ('type' in item) {
            if (item.type === 'gold' || item.type === 'credits') setInspectingCurrency(item);
            else if (item.type === 'box') setInspectingBox(item);
            else if (item.type === 'level_info') setInspectingReward(item);
        } 
        else if (('instanceId' in item) || ('basePower' in item) || ('definitionId' in item)) setInspectingCard({ data: item, borderOverride: options?.borderOverride });
        else if ('description' in item) setInspectingLocation(item);
    };

    const closeInspector = () => { setInspectingCard(null); setInspectingLocation(null); setInspectingCurrency(null); setInspectingBox(null); setInspectingReward(null); };

    const activeDeck = useMemo(() => user.decks[user.activeDeckId] || [], [user.decks, user.activeDeckId]);

    return (
        <UserContext.Provider value={{ 
            user, storeData, isStoreLoading, storeScrollTarget, setStoreScrollTarget,
            seasonPassData, isSeasonLoading, syncSeasonPass, debugSwitchSeason,
            progressionData, activityLog, isProgressionLoading, syncProgression,
            inspectingCard, inspectingLocation, inspectingCurrency, inspectingBox, inspectingReward,
            collectionSort, setCollectionSort, collectionFilterSearch, setCollectionFilterSearch,
            collectionFilterTags, toggleCollectionFilterTag,
            performSynchronizedAction, syncStore, inspect, closeInspector, activeDeck
        }}>{children}</UserContext.Provider>
    );
};

export const useUser = () => {
    const context = useContext(UserContext);
    if (!context) throw new Error('useUser must be used within a UserProvider');
    return context;
};

import { useState, useCallback, useRef, useEffect } from 'react';

export type ActionStatus = 'idle' | 'processing' | 'success' | 'error';

interface UseSynchronizedActionProps {
    onAction: () => Promise<boolean>;
    holdDuration?: number;
    resetDelay?: number;
}

/**
 * useSynchronizedAction
 * Encapsulates the visual logic for a transaction.
 * Synchronizes component-local success state with context-level data commitment.
 */
export const useSynchronizedAction = ({ 
    onAction, 
    holdDuration = 0,
    resetDelay = 4000 
}: UseSynchronizedActionProps) => {
    const [status, setStatus] = useState<ActionStatus>('idle');
    const [holdProgress, setHoldProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);
    const timerRef = useRef<number | null>(null);

    const execute = useCallback(async () => {
        if (status !== 'idle') return;

        setStatus('processing');

        // The onAction call (performSynchronizedAction in Context) handles the delay internally.
        // It only resolves AFTER the theatrical window closes and the data is committed.
        const success = await onAction();

        if (success) {
            // Flip to success at the EXACT same time header updates and sound plays
            setStatus('success');

            // Auto-reset button state after user sees results
            setTimeout(() => {
                setStatus('idle');
                setHoldProgress(0);
            }, resetDelay);
        } else {
            // Revert on failure or insufficient funds
            setStatus('idle');
            setHoldProgress(0);
        }
    }, [onAction, status, resetDelay]);

    const startHold = useCallback(() => {
        if (status !== 'idle' || holdDuration <= 0) return;
        setIsHolding(true);
        const startTime = Date.now();

        timerRef.current = window.setInterval(() => {
            const elapsed = Date.now() - startTime;
            const p = Math.min((elapsed / holdDuration) * 100, 100);
            setHoldProgress(p);

            if (p >= 100) {
                cancelHold();
                execute();
            }
        }, 16);
    }, [status, holdDuration, execute]);

    const cancelHold = useCallback(() => {
        if (timerRef.current) clearInterval(timerRef.current);
        timerRef.current = null;
        setIsHolding(false);
        if (status === 'idle') setHoldProgress(0);
    }, [status]);

    useEffect(() => () => { if (timerRef.current) clearInterval(timerRef.current); }, []);

    return {
        status,
        holdProgress,
        isHolding,
        execute: holdDuration > 0 ? undefined : execute, // Direct click if no hold
        bind: {
            onPointerDown: startHold,
            onPointerUp: cancelHold,
            onPointerLeave: cancelHold
        }
    };
};

import React, { useEffect, useState, useMemo } from 'react';
import { SlantedButton } from '../ui/SlantedButton';
import { GameText } from '../ui/GameText';
import { useUser } from '../../contexts/UserContext';
import { useSynchronizedAction } from '../../hooks/useSynchronizedAction';
import { CreditIcon, GoldIcon, TokenIcon } from '../ui/CurrencyIcons';
import { api } from '../../services/api';

interface StoreResourceItemProps {
    type: 'gold' | 'credits' | 'tokens';
    amount: number;
    costLabel: string;
    costAmount?: number;
    costType: 'gold' | 'real' | 'free';
    offerId?: string;
    availableAt?: string;
}

const SUCCESS_WINDOW = 800; // Shared theatrical duration

export const StoreResourceItem: React.FC<StoreResourceItemProps> = ({ 
    type, amount, costLabel, costAmount, costType, offerId, availableAt 
}) => {
    const { user, storeData, performSynchronizedAction, syncStore } = useUser();
    const [timeLeft, setTimeLeft] = useState<number>(0);

    const isFree = costType === 'free';
    const hasFunds = isFree || costType === 'real' || (costType === 'gold' && user.gold >= (costAmount || 0));

    useEffect(() => {
        if (!availableAt) return;
        const updateTimer = () => {
            const now = Date.now();
            const target = new Date(availableAt).getTime();
            const diff = Math.max(0, Math.floor((target - now) / 1000));
            setTimeLeft(diff);
        };
        updateTimer();
        const interval = setInterval(updateTimer, 1000);
        return () => clearInterval(interval);
    }, [availableAt]);

    const { status, holdProgress, isHolding, execute, bind } = useSynchronizedAction({
        holdDuration: (isFree || costType === 'real') ? 0 : 800,
        onAction: async () => {
            if (!hasFunds) {
                syncStore();
                return false;
            }
            if (!offerId) return false;

            // Standard fetch call passed to centralized synchronizer
            return await performSynchronizedAction(
                () => api.purchaseOffer(user, offerId, `txn_${Math.random()}`),
                { visualDelay: SUCCESS_WINDOW }
            );
        }
    });

    const isLocked = timeLeft > 0;
    const isSuccess = status === 'success';
    const isProcessing = status === 'processing';

    const isPermanentlyClaimed = useMemo(() => {
        const offer = storeData?.offers.find(o => o.id === offerId);
        return offer?.isOneTime && user.purchasedOfferIds.includes(offerId || '');
    }, [user.purchasedOfferIds, offerId, storeData]);

    const showSuccess = isSuccess || isPermanentlyClaimed;
    const colors = type === 'gold' ? { text: 'text-amber-500', bg: 'bg-amber-400/30' } : (type === 'tokens' ? { text: 'text-red-500', bg: 'bg-red-400/30' } : { text: 'text-blue-400', bg: 'bg-blue-400/30' });

    return (
        <div 
            className={`bg-gradient-to-b from-slate-800 via-slate-900 to-black border-2 transition-all duration-300 rounded p-2 flex flex-col items-center justify-between h-[10.5rem] relative overflow-hidden shadow-2xl ${showSuccess ? 'border-emerald-400 ring-2 ring-emerald-500/50 bg-emerald-950' : 'border-slate-700'}`}
            {...(isFree || isLocked || isPermanentlyClaimed ? {} : bind)}
        >
            {isSuccess && <div className="absolute inset-0 bg-white/20 animate-pulse z-40 pointer-events-none" />}

            {holdProgress > 0 && status === 'idle' && !isLocked && !isPermanentlyClaimed && (
                <div className={`absolute inset-y-0 left-0 z-0 pointer-events-none ${colors.bg}`} style={{ width: `${holdProgress}%` }} />
            )}

            <div className="relative z-10 text-center w-full px-1">
                <div className="h-6 w-full mb-0.5">
                    <GameText text={amount.toLocaleString()} baseFontSize={1.1} className="text-white drop-shadow-md" />
                </div>
                <div className={`text-[0.45rem] font-black uppercase tracking-[0.2em] leading-none ${colors.text}`}>{type}</div>
            </div>

            <div className="relative z-10 flex-1 flex items-center justify-center">
                <div className={`w-12 h-12 rounded-full flex items-center justify-center border-2 transition-all duration-500 ${showSuccess ? 'bg-emerald-500 border-emerald-300 scale-110 shadow-[0_0_20px_rgba(16,185,129,0.8)]' : 'bg-slate-900 border-slate-700'}`}>
                    {showSuccess ? (
                        <svg className="w-7 h-7 text-white animate-pop" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" /></svg>
                    ) : (
                        type === 'gold' ? <GoldIcon size="md" /> : (type === 'tokens' ? <TokenIcon size="md" /> : <CreditIcon size="md" />)
                    )}
                </div>
            </div>

            <div className="w-full relative z-10">
                <div className="h-3 flex items-center justify-center mb-0.5 overflow-visible">
                    {isHolding && !isLocked && !isPermanentlyClaimed ? (
                         <span className="text-[0.45rem] font-black text-white uppercase tracking-widest animate-pulse drop-shadow-black">Hold to Buy</span>
                    ) : isProcessing ? (
                         <span className="text-[0.45rem] font-black text-cyan-300 uppercase tracking-[0.3em] leading-none animate-pulse drop-shadow-cyan">Syncing...</span>
                    ) : showSuccess ? (
                         <span className="text-[0.45rem] font-black text-emerald-400 uppercase tracking-[0.3em] leading-none animate-bounce drop-shadow-emerald">Deposited</span>
                    ) : null}
                </div>

                {isLocked ? (
                    <div className="h-8 w-full bg-slate-900 border border-slate-700 rounded flex items-center justify-center gap-1.5 grayscale opacity-60">
                         <svg className="w-2.5 h-2.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                         <span className="text-[0.6rem] font-black tabular-nums">{Math.floor(timeLeft / 60)}:{(timeLeft % 60).toString().padStart(2, '0')}</span>
                    </div>
                ) : (
                    <SlantedButton 
                        variant={showSuccess ? 'success' : (type === 'gold' ? 'primary' : (type === 'tokens' ? 'danger' : 'blue'))} 
                        size="sm" 
                        fullWidth
                        onClick={execute}
                        disabled={isProcessing || showSuccess}
                    >
                        {isProcessing ? 'AUTHORIZING' : (showSuccess ? 'SYNCED' : costLabel)}
                    </SlantedButton>
                )}
            </div>
        </div>
    );
};

