import { useState, useCallback, useRef, useEffect } from 'react';

export type ActionStatus = 'idle' | 'processing' | 'success' | 'error';

interface UseSynchronizedActionProps {
    onAction: () => Promise<boolean>;
    holdDuration?: number;
    resetDelay?: number;
    errorDelay?: number;
}

/**
 * useSynchronizedAction
 * Encapsulates the visual logic for a transaction.
 * Now supports an 'error' state for immediate UX feedback.
 */
export const useSynchronizedAction = ({ 
    onAction, 
    holdDuration = 0,
    resetDelay = 4000,
    errorDelay = 1500
}: UseSynchronizedActionProps) => {
    const [status, setStatus] = useState<ActionStatus>('idle');
    const [holdProgress, setHoldProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);
    const timerRef = useRef<number | null>(null);

    const execute = useCallback(async () => {
        if (status !== 'idle') return;

        setStatus('processing');

        const success = await onAction();

        if (success) {
            setStatus('success');
            setTimeout(() => {
                setStatus('idle');
                setHoldProgress(0);
            }, resetDelay);
        } else {
            // New Error Logic: Provide visual "no" feedback
            setStatus('error');
            setTimeout(() => {
                setStatus('idle');
                setHoldProgress(0);
            }, errorDelay);
        }
    }, [onAction, status, resetDelay, errorDelay]);

    const startHold = useCallback(() => {
        if (status !== 'idle' || holdDuration <= 0) return;
        setIsHolding(true);
        const startTime = Date.now();

        timerRef.current = window.setInterval(() => {
            const elapsed = Date.now() - startTime;
            const p = Math.min((elapsed / holdDuration) * 100, 100);
            setHoldProgress(p);

            if (p >= 100) {
                cancelHold();
                execute();
            }
        }, 16);
    }, [status, holdDuration, execute]);

    const cancelHold = useCallback(() => {
        if (timerRef.current) clearInterval(timerRef.current);
        timerRef.current = null;
        setIsHolding(false);
        if (status === 'idle') setHoldProgress(0);
    }, [status]);

    useEffect(() => () => { if (timerRef.current) clearInterval(timerRef.current); }, []);

    return {
        status,
        holdProgress,
        isHolding,
        execute: holdDuration > 0 ? undefined : execute,
        bind: {
            onPointerDown: startHold,
            onPointerUp: cancelHold,
            onPointerLeave: cancelHold
        }
    };
};

import React, { useEffect, useState, useMemo } from 'react';
import { SlantedButton } from '../ui/SlantedButton';
import { GameText } from '../ui/GameText';
import { useUser } from '../../contexts/UserContext';
import { useSynchronizedAction } from '../../hooks/useSynchronizedAction';
import { CreditIcon, GoldIcon, TokenIcon } from '../ui/CurrencyIcons';
import { api } from '../../services/api';
import { StoreOffer } from '../../types';

interface StoreResourceItemProps {
    offer: StoreOffer;
}

const SUCCESS_WINDOW = 800; 

export const StoreResourceItem: React.FC<StoreResourceItemProps> = ({ offer }) => {
    const { user, storeData, performSynchronizedAction, syncStore } = useUser();
    const [timeLeft, setTimeLeft] = useState<number>(0);

    // Dynamic data extraction from manifest
    const amount = offer.contents[0]?.type === 'currency' ? offer.contents[0].amount : 0;
    const type = offer.contents[0]?.type === 'currency' ? offer.contents[0].currencyType : 'credits';
    const isFree = offer.priceType === 'free';
    const hasFunds = isFree || offer.priceType === 'real' || (offer.priceType === 'gold' && user.gold >= (offer.priceAmount || 0));

    useEffect(() => {
        if (!offer.availableAt) return;
        const updateTimer = () => {
            const now = Date.now();
            const target = new Date(offer.availableAt!).getTime();
            const diff = Math.max(0, Math.floor((target - now) / 1000));
            setTimeLeft(diff);
        };
        updateTimer();
        const interval = setInterval(updateTimer, 1000);
        return () => clearInterval(interval);
    }, [offer.availableAt]);

    const { status, holdProgress, isHolding, execute, bind } = useSynchronizedAction({
        holdDuration: (isFree || offer.priceType === 'real') ? 0 : 800,
        onAction: async () => {
            if (!hasFunds) {
                // Shake header or simulate "insufficient" toast locally
                return false;
            }
            return await performSynchronizedAction(
                () => api.purchaseOffer(user, offer.id, `txn_${Math.random()}`),
                { visualDelay: SUCCESS_WINDOW }
            );
        }
    });

    const isLocked = timeLeft > 0;
    const isSuccess = status === 'success';
    const isError = status === 'error';
    const isProcessing = status === 'processing';

    const isPermanentlyClaimed = useMemo(() => {
        return offer.isOneTime && user.purchasedOfferIds.includes(offer.id);
    }, [user.purchasedOfferIds, offer]);

    const showSuccess = isSuccess || isPermanentlyClaimed;
    const colors = type === 'gold' ? { text: 'text-amber-500', bg: 'bg-amber-400/30' } : (type === 'tokens' ? { text: 'text-red-500', bg: 'bg-red-400/30' } : { text: 'text-blue-400', bg: 'bg-blue-400/30' });

    return (
        <div 
            className={`
                bg-gradient-to-b from-slate-800 via-slate-900 to-black border-2 transition-all duration-300 rounded p-2 flex flex-col items-center justify-between h-[10.5rem] relative overflow-hidden shadow-2xl
                ${showSuccess ? 'border-emerald-400 ring-2 ring-emerald-500/50 bg-emerald-950' : (isError ? 'border-red-500 ring-2 ring-red-500/50 animate-[shake_0.4s_ease-in-out]' : 'border-slate-700')}
            `}
            {...(isFree || isLocked || isPermanentlyClaimed ? {} : bind)}
        >
            {isSuccess && <div className="absolute inset-0 bg-white/20 animate-pulse z-40 pointer-events-none" />}

            {holdProgress > 0 && status === 'idle' && !isLocked && !isPermanentlyClaimed && (
                <div className={`absolute inset-y-0 left-0 z-0 pointer-events-none ${colors.bg}`} style={{ width: `${holdProgress}%` }} />
            )}

            <div className="relative z-10 text-center w-full px-1">
                <div className="h-6 w-full mb-0.5">
                    <GameText text={amount.toLocaleString()} baseFontSize={1.1} className="text-white drop-shadow-md" />
                </div>
                <div className={`text-[0.45rem] font-black uppercase tracking-[0.2em] leading-none ${colors.text}`}>{type}</div>
            </div>

            <div className="relative z-10 flex-1 flex items-center justify-center">
                <div className={`w-12 h-12 rounded-full flex items-center justify-center border-2 transition-all duration-500 ${showSuccess ? 'bg-emerald-500 border-emerald-300 scale-110 shadow-[0_0_20px_rgba(16,185,129,0.8)]' : (isError ? 'bg-red-900 border-red-400' : 'bg-slate-900 border-slate-700')}`}>
                    {showSuccess ? (
                        <svg className="w-7 h-7 text-white animate-pop" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" /></svg>
                    ) : isError ? (
                        <svg className="w-7 h-7 text-white animate-pop" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M6 18L18 6M6 6l12 12" /></svg>
                    ) : (
                        type === 'gold' ? <GoldIcon size="md" /> : (type === 'tokens' ? <TokenIcon size="md" /> : <CreditIcon size="md" />)
                    )}
                </div>
            </div>

            <div className="w-full relative z-10">
                <div className="h-3 flex items-center justify-center mb-0.5 overflow-visible">
                    {isHolding && !isLocked && !isPermanentlyClaimed ? (
                         <span className="text-[0.45rem] font-black text-white uppercase tracking-widest animate-pulse drop-shadow-black">Hold to Buy</span>
                    ) : isProcessing ? (
                         <span className="text-[0.45rem] font-black text-cyan-300 uppercase tracking-[0.3em] leading-none animate-pulse drop-shadow-cyan">Syncing...</span>
                    ) : showSuccess ? (
                         <span className="text-[0.45rem] font-black text-emerald-400 uppercase tracking-[0.3em] leading-none animate-bounce drop-shadow-emerald">Deposited</span>
                    ) : isError ? (
                         <span className="text-[0.4rem] font-black text-red-400 uppercase tracking-[0.1em] leading-none italic animate-pulse">Low Funds</span>
                    ) : null}
                </div>

                {isLocked ? (
                    <div className="h-8 w-full bg-slate-900 border border-slate-700 rounded flex items-center justify-center gap-1.5 grayscale opacity-60">
                         <svg className="w-2.5 h-2.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                         <span className="text-[0.6rem] font-black tabular-nums">{Math.floor(timeLeft / 60)}:{(timeLeft % 60).toString().padStart(2, '0')}</span>
                    </div>
                ) : (
                    <SlantedButton 
                        variant={showSuccess ? 'success' : (isError ? 'danger' : (type === 'gold' ? 'primary' : (type === 'tokens' ? 'danger' : 'blue')))} 
                        size="sm" 
                        fullWidth
                        onClick={execute}
                        disabled={isProcessing || showSuccess}
                    >
                        {isProcessing ? 'AUTHORIZING' : (showSuccess ? 'SYNCED' : offer.price)}
                    </SlantedButton>
                )}
            </div>
            <style>{`
                @keyframes shake {
                    0%, 100% { transform: translateX(0); }
                    25% { transform: translateX(-4px); }
                    75% { transform: translateX(4px); }
                }
            `}</style>
        </div>
    );
};

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { StandardHeader } from '../ui/StandardHeader';
import { StoreResourceItem } from '../store/StoreResourceItem';
import { StoreSection } from '../store/StoreSection';
import { DailyOfferCard } from '../store/DailyOfferCard';
import { StoreOfferDetailOverlay } from '../store/StoreOfferDetailOverlay';
import { StoreOffer } from '../../types';
import { useUser } from '../../contexts/UserContext';

export const StoreScreen: React.FC = () => {
    const { storeData, isStoreLoading, storeScrollTarget, setStoreScrollTarget } = useUser();
    const [selectedOffer, setSelectedOffer] = useState<StoreOffer | null>(null);
    const scrollContainerRef = useRef<HTMLDivElement>(null);

    const handleJumpToSection = useCallback((id: string) => {
        const el = document.getElementById(id);
        const container = scrollContainerRef.current;
        if (el && container) {
            const targetTop = el.offsetTop - 8;
            container.scrollTo({ 
                top: targetTop, 
                behavior: 'smooth' 
            });
        }
    }, []);

    useEffect(() => {
        if (storeScrollTarget) {
            const t = setTimeout(() => {
                handleJumpToSection(storeScrollTarget);
                setStoreScrollTarget(null);
            }, 150);
            return () => clearTimeout(t);
        }
    }, [storeScrollTarget, setStoreScrollTarget, handleJumpToSection]);

    const offers = useMemo(() => storeData?.offers || [], [storeData]);

    // Data-driven grouping
    const featuredOffers = offers.filter(o => o.category === 'featured');

    // We categorize the 'daily' items into their specific sub-sections for better organization
    const creditOffers = offers.filter(o => 
        o.category === 'daily' && 
        o.contents.some(c => c.type === 'currency' && c.currencyType === 'credits')
    );
    const goldOffers = offers.filter(o => 
        o.category === 'daily' && 
        o.contents.some(c => c.type === 'currency' && c.currencyType === 'gold')
    );
    const tokenOffers = offers.filter(o => 
        o.category === 'daily' && 
        o.contents.some(c => c.type === 'currency' && c.currencyType === 'tokens')
    );

    return (
        <div className="w-full h-full flex flex-col bg-transparent overflow-hidden relative">
            <StandardHeader 
                title="Store" 
                showCurrency={true}
                onCreditClick={() => handleJumpToSection('store-credits')}
                onGoldClick={() => handleJumpToSection('store-gold')}
                onTokenClick={() => handleJumpToSection('store-tokens')}
            />

            <div 
                ref={scrollContainerRef}
                className="flex-1 overflow-y-auto p-4 pb-32 space-y-10 relative"
            >
                {/* 1. FEATURED SECTION */}
                {featuredOffers.length > 0 && (
                    <StoreSection id="store-featured" title="Featured" colorClass="text-indigo-400">
                        <div className="space-y-4">
                            {featuredOffers.map(offer => (
                                <DailyOfferCard 
                                    key={offer.id}
                                    title={offer.title}
                                    description={offer.description}
                                    price={offer.price}
                                    discount={offer.discountLabel}
                                    backgroundImage={offer.imageUrl}
                                    onClick={() => setSelectedOffer(offer)}
                                />
                            ))}
                        </div>
                    </StoreSection>
                )}

                {/* 2. CREDITS SECTION */}
                <StoreSection id="store-credits" title="Credits" colorClass="text-blue-400">
                    <div className="grid grid-cols-3 gap-2">
                        {creditOffers.map(offer => (
                            <StoreResourceItem key={offer.id} offer={offer} />
                        ))}
                    </div>
                </StoreSection>

                {/* 3. GOLD SECTION */}
                <StoreSection id="store-gold" title="Gold" colorClass="text-amber-400">
                    <div className="grid grid-cols-3 gap-2">
                        {goldOffers.map(offer => (
                            <StoreResourceItem key={offer.id} offer={offer} />
                        ))}
                    </div>
                </StoreSection>

                {/* 4. TOKENS SECTION */}
                <StoreSection id="store-tokens" title="Tokens" colorClass="text-red-400">
                    <div className="grid grid-cols-3 gap-2">
                        {tokenOffers.map(offer => (
                            <StoreResourceItem key={offer.id} offer={offer} />
                        ))}
                    </div>
                </StoreSection>

                {isStoreLoading && (
                    <div className="text-center py-4 animate-pulse">
                        <span className="text-[0.55rem] font-black text-indigo-400/50 uppercase tracking-[0.3em]">Refreshing Market Manifest...</span>
                    </div>
                )}

                <div className="text-center text-[0.55rem] font-bold text-white/10 py-6 uppercase tracking-[0.5em]">
                    End of Transmissions
                </div>
            </div>

            {selectedOffer && (
                <StoreOfferDetailOverlay 
                    offer={selectedOffer} 
                    onClose={() => setSelectedOffer(null)} 
                />
            )}
        </div>
    );
};

import React, { useState, useRef, useEffect } from 'react';
import { GameText } from './GameText';

type ButtonVariant = 'primary' | 'secondary' | 'success' | 'danger' | 'warning' | 'blue';

interface SlantedButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
    variant?: ButtonVariant;
    fullWidth?: boolean;
    size?: 'xs' | 'sm' | 'md' | 'lg';
    icon?: React.ReactNode;
    holdDuration?: number; 
    onHoldChange?: (isHolding: boolean) => void;
    onProgressChange?: (progress: number) => void;
}

export const SlantedButton: React.FC<SlantedButtonProps> = ({ 
    children, 
    variant = 'primary', 
    fullWidth = false,
    size = 'md',
    icon,
    className = '',
    holdDuration = 0,
    onHoldChange,
    onProgressChange,
    onClick,
    ...props 
}) => {
    const [progress, setProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);
    const timerRef = useRef<number | null>(null);
    const startTimeRef = useRef<number>(0);

    const variants = {
        primary: "from-indigo-500 to-indigo-800 border-indigo-400 shadow-[0_0.2rem_0_rgb(30,27,75)]",
        secondary: "from-slate-700 to-slate-900 border-slate-500 shadow-[0_0.2rem_0_rgb(15,23,42)]",
        success: "from-emerald-600 to-emerald-900 border-emerald-400 shadow-[0_0.2rem_0_rgb(6,78,59)]",
        danger: "from-red-600 to-red-900 border-red-400 shadow-[0_0.2rem_0_rgb(127,29,29)]",
        warning: "from-amber-600 to-amber-900 border-amber-400 shadow-[0_0.2rem_0_rgb(120,53,15)]",
        blue: "from-blue-600 to-blue-900 border-blue-400 shadow-[0_0.2rem_0_rgb(30,58,138)]",
    };

    const sizeConfigs = {
        // UI REFINEMENT: Lowered font sizes to ensure fit in 3-column store views
        xs: { height: "h-[1.65rem]", fontSize: 0.8, padding: "px-1" },
        sm: { height: "h-8", fontSize: 0.9, padding: "px-0.5" },
        md: { height: "h-10", fontSize: 1.15, padding: "px-1.5" },
        lg: { height: "h-16", fontSize: 1.45, padding: "px-1" }
    };

    const config = sizeConfigs[size];

    const startHold = (e: React.PointerEvent) => {
        if (!holdDuration || props.disabled) return;
        setIsHolding(true);
        onHoldChange?.(true);
        startTimeRef.current = Date.now();
        timerRef.current = window.setInterval(() => {
            const elapsed = Date.now() - startTimeRef.current;
            const p = Math.min((elapsed / holdDuration) * 100, 100);
            setProgress(p);
            onProgressChange?.(p);
            if (p >= 100) {
                if (timerRef.current) clearInterval(timerRef.current);
                timerRef.current = null;
                setProgress(100);
                onProgressChange?.(100);
                setTimeout(() => {
                    if (onClick) {
                        const sEvent = { clientX: e.clientX, clientY: e.clientY, target: e.target, currentTarget: e.currentTarget, type: 'click' } as any;
                        onClick(sEvent);
                    }
                    setIsHolding(false);
                    onHoldChange?.(false);
                    setProgress(0);
                    onProgressChange?.(0);
                }, 60);
            }
        }, 16);
    };

    const cancelHold = () => {
        if (timerRef.current) { clearInterval(timerRef.current); timerRef.current = null; }
        setIsHolding(false);
        onHoldChange?.(false);
        setProgress(0);
        onProgressChange?.(0);
    };

    useEffect(() => { return () => { if (timerRef.current) clearInterval(timerRef.current); }; }, []);

    const hasExplicitWidth = className.includes('w-') || className.includes('max-w-');
    const widthClass = fullWidth ? 'w-full' : (hasExplicitWidth ? '' : 'w-max');

    const containerJustify = 'justify-center';
    const textJustify = icon ? 'justify-start' : 'justify-center';

    return (
        <div className={`relative group ${widthClass} ${config.height} min-w-0 ${props.disabled ? 'opacity-50 pointer-events-none' : ''} ${className}`}>
            <button 
                className={`w-full h-full relative z-10 active:translate-y-0.5 transition-all outline-none`}
                onPointerDown={holdDuration ? startHold : undefined}
                onPointerUp={holdDuration ? cancelHold : undefined}
                onPointerLeave={holdDuration ? cancelHold : undefined}
                onClick={holdDuration ? undefined : onClick}
                role="button"
                {...props}
            >
                {/* SLANTED BACKGROUND */}
                <div className={`absolute inset-0 bg-gradient-to-b border rounded skew-x-[-9deg] transition-all duration-200 overflow-hidden ${variants[variant]}`}>
                    {holdDuration > 0 && (
                        <div className="absolute inset-y-0 left-0 bg-white/20 transition-all duration-75 ease-linear pointer-events-none" style={{ width: `${progress}%` }} />
                    )}
                </div>

                {/* SLANTED CONTENT WRAPPER */}
                <div className={`relative z-20 h-full w-full pointer-events-none flex items-center ${containerJustify} skew-x-[-9deg] min-w-0 ${children ? config.padding : 'px-1.5'}`}>
                    <div className={`flex items-center ${containerJustify} gap-0.5 w-full h-full min-w-0 transition-opacity ${isHolding ? 'opacity-40' : 'opacity-100'}`}>
                        {icon && (
                            <div className="shrink-0 flex items-center justify-center drop-shadow-[0_2px_3px_rgba(0,0,0,0.8)]">
                                {icon}
                            </div>
                        )}

                        {children && (
                            <div className={`flex-1 h-full min-w-0 flex items-center ${textJustify}`}>
                                {typeof children === 'string' || typeof children === 'number' ? (
                                    <GameText 
                                        text={children.toString()} 
                                        baseFontSize={config.fontSize} 
                                        skewFactor={0.92} 
                                        maxLines={2} 
                                        className="text-white font-black italic tracking-tighter uppercase drop-shadow-[0_2px_3px_rgba(0,0,0,0.8)]"
                                    />
                                ) : (
                                    <div className={`flex items-center ${textJustify} drop-shadow-[0_2px_3px_rgba(0,0,0,0.8)] w-full h-full min-w-0`}>
                                        {children}
                                    </div>
                                )}
                            </div>
                        )}
                    </div>
                </div>
            </button>
        </div>
    );
};

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
