                    <div className="grid grid-cols-3 gap-2">
                        {goldOffers.map(offer => (
                            <StoreResourceItem 
                                key={offer.id}
                                type="gold"
                                // FIX: Cast find result to the currency union member to safely access 'amount'
                                amount={(offer.contents.find(c => c.type === 'currency') as Extract<OfferItem, { type: 'currency' }>)?.amount || 0}
                                costLabel={offer.price}
                                costAmount={offer.priceAmount}
                                costType={offer.priceType as any}
                                offerId={offer.id}
                            />
