    async debugNextSeason(): Promise<void> {
        currentSeasonIndex = (currentSeasonIndex + 1) % SEASONS.length;
        await new Promise(resolve => setTimeout(resolve, 200));
    },

    async getSeasonPass(user: UserProfile): Promise<SeasonPassData> {
        await new Promise(resolve => setTimeout(resolve, 500));

        const season = SEASONS[currentSeasonIndex];
        const seasonId = season.id;

        const userProgress = user.seasonProgress[seasonId] || { level: 1, xp: 0 };

        const endDate = "2025-12-31T23:59:59Z";
        const endsInSeconds = Math.floor((new Date(endDate).getTime() - Date.now()) / 1000);

        const heroCard = CARDS.find(c => c.id === season.heroCardId)!;

        const rewards: SeasonPassReward[] = Array.from({ length: 100 }, (_, i) => {
            const level = i + 1;
            let type: SeasonRewardType = 'credits';
            let amount: string | number = 50;
            let specificCardDef = undefined;

            if (level === 50) {
                type = 'card';
                amount = 'SEASON EXCLUSIVE';
                specificCardDef = heroCard;
            } else if (level % 10 === 0) {
                type = 'card';
                amount = 'VARIANT';
                specificCardDef = CARDS[Math.floor((level / 10) % CARDS.length)];
            } else if (level % 5 === 0) {
                type = 'gold';
                amount = 100;
            } else if (level % 2 === 0) {
                type = 'booster';
                amount = 10;
            } else {
                type = 'credits';
                amount = 50 + (Math.floor(level / 10) * 10);
            }

            return {
                level,
                type,
                amount,
                cardDef: specificCardDef,
                isClaimed: level < userProgress.level,
                isActive: level === userProgress.level,
                isLocked: level > userProgress.level
            };
        });

        return {
            id: seasonId,
            themeName: season.name,
            startDate: "2025-01-01T00:00:00Z",
            endDate,
            endsInSeconds,
            premiumActive: true,
            heroCardId: season.heroCardId,
            heroVariantName: season.heroVariant,
            rewards
        };
    },

    async getStoreOffers(user: UserProfile): Promise<StoreData> {
        await new Promise(resolve => setTimeout(resolve, 600)); 

        const filteredOffers = MOCK_STORE_OFFERS.filter(offer => {
            if (offer.isOneTime && user.purchasedOfferIds.includes(offer.id)) return false;
            if (offer.purchaseLimit) {
                const count = user.purchasedOfferIds.filter(id => id === offer.id).length;
                if (count >= offer.purchaseLimit) return false;
            }
            if (offer.expiryDate && new Date(offer.expiryDate) < new Date()) return false;
            return true;
        }).map(offer => {
            if (offer.cooldownSeconds && user.lastClaimedDates[offer.id]) {
                const lastClaimed = new Date(user.lastClaimedDates[offer.id]).getTime();
                const availableAt = new Date(lastClaimed + (offer.cooldownSeconds * 1000));
                return { ...offer, availableAt: availableAt.toISOString() };
            }
            return offer;
        });

        /**
         * AUTHORITATIVE SERVER SORT
         * Sort logic: 
         * 1. Free price types always -1 (first)
         * 2. Real price types always 1,000,000 (last)
         * 3. Numerical amount comparison for currencies (smallest amount first)
         */
        const sortedOffers = [...filteredOffers].sort((a, b) => {
            const getWeight = (o: StoreOffer) => {
                if (o.priceType === 'free') return -1;
                if (o.priceType === 'real') return 1000000;

                // Get the currency amount of the first item in contents if it's a currency offer
                const currencyItem = o.contents.find(c => c.type === 'currency');
                if (currencyItem && 'amount' in currencyItem) {
                    return currencyItem.amount;
                }
                return 0;
            };
            return getWeight(a) - getWeight(b);
        });

        return {
            offers: sortedOffers,
            lastUpdated: Date.now(),
            refreshHintSeconds: 60
        };
    },

    async purchaseOffer(user: UserProfile, offerId: string, transactionId: string): Promise<PurchaseResponse> {
        await new Promise(resolve => setTimeout(resolve, 800 + Math.random() * 400));
        if (processedTransactions.has(transactionId)) return { success: false, errorCode: 'ERR_DUPLICATE_TRANSACTION', transactionId };
        const offer = MOCK_STORE_OFFERS.find(o => o.id === offerId);
        if (!offer) return { success: false, errorCode: 'ERR_OFFER_NOT_FOUND', transactionId };
        if (offer.cooldownSeconds && user.lastClaimedDates[offer.id]) {
            const lastClaimed = new Date(user.lastClaimedDates[offer.id]).getTime();
            if (Date.now() < lastClaimed + (offer.cooldownSeconds * 1000)) return { success: false, errorCode: 'ERR_COOLDOWN_ACTIVE', transactionId };
        }
        if (offer.priceType === 'gold' && user.gold < (offer.priceAmount || 0)) return { success: false, errorCode: 'ERR_INSUFFICIENT_FUNDS', transactionId };
        if (offer.priceType === 'credits' && user.credits < (offer.priceAmount || 0)) return { success: false, errorCode: 'ERR_INSUFFICIENT_FUNDS', transactionId };
        processedTransactions.add(transactionId);
        const updatedProfile: UserProfile = { ...user };
        if (offer.priceType === 'gold') updatedProfile.gold -= (offer.priceAmount || 0);
        if (offer.priceType === 'credits') updatedProfile.credits -= (offer.priceAmount || 0);
        offer.contents.forEach(item => {
            if (item.type === 'currency') {
                if (item.currencyType === 'gold') updatedProfile.gold += item.amount;
                if (item.currencyType === 'credits') updatedProfile.credits += item.amount;
                if (item.currencyType === 'tokens') updatedProfile.tokens += item.amount;
            } else if (item.type === 'card' && !updatedProfile.collection.includes(item.definitionId)) {
                updatedProfile.collection = [...updatedProfile.collection, item.definitionId];
            }
        });
        updatedProfile.purchasedOfferIds = [...updatedProfile.purchasedOfferIds, offerId];
        updatedProfile.lastClaimedDates = { ...updatedProfile.lastClaimedDates, [offerId]: new Date().toISOString() };
        return { success: true, transactionId, updatedProfile };
    },

    // --- Progression API ---
    async getProgression(user: UserProfile): Promise<ProgressionData> {
        await new Promise(resolve => setTimeout(resolve, 400));
        return getProgressionDataInternal(user);
    },

    async getActivityLog(type: string = 'all'): Promise<ActivityLogEntry[]> {
        await new Promise(resolve => setTimeout(resolve, 200));
        if (type === 'all') return progressionStore.activityLog;
        return progressionStore.activityLog.filter(log => log.type === type);
    },

    async claimProgressionReward(user: UserProfile, type: ProgressionRewardType): Promise<{ success: boolean, updatedProfile?: UserProfile, progressionData?: ProgressionData, activityLog?: ActivityLogEntry[] }> {
        await new Promise(resolve => setTimeout(resolve, 500));

        if (progressionStore.unclaimedCounts[type] <= 0) {
            return { success: false };
        }

        // Mutation: Server-side
        progressionStore.unclaimedCounts[type]--;

        const updatedProfile = { ...user };
        let rewardTitle = '';
        let rewardAmount: string | number = '';
        let rewardCardDef = undefined;

        if (type === 'credits') {
            updatedProfile.credits += 50;
            rewardTitle = "50 Credits";
            rewardAmount = 50;
        } else if (type === 'gold') {
            updatedProfile.gold += 100;
            rewardTitle = "100 Gold";
            rewardAmount = 100;
        } else if (type === 'tokens') {
            updatedProfile.tokens += 100;
            rewardTitle = "100 Tokens";
            rewardAmount = 100;
        } else if (type === 'card') {
            const card = CARDS[Math.floor(Math.random() * CARDS.length)];
            updatedProfile.collection.push(card.id);
            rewardTitle = card.name;
            rewardCardDef = card;
        } else if (type === 'booster') {
            rewardTitle = "10 Boosters";
            rewardAmount = 10;
        } else if (type === 'box') {
            rewardTitle = "Omega Box";
        }

        // Add to log
        const now = new Date();
        progressionStore.activityLog.unshift({
            id: generateInstanceId(),
            title: rewardTitle,
            type: type,
            date: `${now.getDate()} ${now.toLocaleString('default', { month: 'short' }).toUpperCase()}`,
            time: `${now.getHours()}:${now.getMinutes().toString().padStart(2, '0')}`,
            amount: rewardAmount,
            cardDef: rewardCardDef
        });

        // Return the complete updated state atomically
        return { 
            success: true, 
            updatedProfile, 
            progressionData: getProgressionDataInternal(updatedProfile),
            activityLog: [...progressionStore.activityLog]
        };
    }
};

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { StandardHeader } from '../ui/StandardHeader';
import { StoreResourceItem } from '../store/StoreResourceItem';
import { StoreSection } from '../store/StoreSection';
import { DailyOfferCard } from '../store/DailyOfferCard';
import { StoreOfferDetailOverlay } from '../store/StoreOfferDetailOverlay';
import { StoreOffer, OfferItem } from '../../types';
import { useUser } from '../../contexts/UserContext';

export const StoreScreen: React.FC = () => {
    const { storeData, isStoreLoading, storeScrollTarget, setStoreScrollTarget } = useUser();
    const [selectedOffer, setSelectedOffer] = useState<StoreOffer | null>(null);
    const scrollContainerRef = useRef<HTMLDivElement>(null);

    const handleJumpToSection = useCallback((id: string) => {
        const el = document.getElementById(id);
        const container = scrollContainerRef.current;
        if (el && container) {
            const targetTop = el.offsetTop - 8;
            container.scrollTo({ 
                top: targetTop, 
                behavior: 'smooth' 
            });
        }
    }, []);

    useEffect(() => {
        if (storeScrollTarget) {
            const t = setTimeout(() => {
                handleJumpToSection(storeScrollTarget);
                setStoreScrollTarget(null);
            }, 150);
            return () => clearTimeout(t);
        }
    }, [storeScrollTarget, setStoreScrollTarget, handleJumpToSection]);

    const offers = storeData?.offers || [];

    const getCurrencyAmount = (offer: StoreOffer) => {
        const item = offer.contents.find(c => c.type === 'currency');
        if (item && 'amount' in item) return item.amount;
        return 0;
    };

    /**
     * Filter functions - We trust the SERVER'S order, so we just filter by type.
     */
    const featuredOffers = offers.filter(o => o.category === 'featured');

    const creditOffers = offers.filter(o => 
        o.category === 'daily' && 
        o.contents.some(c => c.type === 'currency' && c.currencyType === 'credits')
    );

    const goldOffers = offers.filter(o => 
        o.category === 'daily' && 
        o.contents.some(c => c.type === 'currency' && c.currencyType === 'gold')
    );

    const tokenOffers = offers.filter(o => 
        o.category === 'daily' && 
        o.contents.some(c => c.type === 'currency' && c.currencyType === 'tokens')
    );

    return (
        <div className="w-full h-full flex flex-col bg-transparent overflow-hidden relative">
            <StandardHeader 
                title="Store" 
                showCurrency={true}
                onCreditClick={() => handleJumpToSection('store-credits')}
                onGoldClick={() => handleJumpToSection('store-gold')}
                onTokenClick={() => handleJumpToSection('store-tokens')}
            />

            <div 
                ref={scrollContainerRef}
                className="flex-1 overflow-y-auto p-4 pb-32 space-y-10 relative"
            >
                {/* 1. FEATURED SECTION */}
                {featuredOffers.length > 0 && (
                    <StoreSection id="store-featured" title="Featured" colorClass="text-indigo-400">
                        <div className="space-y-4">
                            {featuredOffers.map(offer => (
                                <DailyOfferCard 
                                    key={offer.id}
                                    title={offer.title}
                                    description={offer.description}
                                    price={offer.price}
                                    discount={offer.discountLabel}
                                    backgroundImage={offer.imageUrl}
                                    onClick={() => setSelectedOffer(offer)}
                                />
                            ))}
                        </div>
                    </StoreSection>
                )}

                {/* 2. CREDITS SECTION */}
                <StoreSection id="store-credits" title="Credits" colorClass="text-blue-400">
                    <div className="grid grid-cols-3 gap-2">
                        {creditOffers.map(offer => (
                            <StoreResourceItem 
                                key={offer.id}
                                type="credits"
                                amount={getCurrencyAmount(offer)}
                                costLabel={offer.price}
                                costAmount={offer.priceAmount}
                                costType={offer.priceType as any}
                                offerId={offer.id}
                                availableAt={offer.availableAt}
                            />
                        ))}
                    </div>
                </StoreSection>

                {/* 3. GOLD SECTION */}
                <StoreSection id="store-gold" title="Gold" colorClass="text-amber-400">
                    <div className="grid grid-cols-3 gap-2">
                        {goldOffers.map(offer => (
                            <StoreResourceItem 
                                key={offer.id}
                                type="gold"
                                amount={getCurrencyAmount(offer)}
                                costLabel={offer.price}
                                costAmount={offer.priceAmount}
                                costType={offer.priceType as any}
                                offerId={offer.id}
                            />
                        ))}
                    </div>
                </StoreSection>

                {/* 4. TOKENS SECTION */}
                <StoreSection id="store-tokens" title="Tokens" colorClass="text-red-400">
                    <div className="grid grid-cols-3 gap-2">
                        {tokenOffers.map(offer => (
                            <StoreResourceItem 
                                key={offer.id}
                                type="tokens"
                                amount={getCurrencyAmount(offer)}
                                costLabel={offer.price}
                                costAmount={offer.priceAmount}
                                costType={offer.priceType as any}
                                offerId={offer.id}
                                availableAt={offer.availableAt}
                            />
                        ))}
                    </div>
                </StoreSection>

                {isStoreLoading && (
                    <div className="text-center py-4 animate-pulse">
                        <span className="text-[0.55rem] font-black text-indigo-400/50 uppercase tracking-[0.3em]">Refreshing Market Manifest...</span>
                    </div>
                )}

                <div className="text-center text-[0.55rem] font-bold text-white/10 py-6 uppercase tracking-[0.5em]">
                    End of Transmissions
                </div>
            </div>

            {selectedOffer && (
                <StoreOfferDetailOverlay 
                    offer={selectedOffer} 
                    onClose={() => setSelectedOffer(null)} 
                />
            )}
        </div>
    );
};

import React, { useState, useRef, useEffect } from 'react';
import { GameText } from './GameText';

type ButtonVariant = 'primary' | 'secondary' | 'success' | 'danger' | 'warning' | 'blue';

interface SlantedButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
    variant?: ButtonVariant;
    fullWidth?: boolean;
    size?: 'xs' | 'sm' | 'md' | 'lg';
    icon?: React.ReactNode;
    holdDuration?: number; 
    onHoldChange?: (isHolding: boolean) => void;
    onProgressChange?: (progress: number) => void;
}

export const SlantedButton: React.FC<SlantedButtonProps> = ({ 
    children, 
    variant = 'primary', 
    fullWidth = false,
    size = 'md',
    icon,
    className = '',
    holdDuration = 0,
    onHoldChange,
    onProgressChange,
    onClick,
    ...props 
}) => {
    const [progress, setProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);
    const timerRef = useRef<number | null>(null);
    const startTimeRef = useRef<number>(0);

    const variants = {
        primary: "from-indigo-500 to-indigo-800 border-indigo-400 shadow-[0_0.2rem_0_rgb(30,27,75)]",
        secondary: "from-slate-700 to-slate-900 border-slate-500 shadow-[0_0.2rem_0_rgb(15,23,42)]",
        success: "from-emerald-600 to-emerald-900 border-emerald-400 shadow-[0_0.2rem_0_rgb(6,78,59)]",
        danger: "from-red-600 to-red-900 border-red-400 shadow-[0_0.2rem_0_rgb(127,29,29)]",
        warning: "from-amber-600 to-amber-900 border-amber-400 shadow-[0_0.2rem_0_rgb(120,53,15)]",
        blue: "from-blue-600 to-blue-900 border-blue-400 shadow-[0_0.2rem_0_rgb(30,58,138)]",
    };

    const sizeConfigs = {
        xs: { height: "h-[1.65rem]", fontSize: 1.1, padding: "px-1" },
        sm: { height: "h-8", fontSize: 1.35, padding: "px-0.5" },
        md: { height: "h-10", fontSize: 1.25, padding: "px-1.5" },
        lg: { height: "h-16", fontSize: 1.45, padding: "px-1" }
    };

    const config = sizeConfigs[size];

    const startHold = (e: React.PointerEvent) => {
        if (!holdDuration || props.disabled) return;
        setIsHolding(true);
        onHoldChange?.(true);
        startTimeRef.current = Date.now();
        timerRef.current = window.setInterval(() => {
            const elapsed = Date.now() - startTimeRef.current;
            const p = Math.min((elapsed / holdDuration) * 100, 100);
            setProgress(p);
            onProgressChange?.(p);
            if (p >= 100) {
                if (timerRef.current) clearInterval(timerRef.current);
                timerRef.current = null;
                setProgress(100);
                onProgressChange?.(100);
                setTimeout(() => {
                    if (onClick) {
                        const sEvent = { clientX: e.clientX, clientY: e.clientY, target: e.target, currentTarget: e.currentTarget, type: 'click' } as any;
                        onClick(sEvent);
                    }
                    setIsHolding(false);
                    onHoldChange?.(false);
                    setProgress(0);
                    onProgressChange?.(0);
                }, 60);
            }
        }, 16);
    };

    const cancelHold = () => {
        if (timerRef.current) { clearInterval(timerRef.current); timerRef.current = null; }
        setIsHolding(false);
        onHoldChange?.(false);
        setProgress(0);
        onProgressChange?.(0);
    };

    useEffect(() => { return () => { if (timerRef.current) clearInterval(timerRef.current); }; }, []);

    const hasExplicitWidth = className.includes('w-') || className.includes('max-w-');
    const widthClass = fullWidth ? 'w-full' : (hasExplicitWidth ? '' : 'w-max');

    const containerJustify = 'justify-center';
    const textJustify = icon ? 'justify-start' : 'justify-center';

    return (
        <div className={`relative group ${widthClass} ${config.height} min-w-0 ${props.disabled ? 'opacity-50 pointer-events-none' : ''} ${className}`}>
            <button 
                className={`w-full h-full relative z-10 active:translate-y-0.5 transition-all outline-none`}
                onPointerDown={holdDuration ? startHold : undefined}
                onPointerUp={holdDuration ? cancelHold : undefined}
                onPointerLeave={holdDuration ? cancelHold : undefined}
                onClick={holdDuration ? undefined : onClick}
                role="button"
                {...props}
            >
                {/* SLANTED BACKGROUND */}
                <div className={`absolute inset-0 bg-gradient-to-b border rounded skew-x-[-9deg] transition-all duration-200 overflow-hidden ${variants[variant]}`}>
                    {holdDuration > 0 && (
                        <div className="absolute inset-y-0 left-0 bg-white/20 transition-all duration-75 ease-linear pointer-events-none" style={{ width: `${progress}%` }} />
                    )}
                </div>

                {/* SLANTED CONTENT WRAPPER */}
                <div className={`relative z-20 h-full w-full pointer-events-none flex items-center ${containerJustify} skew-x-[-9deg] min-w-0 ${children ? config.padding : 'px-1.5'}`}>
                    <div className={`flex items-center ${containerJustify} gap-0.5 w-full h-full min-w-0 transition-opacity ${isHolding ? 'opacity-40' : 'opacity-100'}`}>
                        {icon && (
                            <div className="shrink-0 flex items-center justify-center drop-shadow-[0_2px_3px_rgba(0,0,0,0.8)]">
                                {icon}
                            </div>
                        )}

                        {children && (
                            <div className={`flex-1 h-full min-w-0 flex items-center ${textJustify}`}>
                                {typeof children === 'string' || typeof children === 'number' ? (
                                    <GameText 
                                        text={children.toString()} 
                                        baseFontSize={config.fontSize} 
                                        skewFactor={0.85} // GEOMETRIC RE-CALIBRATION: Prevents edge-clipping on long dynamic strings.
                                        maxLines={2} 
                                        className="text-white font-black italic tracking-tighter uppercase drop-shadow-[0_2px_3px_rgba(0,0,0,0.8)]"
                                    />
                                ) : (
                                    <div className={`flex items-center ${textJustify} drop-shadow-[0_2px_3px_rgba(0,0,0,0.8)] w-full h-full min-w-0`}>
                                        {children}
                                    </div>
                                )}
                            </div>
                        )}
                    </div>
                </div>
            </button>
        </div>
    );
};

import React, { useState, useLayoutEffect, useRef } from 'react';

interface GameTextProps {
  text: string;
  className?: string;
  baseFontSize: number; // in rem
  maxScale?: number;
  minScale?: number;
  skewFactor?: number; 
  maxLines?: number;
}

/**
 * HIGH-PRECISION TEXT SCALING ENGINE
 * Optimized for centering and deterministic fitting.
 * Now supports true liquid wrapping for multi-line strings.
 */
export const GameText: React.FC<GameTextProps> = React.memo(({ 
  text, 
  className = '', 
  baseFontSize,
  maxScale = 1.0,
  minScale = 0.2,
  skewFactor = 1.0,
  maxLines = 1
}) => {
  const [scale, setScale] = useState(1);
  const containerRef = useRef<HTMLDivElement>(null);
  const textRef = useRef<HTMLDivElement>(null);

  useLayoutEffect(() => {
    let rafId: number;

    const measure = () => {
      const container = containerRef.current;
      const textEl = textRef.current;
      if (!container || !textEl) return;

      const containerW = container.clientWidth * skewFactor;
      const containerH = container.clientHeight;

      if (containerW <= 0 || containerH <= 0) {
        rafId = requestAnimationFrame(measure);
        return;
      }

      // MEASUREMENT CLONE - EXACT DUPLICATE OF RENDERING STYLE
      const clone = document.createElement('div');
      clone.style.position = 'absolute';
      clone.style.visibility = 'hidden';
      clone.style.left = '-9999px';
      clone.style.top = '-9999px';
      clone.style.fontSize = `${baseFontSize}rem`;
      const computedStyle = getComputedStyle(textEl);
      clone.style.fontFamily = computedStyle.fontFamily;
      clone.style.fontWeight = computedStyle.fontWeight;
      clone.style.fontStyle = computedStyle.fontStyle;
      clone.style.letterSpacing = computedStyle.letterSpacing;
      clone.style.textTransform = computedStyle.textTransform;
      clone.style.lineHeight = '0.85'; 
      clone.style.textAlign = 'center';

      const isMultiLine = maxLines > 1;

      // Measure natural unwrapped width
      clone.style.whiteSpace = 'nowrap';
      clone.style.width = 'auto';
      clone.innerText = text.replace(/\n/g, ' '); 
      document.body.appendChild(clone);
      const naturalUnwrappedW = clone.scrollWidth;

      // Calculate a "Wrap Budget"
      // If we want 2 lines, we aim to wrap at roughly half the total width or the container width
      const idealWrapWidth = isMultiLine ? Math.min(containerW, Math.max(naturalUnwrappedW / 1.8, containerW * 0.6)) : naturalUnwrappedW;

      // Measure actual dimensions with wrapping
      if (isMultiLine) {
          clone.style.whiteSpace = 'pre-wrap';
          clone.style.wordBreak = 'break-word';
          clone.style.width = `${idealWrapWidth}px`;
          clone.innerText = text;
      }

      const measuredH = clone.scrollHeight;
      const measuredW = isMultiLine ? clone.scrollWidth : naturalUnwrappedW;

      document.body.removeChild(clone);

      // SCALING CALCULATION
      // We calculate scale based on the wrap-constrained measurement
      const scaleW = containerW / measuredW;
      const scaleH = containerH / measuredH;
      const targetScale = Math.min(scaleW, scaleH);

      const finalScale = Math.min(maxScale, Math.max(minScale, targetScale));
      setScale(finalScale);
    };

    measure();

    if (typeof ResizeObserver !== 'undefined' && containerRef.current) {
        const observer = new ResizeObserver(measure);
        observer.observe(containerRef.current);
        return () => {
            observer.disconnect();
            cancelAnimationFrame(rafId);
        };
    }
  }, [text, baseFontSize, maxScale, minScale, skewFactor, maxLines]);

  return (
    <div 
        ref={containerRef}
        className={`w-full h-full flex justify-center items-center overflow-hidden pointer-events-none select-none ${className}`}
        style={{ fontSize: `${baseFontSize}rem` }}
    >
      <div 
        ref={textRef}
        style={{ 
          transform: scale < 1 ? `scale(${scale})` : 'none',
          transformOrigin: 'center center',
          display: 'flex', 
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          width: maxLines > 1 ? '100%' : 'max-content',
          lineHeight: 0.85,
          textAlign: 'center',
          whiteSpace: maxLines > 1 ? 'pre-wrap' : 'nowrap',
          wordBreak: 'break-word'
        }} 
        className="transition-transform duration-300 ease-out will-change-transform"
      >
        {text}
      </div>
    </div>
  );
});

import React, { useEffect, useState, useMemo } from 'react';
import { SlantedButton } from '../ui/SlantedButton';
import { GameText } from '../ui/GameText';
import { useUser } from '../../contexts/UserContext';
import { useSynchronizedAction } from '../../hooks/useSynchronizedAction';
import { CreditIcon, GoldIcon, TokenIcon } from '../ui/CurrencyIcons';
import { api } from '../../services/api';

interface StoreResourceItemProps {
    type: 'gold' | 'credits' | 'tokens';
    amount: number;
    costLabel: string;
    costAmount?: number;
    costType: 'gold' | 'real' | 'free';
    offerId?: string;
    availableAt?: string;
}

const SUCCESS_WINDOW = 800; // Shared theatrical duration

export const StoreResourceItem: React.FC<StoreResourceItemProps> = ({ 
    type, amount, costLabel, costAmount, costType, offerId, availableAt 
}) => {
    const { user, storeData, performSynchronizedAction, syncStore } = useUser();
    const [timeLeft, setTimeLeft] = useState<number>(0);

    const isFree = costType === 'free';
    const hasFunds = isFree || costType === 'real' || (costType === 'gold' && user.gold >= (costAmount || 0));

    // Restore two-line formatting for Store Buttons
    // Converts "400 Gold" -> "400\nGold"
    const formattedCostLabel = useMemo(() => {
        if (costLabel.includes(' ')) {
            return costLabel.replace(' ', '\n');
        }
        return costLabel;
    }, [costLabel]);

    useEffect(() => {
        if (!availableAt) return;
        const updateTimer = () => {
            const now = Date.now();
            const target = new Date(availableAt).getTime();
            const diff = Math.max(0, Math.floor((target - now) / 1000));
            setTimeLeft(diff);
        };
        updateTimer();
        const interval = setInterval(updateTimer, 1000);
        return () => clearInterval(interval);
    }, [availableAt]);

    const { status, holdProgress, isHolding, execute, bind } = useSynchronizedAction({
        holdDuration: (isFree || costType === 'real') ? 0 : 800,
        onAction: async () => {
            if (!hasFunds) {
                syncStore();
                return false;
            }
            if (!offerId) return false;

            return await performSynchronizedAction(
                () => api.purchaseOffer(user, offerId, `txn_${Math.random()}`),
                { visualDelay: SUCCESS_WINDOW }
            );
        }
    });

    const isLocked = timeLeft > 0;
    const isSuccess = status === 'success';
    const isProcessing = status === 'processing';

    const isPermanentlyClaimed = useMemo(() => {
        const offer = storeData?.offers.find(o => o.id === offerId);
        return offer?.isOneTime && user.purchasedOfferIds.includes(offerId || '');
    }, [user.purchasedOfferIds, offerId, storeData]);

    const showSuccess = isSuccess || isPermanentlyClaimed;
    const colors = type === 'gold' ? { text: 'text-amber-500', bg: 'bg-amber-400/30' } : (type === 'tokens' ? { text: 'text-red-500', bg: 'bg-red-400/30' } : { text: 'text-blue-400', bg: 'bg-blue-400/30' });

    return (
        <div 
            className={`bg-gradient-to-b from-slate-800 via-slate-900 to-black border-2 transition-all duration-300 rounded p-2 flex flex-col items-center justify-between h-[10.5rem] relative overflow-hidden shadow-2xl ${showSuccess ? 'border-emerald-400 ring-2 ring-emerald-500/50 bg-emerald-950' : 'border-slate-700'}`}
            {...(isFree || isLocked || isPermanentlyClaimed ? {} : bind)}
        >
            {isSuccess && <div className="absolute inset-0 bg-white/20 animate-pulse z-40 pointer-events-none" />}

            {holdProgress > 0 && status === 'idle' && !isLocked && !isPermanentlyClaimed && (
                <div className={`absolute inset-y-0 left-0 z-0 pointer-events-none ${colors.bg}`} style={{ width: `${holdProgress}%` }} />
            )}

            <div className="relative z-10 text-center w-full px-1">
                <div className="h-6 w-full mb-0.5">
                    <GameText text={amount.toLocaleString()} baseFontSize={1.1} className="text-white drop-shadow-md" />
                </div>
                <div className={`text-[0.45rem] font-black uppercase tracking-[0.2em] leading-none ${colors.text}`}>{type}</div>
            </div>

            <div className="relative z-10 flex-1 flex items-center justify-center">
                <div className={`w-12 h-12 rounded-full flex items-center justify-center border-2 transition-all duration-500 ${showSuccess ? 'bg-emerald-500 border-emerald-300 scale-110 shadow-[0_0_20px_rgba(16,185,129,0.8)]' : 'bg-slate-900 border-slate-700'}`}>
                    {showSuccess ? (
                        <svg className="w-7 h-7 text-white animate-pop" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" /></svg>
                    ) : (
                        type === 'gold' ? <GoldIcon size="md" /> : (type === 'tokens' ? <TokenIcon size="md" /> : <CreditIcon size="md" />)
                    )}
                </div>
            </div>

            <div className="w-full relative z-10">
                <div className="h-3 flex items-center justify-center mb-0.5 overflow-visible">
                    {isHolding && !isLocked && !isPermanentlyClaimed ? (
                         <span className="text-[0.45rem] font-black text-white uppercase tracking-widest animate-pulse drop-shadow-black">Hold to Buy</span>
                    ) : isProcessing ? (
                         <span className="text-[0.45rem] font-black text-cyan-300 uppercase tracking-[0.3em] leading-none animate-pulse drop-shadow-cyan">Syncing...</span>
                    ) : showSuccess ? (
                         <span className="text-[0.45rem] font-black text-emerald-400 uppercase tracking-[0.3em] leading-none animate-bounce drop-shadow-emerald">Deposited</span>
                    ) : null}
                </div>

                {isLocked ? (
                    <div className="h-8 w-full bg-slate-900 border border-slate-700 rounded flex items-center justify-center gap-1.5 grayscale opacity-60">
                         <svg className="w-2.5 h-2.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                         <span className="text-[0.6rem] font-black tabular-nums">{Math.floor(timeLeft / 60)}:{(timeLeft % 60).toString().padStart(2, '0')}</span>
                    </div>
                ) : (
                    <SlantedButton 
                        variant={showSuccess ? 'success' : (type === 'gold' ? 'primary' : (type === 'tokens' ? 'danger' : 'blue'))} 
                        size="sm" 
                        fullWidth
                        onClick={execute}
                        disabled={isProcessing || showSuccess}
                    >
                        {isProcessing ? 'AUTHORIZING' : (showSuccess ? 'SYNCED' : formattedCostLabel)}
                    </SlantedButton>
                )}
            </div>
        </div>
    );
};

