import React, { useEffect, useState, useMemo } from 'react';
import { SlantedButton } from '../ui/SlantedButton';
import { GameText } from '../ui/GameText';
import { useUser } from '../../contexts/UserContext';
import { useSynchronizedAction } from '../../hooks/useSynchronizedAction';
import { CreditIcon, GoldIcon, TokenIcon } from '../ui/CurrencyIcons';
import { api } from '../../services/api';

interface StoreResourceItemProps {
    type: 'gold' | 'credits' | 'tokens';
    amount: number;
    costLabel: string;
    costAmount?: number;
    costType: 'gold' | 'real' | 'free';
    offerId?: string;
    availableAt?: string;
}

const SUCCESS_WINDOW = 800; // Shared theatrical duration

export const StoreResourceItem: React.FC<StoreResourceItemProps> = ({ 
    type, amount, costLabel, costAmount, costType, offerId, availableAt 
}) => {
    const { user, storeData, performSynchronizedAction, syncStore } = useUser();
    const [timeLeft, setTimeLeft] = useState<number>(0);

    const isFree = costType === 'free';
    const hasFunds = isFree || costType === 'real' || (costType === 'gold' && user.gold >= (costAmount || 0));

    useEffect(() => {
        if (!availableAt) return;
        const updateTimer = () => {
            const now = Date.now();
            const target = new Date(availableAt).getTime();
            const diff = Math.max(0, Math.floor((target - now) / 1000));
            setTimeLeft(diff);
        };
        updateTimer();
        const interval = setInterval(updateTimer, 1000);
        return () => clearInterval(interval);
    }, [availableAt]);

    const { status, holdProgress, isHolding, execute, bind } = useSynchronizedAction({
        // Requirement: Hold to purchase if NOT free. Tap if free.
        holdDuration: isFree ? 0 : 800,
        onAction: async () => {
            if (!hasFunds) {
                syncStore();
                return false;
            }
            if (!offerId) return false;

            return await performSynchronizedAction(
                () => api.purchaseOffer(user, offerId, `txn_${Math.random()}`),
                { visualDelay: SUCCESS_WINDOW }
            );
        }
    });

    const isLocked = timeLeft > 0;
    const isSuccess = status === 'success';
    const isProcessing = status === 'processing';

    const isPermanentlyClaimed = useMemo(() => {
        const offer = storeData?.offers.find(o => o.id === offerId);
        return offer?.isOneTime && user.purchasedOfferIds.includes(offerId || '');
    }, [user.purchasedOfferIds, offerId, storeData]);

    const showSuccess = isSuccess || isPermanentlyClaimed;
    const colors = type === 'gold' ? { text: 'text-amber-500', bg: 'bg-amber-400/30' } : (type === 'tokens' ? { text: 'text-red-500', bg: 'bg-red-400/30' } : { text: 'text-blue-400', bg: 'bg-blue-400/30' });

    return (
        <div 
            className={`bg-gradient-to-b from-slate-800 via-slate-900 to-black border-2 transition-all duration-300 rounded p-2 flex flex-col items-center justify-between h-[10.5rem] relative overflow-hidden shadow-2xl ${showSuccess ? 'border-emerald-400 ring-2 ring-emerald-500/50 bg-emerald-950' : 'border-slate-700'}`}
            {...(isFree || isLocked || isPermanentlyClaimed ? {} : bind)}
        >
            {isSuccess && <div className="absolute inset-0 bg-white/20 animate-pulse z-40 pointer-events-none" />}

            {holdProgress > 0 && status === 'idle' && !isLocked && !isPermanentlyClaimed && (
                <div className={`absolute inset-y-0 left-0 z-0 pointer-events-none ${colors.bg}`} style={{ width: `${holdProgress}%` }} />
            )}

            <div className="relative z-10 text-center w-full px-1">
                <div className="h-6 w-full mb-0.5">
                    <GameText text={amount.toLocaleString()} baseFontSize={1.1} className="text-white drop-shadow-md" />
                </div>
                <div className={`text-[0.45rem] font-black uppercase tracking-[0.2em] leading-none ${colors.text}`}>{type}</div>
            </div>

            <div className="relative z-10 flex-1 flex items-center justify-center">
                <div className={`w-12 h-12 rounded-full flex items-center justify-center border-2 transition-all duration-500 ${showSuccess ? 'bg-emerald-500 border-emerald-300 scale-110 shadow-[0_0_20px_rgba(16,185,129,0.8)]' : 'bg-slate-900 border-slate-700'}`}>
                    {showSuccess ? (
                        <svg className="w-7 h-7 text-white animate-pop" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M5 13l4 4L19 7" /></svg>
                    ) : (
                        type === 'gold' ? <GoldIcon size="md" /> : (type === 'tokens' ? <TokenIcon size="md" /> : <CreditIcon size="md" />)
                    )}
                </div>
            </div>

            <div className="w-full relative z-10">
                <div className="h-3 flex items-center justify-center mb-0.5 overflow-visible">
                    {isHolding && !isLocked && !isPermanentlyClaimed ? (
                         <span className="text-[0.45rem] font-black text-white uppercase tracking-widest animate-pulse drop-shadow-black">Hold to Buy</span>
                    ) : isProcessing ? (
                         <span className="text-[0.45rem] font-black text-cyan-300 uppercase tracking-[0.3em] leading-none animate-pulse drop-shadow-cyan">Syncing...</span>
                    ) : showSuccess ? (
                         <span className="text-[0.45rem] font-black text-emerald-400 uppercase tracking-[0.3em] leading-none animate-bounce drop-shadow-emerald">Deposited</span>
                    ) : null}
                </div>

                {isLocked ? (
                    <div className="h-8 w-full bg-slate-900 border border-slate-700 rounded flex items-center justify-center gap-1.5 grayscale opacity-60">
                         <svg className="w-2.5 h-2.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                         <span className="text-[0.6rem] font-black tabular-nums">{Math.floor(timeLeft / 60)}:{(timeLeft % 60).toString().padStart(2, '0')}</span>
                    </div>
                ) : (
                    <SlantedButton 
                        variant={showSuccess ? 'success' : (type === 'gold' ? 'primary' : (type === 'tokens' ? 'danger' : 'blue'))} 
                        size="sm" 
                        fullWidth
                        onClick={execute}
                        disabled={isProcessing || showSuccess}
                    >
                        {isProcessing ? 'AUTHORIZING' : (showSuccess ? 'SYNCED' : costLabel)}
                    </SlantedButton>
                )}
            </div>
        </div>
    );
};

import React, { useState, useEffect } from 'react';
import { StoreOffer } from '../../types';
import { SlantedButton } from '../ui/SlantedButton';
import { OfferItemView } from './OfferItemView';
import { useUser } from '../../contexts/UserContext';
import { audio } from '../../services/audio';
import { ModalBackdrop } from '../ui/ModalBackdrop';

interface StoreOfferDetailOverlayProps {
    offer: StoreOffer;
    onClose: () => void;
}

export const StoreOfferDetailOverlay: React.FC<StoreOfferDetailOverlayProps> = ({ offer, onClose }) => {
    const { performSynchronizedAction, api } = useUser() as any; 
    // Fallback if useUser types are strictly defined without performSynchronizedAction
    const context = useUser();

    const [isPurchasing, setIsPurchasing] = useState(false);
    const [holdProgress, setHoldProgress] = useState(0);
    const [isHolding, setIsHolding] = useState(false);
    const [status, setStatus] = useState<'idle' | 'success'>('idle');

    const isFree = offer.priceType === 'free';

    // Sync victory audio with visual success
    useEffect(() => {
        if (status === 'success') {
            audio.play('sfx_victory', 0.6);
        }
    }, [status]);

    const handlePurchase = async (e: React.MouseEvent) => {
        if (e) e.stopPropagation();
        if (status !== 'idle') return;

        setIsPurchasing(true);

        // Use the context's synchronized action engine for bundles as well
        const success = await context.performSynchronizedAction(
            () => api.purchaseOffer(context.user, offer.id, `txn_${Math.random()}`),
            { visualDelay: 800 }
        );

        if (success) {
            setStatus('success');
            // Auto-close after fanfare duration
            setTimeout(() => {
                onClose();
            }, 4000);
        } else {
            setIsPurchasing(false);
        }
    };

    return (
        <ModalBackdrop onClose={onClose} showCloseHint={status === 'idle'} blurAmount="lg" className="p-0">
            <div 
                className={`w-full h-full flex flex-col bg-slate-950/40 animate-pop relative ${status === 'success' ? 'pointer-events-none' : ''}`}
                onClick={e => e.stopPropagation()}
            >
                {status === 'success' && (
                    <div className="absolute inset-0 bg-white/10 animate-pulse z-50 pointer-events-none" />
                )}

                <div className="relative h-48 shrink-0 overflow-hidden border-b border-slate-800">
                    <img src={offer.imageUrl} className="absolute inset-0 w-full h-full object-cover opacity-60" alt="" />
                    <div className="absolute inset-0 bg-gradient-to-t from-slate-950 via-slate-950/40 to-transparent"></div>

                    {status === 'idle' && (
                        <button 
                            onClick={onClose}
                            className="absolute top-4 right-4 w-10 h-10 rounded-full bg-black/50 border border-white/20 flex items-center justify-center text-white z-20 active:scale-90 transition-transform"
                        >
                            <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                        </button>
                    )}

                    <div className="absolute bottom-4 left-6 right-6 z-10">
                        <h1 className="text-3xl font-black text-white italic tracking-tighter uppercase drop-shadow-lg leading-none mb-1">
                            {offer.title}
                        </h1>
                        <p className="text-xs text-slate-300 font-medium drop-shadow leading-relaxed">
                            {offer.description}
                        </p>
                    </div>
                </div>

                <div className="flex-1 overflow-y-auto p-4 space-y-8">
                    <section>
                        <h3 className="text-[0.65rem] font-black text-slate-500 uppercase tracking-widest mb-4">Bundle Contents</h3>
                        <div className="grid grid-cols-2 gap-4">
                            {offer.contents.map((item, idx) => (
                                <OfferItemView key={idx} item={item} />
                            ))}
                        </div>
                    </section>

                    <section className="pb-32 pt-4"> 
                        <div className="relative group">
                            <div className={`absolute -inset-1 rounded-lg blur opacity-25 transition duration-1000 ${status === 'success' ? 'bg-emerald-500 opacity-70' : 'bg-gradient-to-r from-emerald-600 to-indigo-600 group-hover:opacity-50'}`}></div>

                            <div className="h-1 flex items-center justify-center mb-1 overflow-visible pointer-events-none">
                                {isHolding && status === 'idle' && !isFree && (
                                    <div className="relative font-black text-[0.6rem] uppercase tracking-widest">
                                        <span className="text-slate-600 whitespace-nowrap italic">HOLD TO BUY</span>
                                        <div 
                                            className="absolute inset-0 text-cyan-300 shadow-[0_0_10px_rgba(34,211,238,0.8)] whitespace-nowrap overflow-hidden transition-all duration-75 ease-linear italic"
                                            style={{ width: `${holdProgress}%` }}
                                        >
                                            HOLD TO BUY
                                        </div>
                                    </div>
                                )}
                                {status === 'success' && (
                                    <span className="text-[0.7rem] font-black text-emerald-400 uppercase tracking-[0.3em] italic animate-pulse drop-shadow-[0_0_5px_rgba(52,211,153,0.8)]">TRANSACTION AUTHORIZED</span>
                                )}
                            </div>

                            <SlantedButton 
                                variant={status === 'success' ? 'success' : 'success'} 
                                fullWidth 
                                size="lg" 
                                onClick={handlePurchase}
                                disabled={isPurchasing || status === 'success'}
                                holdDuration={isFree ? 0 : 1000}
                                onHoldChange={setIsHolding}
                                onProgressChange={setHoldProgress}
                            >
                                {status === 'success' ? 'SYNCED' : (isPurchasing ? 'SYNCING...' : offer.price)}
                            </SlantedButton>
                        </div>
                        <p className="mt-6 text-[0.6rem] text-slate-500 font-bold text-center uppercase tracking-[0.2em] leading-relaxed">
                            Cards added to collection instantly.<br/>Authoritative transaction via Galactic Proxy.
                        </p>
                    </section>
                </div>
            </div>
        </ModalBackdrop>
    );
};

import React, { createContext, useContext, useState, ReactNode, useCallback } from 'react';
import { CardInstance, CardDefinition, LocationDefinition, SeasonRewardType, ProgressionRewardType } from '../types';
import { audio } from '../services/audio';

interface BoxReward {
    type: 'box';
    boxType: 'MYSTERY' | 'MEGA';
    title: string;
    description: string;
}

export interface SeasonRewardInfo {
    type: 'level_info';
    level: number;
    rewardType: SeasonRewardType | ProgressionRewardType;
    rewardAmount: string | number;
    isClaimed?: boolean;
    cardDef?: CardDefinition;
}

interface InspectingCard {
    data: CardInstance | CardDefinition;
    borderOverride?: string;
}

interface UIContextType {
    inspectingCard: InspectingCard | null;
    inspectingLocation: LocationDefinition | null;
    inspectingCurrency: { type: 'gold' | 'credits', amount: number } | null;
    inspectingBox: BoxReward | null;
    inspectingReward: SeasonRewardInfo | null;
    inspect: (item: any, options?: { borderOverride?: string }) => void;
    closeInspector: () => void;
    storeScrollTarget: string | null;
    setStoreScrollTarget: (id: string | null) => void;
}

const UIContext = createContext<UIContextType | null>(null);

export const UIProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
    const [inspectingCard, setInspectingCard] = useState<InspectingCard | null>(null);
    const [inspectingLocation, setInspectingLocation] = useState<LocationDefinition | null>(null);
    const [inspectingCurrency, setInspectingCurrency] = useState<{ type: 'gold' | 'credits', amount: number } | null>(null);
    const [inspectingBox, setInspectingBox] = useState<BoxReward | null>(null);
    const [inspectingReward, setInspectingReward] = useState<SeasonRewardInfo | null>(null);
    const [storeScrollTarget, setStoreScrollTarget] = useState<string | null>(null);

    const inspect = useCallback((item: any, options?: { borderOverride?: string }) => {
        if (!item) return; 
        audio.playUiClick();

        // Reset all
        setInspectingCurrency(null); 
        setInspectingCard(null); 
        setInspectingLocation(null); 
        setInspectingBox(null); 
        setInspectingReward(null);

        if ('type' in item) {
            if (item.type === 'gold' || item.type === 'credits') setInspectingCurrency(item);
            else if (item.type === 'box') setInspectingBox(item);
            else if (item.type === 'level_info') setInspectingReward(item);
        } 
        else if (('instanceId' in item) || ('basePower' in item) || ('definitionId' in item)) {
            setInspectingCard({ data: item, borderOverride: options?.borderOverride });
        }
        else if ('description' in item) {
            setInspectingLocation(item);
        }
    }, []);

    const closeInspector = useCallback(() => { 
        setInspectingCard(null); 
        setInspectingLocation(null); 
        setInspectingCurrency(null); 
        setInspectingBox(null); 
        setInspectingReward(null); 
    }, []);

    return (
        <UIContext.Provider value={{ 
            inspectingCard, inspectingLocation, inspectingCurrency, inspectingBox, inspectingReward,
            inspect, closeInspector, storeScrollTarget, setStoreScrollTarget
        }}>
            {children}
        </UIContext.Provider>
    );
};

export const useUI = () => {
    const context = useContext(UIContext);
    if (!context) throw new Error('useUI must be used within a UIProvider');
    return context;
};

import React, { createContext, useContext, useState, ReactNode, useEffect, useCallback, useMemo } from 'react';
import { UserProfile, StoreData, CardDefinition, CardRarity, SeasonPassData, ProgressionData, ActivityLogEntry, PurchaseResponse } from '../types';
import { audio } from '../services/audio';
import { api } from '../services/api';
import { CARDS } from '../constants';

export type CollectionSortOption = 'Cost' | 'Power' | 'Name' | 'Newest';

interface UserContextType {
    user: UserProfile;
    storeData: StoreData | null;
    isStoreLoading: boolean;
    seasonPassData: SeasonPassData | null;
    isSeasonLoading: boolean;
    syncSeasonPass: () => Promise<void>;
    debugSwitchSeason: () => Promise<void>; 
    progressionData: ProgressionData | null;
    activityLog: ActivityLogEntry[];
    isProgressionLoading: boolean;
    syncProgression: (showLoading?: boolean) => Promise<void>;

    // Data filtering state
    collectionSort: CollectionSortOption;
    setCollectionSort: (s: CollectionSortOption) => void;
    collectionFilterSearch: string;
    setCollectionFilterSearch: (s: string) => void;
    collectionFilterTags: string[];
    toggleCollectionFilterTag: (tag: string) => void;

    // Authoritative Actions
    performSynchronizedAction: (apiCall: () => Promise<PurchaseResponse>, options?: { visualDelay?: number, sfx?: string }) => Promise<boolean>;
    syncStore: () => Promise<void>;
    upgradeCard: (id: string) => void;
    setActiveDeck: (id: number) => void;
    updateDeck: (id: number, cardIds: string[]) => void;
    activeDeck: string[];
}

const UserContext = createContext<UserContextType | null>(null);

export const UserProvider: React.FC<{ children: ReactNode; initialUser: UserProfile }> = ({ children, initialUser }) => {
    const [user, setUser] = useState<UserProfile>(initialUser);
    const [storeData, setStoreData] = useState<StoreData | null>(null);
    const [isStoreLoading, setIsStoreLoading] = useState(false);
    const [seasonPassData, setSeasonPassData] = useState<SeasonPassData | null>(null);
    const [isSeasonLoading, setIsSeasonLoading] = useState(false);
    const [progressionData, setProgressionData] = useState<ProgressionData | null>(null);
    const [activityLog, setActivityLog] = useState<ActivityLogEntry[]>([]);
    const [isProgressionLoading, setIsProgressionLoading] = useState(false);

    const [collectionSort, setCollectionSort] = useState<CollectionSortOption>('Cost');
    const [collectionFilterSearch, setCollectionFilterSearch] = useState('');
    const [collectionFilterTags, setCollectionFilterTags] = useState<string[]>([]);

    const toggleCollectionFilterTag = useCallback((tag: string) => {
        setCollectionFilterTags(prev => prev.includes(tag) ? prev.filter(t => t !== tag) : [...prev, tag]);
    }, []);

    const syncSeasonPass = useCallback(async () => {
        setIsSeasonLoading(true);
        try {
            const data = await api.getSeasonPass(user);
            setSeasonPassData(data);
        } catch (e) {
            console.error("Season Sync Failed", e);
        } finally {
            setIsSeasonLoading(false);
        }
    }, [user]);

    const debugSwitchSeason = useCallback(async () => {
        setIsSeasonLoading(true);
        try {
            await api.debugNextSeason();
            await syncSeasonPass();
        } catch (e) {
            console.error("Debug Switch Season Failed", e);
        } finally {
            setIsSeasonLoading(false);
        }
    }, [syncSeasonPass]);

    const syncProgression = useCallback(async (showLoading = false) => {
        if (showLoading) setIsProgressionLoading(true);
        try {
            const data = await api.getProgression(user);
            const logs = await api.getActivityLog();
            setProgressionData(data);
            setActivityLog(logs);
        } catch (e) {
            console.error("Progression Sync Failed", e);
        } finally {
            setIsProgressionLoading(false);
        }
    }, [user]);

    const syncStore = useCallback(async (showLoading = false) => {
        if (showLoading) setIsStoreLoading(true);
        try {
            const data = await api.getStoreOffers(user);
            setStoreData(data);
        } catch (e) {
            console.error("Store Sync Failed", e);
        } finally {
            setIsStoreLoading(false);
        }
    }, [user]);

    const performSynchronizedAction = async (
        apiCall: () => Promise<PurchaseResponse | any>, 
        options?: { visualDelay?: number, sfx?: string }
    ): Promise<boolean> => {
        try {
            const result = await apiCall();
            if (result.success && result.updatedProfile) {
                if (options?.visualDelay) {
                    await new Promise(resolve => setTimeout(resolve, options.visualDelay));
                }
                setUser(result.updatedProfile);
                if ('progressionData' in result && result.progressionData) setProgressionData(result.progressionData);
                if ('activityLog' in result && result.activityLog) setActivityLog(result.activityLog);
                audio.play((options?.sfx || 'sfx_victory') as any, 0.5);
                return true;
            }
        } catch (err) {
            console.error("Synchronized Action Failed:", err);
        }
        return false;
    };

    const upgradeCard = useCallback((cardId: string) => {
        setUser(prev => {
            const def = CARDS.find(c => c.id === cardId);
            if (!def) return prev;
            const currentRarity = prev.cardRarities[cardId] || def.rarity;
            const rarityPath: CardRarity[] = ["Common", "Rare", "Epic", "Legendary"];
            const nextRarity = rarityPath[rarityPath.indexOf(currentRarity) + 1];
            if (!nextRarity) return prev;
            const costMap: Record<string, number> = { "Rare": 100, "Epic": 400, "Legendary": 1000 };
            const cost = costMap[nextRarity];
            if (prev.credits >= cost) {
                audio.play('sfx_victory', 0.6);
                return {
                    ...prev,
                    credits: prev.credits - cost,
                    level: prev.level + 1,
                    cardRarities: { ...prev.cardRarities, [cardId]: nextRarity }
                };
            }
            return prev;
        });
    }, []);

    const setActiveDeck = useCallback(async (deckId: number) => {
        try {
            const updated = await api.updateActiveDeck(user, deckId);
            setUser(updated);
        } catch (e) {
            console.error("Update active deck failed", e);
        }
    }, [user]);

    const updateDeck = useCallback((deckId: number, cardIds: string[]) => {
        setUser(prev => ({
            ...prev,
            decks: { ...prev.decks, [deckId]: cardIds }
        }));
    }, []);

    useEffect(() => {
        syncStore(true);
        syncSeasonPass();
        syncProgression(true);
    }, [user.id, syncStore, syncSeasonPass, syncProgression]);

    const activeDeck = useMemo(() => user.decks[user.activeDeckId] || [], [user.decks, user.activeDeckId]);

    return (
        <UserContext.Provider value={{ 
            user, storeData, isStoreLoading,
            seasonPassData, isSeasonLoading, syncSeasonPass, debugSwitchSeason,
            progressionData, activityLog, isProgressionLoading, syncProgression,
            collectionSort, setCollectionSort, collectionFilterSearch, setCollectionFilterSearch,
            collectionFilterTags, toggleCollectionFilterTag,
            performSynchronizedAction, syncStore, 
            upgradeCard, setActiveDeck, updateDeck, activeDeck
        }}>{children}</UserContext.Provider>
    );
};

export const useUser = () => {
    const context = useContext(UserContext);
    if (!context) throw new Error('useUser must be used within a UserProvider');
    return context;
};

import React, { useState, useLayoutEffect, useRef } from 'react';

interface GameTextProps {
  text: string;
  className?: string;
  baseFontSize: number; // in rem
  maxScale?: number;
  minScale?: number;
  skewFactor?: number; 
  maxLines?: number;
}

// Global cache for text measurements to prevent DOM churn
const MEASUREMENT_CACHE: Record<string, { w: number, h: number }> = {};

/**
 * HIGH-PRECISION TEXT SCALING ENGINE
 * Optimized for performance with a global measurement cache.
 */
export const GameText: React.FC<GameTextProps> = React.memo(({ 
  text, 
  className = '', 
  baseFontSize,
  maxScale = 1.0,
  minScale = 0.2,
  skewFactor = 1.0,
  maxLines = 1
}) => {
  const [scale, setScale] = useState(1);
  const containerRef = useRef<HTMLDivElement>(null);
  const textRef = useRef<HTMLDivElement>(null);

  useLayoutEffect(() => {
    let rafId: number;

    const measure = () => {
      const container = containerRef.current;
      const textEl = textRef.current;
      if (!container || !textEl) return;

      const containerW = container.clientWidth * skewFactor;
      const containerH = container.clientHeight;

      if (containerW <= 0 || containerH <= 0) {
        rafId = requestAnimationFrame(measure);
        return;
      }

      const cacheKey = `${text}_${baseFontSize}_${skewFactor}_${maxLines}`;
      let dims = MEASUREMENT_CACHE[cacheKey];

      if (!dims) {
        // MEASUREMENT CLONE
        const clone = document.createElement('div');
        clone.style.position = 'absolute';
        clone.style.visibility = 'hidden';
        clone.style.left = '-9999px';
        clone.style.top = '-9999px';
        clone.style.fontSize = `${baseFontSize}rem`;

        const computedStyle = getComputedStyle(textEl);
        clone.style.fontFamily = computedStyle.fontFamily;
        clone.style.fontWeight = computedStyle.fontWeight;
        clone.style.fontStyle = computedStyle.fontStyle;
        clone.style.letterSpacing = computedStyle.letterSpacing;
        clone.style.textTransform = computedStyle.textTransform;
        clone.style.lineHeight = '0.85'; 
        clone.style.textAlign = 'center';
        clone.style.whiteSpace = 'pre';
        clone.style.width = 'auto';
        clone.innerText = text;

        document.body.appendChild(clone);
        dims = { w: clone.scrollWidth, h: clone.scrollHeight };
        document.body.removeChild(clone);

        MEASUREMENT_CACHE[cacheKey] = dims;
      }

      const scaleW = containerW / (dims.w || 1);
      const scaleH = containerH / (dims.h || 1);
      const targetScale = Math.min(scaleW, scaleH);
      const finalScale = Math.min(maxScale, Math.max(minScale, targetScale));

      setScale(finalScale);
    };

    measure();

    if (typeof ResizeObserver !== 'undefined' && containerRef.current) {
        const observer = new ResizeObserver(measure);
        observer.observe(containerRef.current);
        return () => {
            observer.disconnect();
            cancelAnimationFrame(rafId);
        };
    }
  }, [text, baseFontSize, maxScale, minScale, skewFactor, maxLines]);

  return (
    <div 
        ref={containerRef}
        className={`w-full h-full flex justify-center items-center overflow-hidden pointer-events-none select-none ${className}`}
        style={{ fontSize: `${baseFontSize}rem` }}
    >
      <div 
        ref={textRef}
        style={{ 
          transform: scale < 1 ? `scale(${scale})` : 'none',
          transformOrigin: 'center center',
          display: 'flex', 
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          width: 'max-content',
          lineHeight: 0.85,
          textAlign: 'center',
          whiteSpace: 'pre',
        }} 
        className="transition-transform duration-300 ease-out will-change-transform"
      >
        {text}
      </div>
    </div>
  );
});

