// Helper to generate progression tracks based on User Profile Data
const getProgressionDataInternal = (user: UserProfile): ProgressionData => {
    // Only use the 4 specific tracks requested by the user
    const tracksToRender: ProgressionRewardType[] = ['booster', 'credits', 'box', 'tokens'];

    const tracks: ProgressionTrack[] = tracksToRender.map(type => {
        const config = PROGRESSION_CONFIGS[type];

        // Deterministic Calculation:
        // Total Earned = floor((CollectionLevel + Seed) / Cycle)
        const totalEarned = Math.floor((user.level + config.seed) / config.cycle);
        const claimed = user.claimedProgressionCounts[type] || 0;
        const unclaimedCount = Math.max(0, totalEarned - claimed);

        // Progress visuals
        const currentXP = (user.level + config.seed) % config.cycle;

        return {
            type,
            label: config.label,
            currentXP,
            targetXP: config.cycle,
            unclaimedCount,
            nextRewardAmount: config.amount,
        };
    });

    return {
        collectionLevel: user.level,
        tracks
    };
};

