const getProgressionDataInternal = (user: UserProfile): ProgressionData => {
    const totalXp = user.level * XP_PER_LEVEL;
    const fullCycles = Math.floor(totalXp / TOTAL_CYCLE_XP);
    const remainderXp = totalXp % TOTAL_CYCLE_XP;

    const tracks: ProgressionTrack[] = REWARD_SEQUENCE.map((reward, i) => {
        const rewardUnlockXp = CUMULATIVE_XP[i];
        const prevUnlockXp = i === 0 ? 0 : CUMULATIVE_XP[i-1];

        // Deterministic total earned for this specific slot in the sequence
        const earnedInFullCycles = fullCycles;
        const earnedInRemainder = remainderXp >= rewardUnlockXp ? 1 : 0;
        const totalEarned = earnedInFullCycles + earnedInRemainder;

        const claimed = progressionStore.claimedCounts[i];
        const unclaimedCount = Math.max(0, totalEarned - claimed);

        // Progress within the current step (relative to the previous reward in sequence)
        let currentXP = 0;
        if (remainderXp >= rewardUnlockXp) {
            currentXP = reward.xpStep; // Completed
        } else if (remainderXp > prevUnlockXp) {
            currentXP = remainderXp - prevUnlockXp; // In progress
        } else {
            currentXP = 0; // Not yet started this cycle
        }

        return {
            type: reward.type,
            label: reward.label,
            currentXP,
            targetXP: reward.xpStep,
            unclaimedCount,
            nextRewardAmount: reward.amount,
        };
    });

    return {
        collectionLevel: user.level,
        tracks
    };
};

