/**
 * PRODUCTION-GRADE MOCK BACKEND
 */

// --- LINEAR SEQUENCE CONFIG ---
// 1 Level = 5 XP. 
// Cycle: 15 + 15 + 15 + 15 + 15 + 40 = 115 XP (23 Levels)
const XP_PER_LEVEL = 5;
const TOTAL_CYCLE_XP = 115;

const REWARD_SEQUENCE: { type: ProgressionRewardType, label: string, amount: number | string, xpStep: number }[] = [
    { type: 'booster', label: 'Boosters',     amount: 10,   xpStep: 15 },
    { type: 'credits', label: 'Credits',      amount: 50,   xpStep: 15 },
    { type: 'box',     label: 'Omega Box I',  amount: 1,    xpStep: 15 },
    { type: 'gold',    label: 'Gold',         amount: 25,   xpStep: 15 },
    { type: 'box',     label: 'Omega Box II', amount: 1,    xpStep: 15 },
    { type: 'tokens',  label: 'Tokens',       amount: 1000, xpStep: 40 }
];

// Calculate the exact XP offset required for each bar to "pop" at the right linear interval
// We want: 15, 30, 45, 60, 75, 115
const CUMULATIVE_UNLOCKS = REWARD_SEQUENCE.reduce((acc, curr, i) => {
    const prev = i === 0 ? 0 : acc[i-1];
    acc.push(prev + curr.xpStep);
    return acc;
}, [] as number[]);

// PERSISTENT PROGRESSION STATE (Mock Database)
let progressionStore = {
    claimedCounts: [0, 0, 0, 0, 0, 0],
    activityLog: [
        { id: 'log_0', title: "1000 Tokens", type: 'tokens', date: "15 MAY", time: "10:30", amount: 1000 },
        { id: 'log_1', title: "Portal Mage", type: 'card', date: "14 MAY", time: "22:15", cardDef: CARDS[8] },
        { id: 'log_2', title: "Omega Box", type: 'box', date: "12 MAY", time: "14:20" },
        { id: 'log_3', title: "500 Credits", type: 'credits', date: "11 MAY", time: "09:45", amount: 500 },
    ] as ActivityLogEntry[]
};

const getProgressionDataInternal = (user: UserProfile): ProgressionData => {
    const totalXp = user.level * XP_PER_LEVEL;
    const fullCycles = Math.floor(totalXp / TOTAL_CYCLE_XP);
    const remainderXp = totalXp % TOTAL_CYCLE_XP;

    const tracks: ProgressionTrack[] = REWARD_SEQUENCE.map((reward, i) => {
        const unlockAt = CUMULATIVE_UNLOCKS[i];
        const prevUnlock = i === 0 ? 0 : CUMULATIVE_UNLOCKS[i-1];

        // 1. Calculate how many times this specific slot has been EARNED
        const earnedInFullCycles = fullCycles;
        const earnedInRemainder = remainderXp >= unlockAt ? 1 : 0;
        const totalEarned = earnedInFullCycles + earnedInRemainder;

        // 2. Compare against CLAIMED count for this specific slot
        const claimed = progressionStore.claimedCounts[i];
        const unclaimedCount = Math.max(0, totalEarned - claimed);

        // 3. Calculate current bar progress (0 to xpStep)
        // If we are currently "in" this step of the cycle
        let currentXP = 0;
        if (remainderXp >= unlockAt) {
            currentXP = reward.xpStep; // This step is finished in the current cycle
        } else if (remainderXp > prevUnlock) {
            currentXP = remainderXp - prevUnlock; // We are partway through this step
        } else {
            currentXP = 0; // Cycle hasn't reached this step yet
        }

        return {
            type: reward.type,
            label: reward.label,
            currentXP,
            targetXP: reward.xpStep,
            unclaimedCount,
            nextRewardAmount: reward.amount,
        };
    });

    return {
        collectionLevel: user.level,
        tracks
    };
};

