        await new Promise(resolve => setTimeout(resolve, 500));
        const season = SEASONS[currentSeasonIndex];
        const userProgress = user.seasonProgress[season.id] || { level: 1, xp: 0 };
        const endDate = "2025-12-31T23:59:59Z";
        const rewards: SeasonPassReward[] = Array.from({ length: 100 }, (_, i) => {
            const level = i + 1;
            let type: SeasonRewardType = 'credits';
            let amount: string | number = 50;
            let specificCardDef = undefined;
            if (level === 50) { type = 'card'; amount = 'SEASON EXCLUSIVE'; specificCardDef = CARDS.find(c => c.id === season.heroCardId)!; } 
            else if (level % 10 === 0) { type = 'card'; amount = 'VARIANT'; specificCardDef = CARDS[Math.floor((level / 10) % CARDS.length)]; } 
            else if (level % 5 === 0) { type = 'gold'; amount = 100; } 
            else if (level % 2 === 0) { type = 'booster'; amount = 10; } 
            else { type = 'credits'; amount = 50 + (Math.floor(level / 10) * 10); }
            return { level, type, amount, cardDef: specificCardDef, isClaimed: level < userProgress.level, isActive: level === userProgress.level, isLocked: level > userProgress.level };
        });
        return { id: season.id, themeName: season.name, startDate: "2025-01-01T00:00:00Z", endDate, endsInSeconds: Math.floor((new Date(endDate).getTime() - Date.now()) / 1000), premiumActive: true, heroCardId: season.heroCardId, heroVariantName: season.heroVariant, rewards };
