// --- LINEAR SEQUENCE CONFIG ---
// 1 Level = 5 XP. 
// Cycle: 15 + 15 + 15 + 15 + 15 + 40 = 115 XP (23 Levels)
const XP_PER_LEVEL = 5;
const TOTAL_CYCLE_XP = 115;

const REWARD_SEQUENCE: { type: ProgressionRewardType, label: string, amount: number | string, xpStep: number }[] = [
    { type: 'booster', label: 'Boosters',     amount: 10,   xpStep: 15 },
    { type: 'credits', label: 'Credits',      amount: 50,   xpStep: 15 },
    { type: 'gold',    label: 'Gold',         amount: 25,   xpStep: 15 },
    { type: 'box',     label: 'Omega Box',    amount: 1,    xpStep: 15 },
    { type: 'box',     label: 'Omega Box',    amount: 1,    xpStep: 15 },
    { type: 'tokens',  label: 'Tokens',       amount: 1000, xpStep: 40 }
];

// Calculate the exact XP offset required for each bar to "pop" at the right linear interval
// We want: 15, 30, 45, 60, 75, 115
const CUMULATIVE_UNLOCKS = REWARD_SEQUENCE.reduce((acc, curr, i) => {
    const prev = i === 0 ? 0 : acc[i-1];
    acc.push(prev + curr.xpStep);
    return acc;
}, [] as number[]);

