const getProgressionDataInternal = (user: UserProfile): ProgressionData => {
    const totalXp = user.level * XP_PER_LEVEL;
    const fullCycles = Math.floor(totalXp / TOTAL_CYCLE_XP);
    const remainderXp = totalXp % TOTAL_CYCLE_XP;

    const tracks: ProgressionTrack[] = REWARD_SEQUENCE.map((reward, i) => {
        const unlockAt = CUMULATIVE_UNLOCKS[i];
        const prevUnlock = i === 0 ? 0 : CUMULATIVE_UNLOCKS[i-1];

        // 1. Calculate how many times this specific slot has been EARNED
        const earnedInFullCycles = fullCycles;
        const earnedInRemainder = remainderXp >= unlockAt ? 1 : 0;
        const totalEarned = earnedInFullCycles + earnedInRemainder;

        // 2. Compare against CLAIMED count for this specific slot
        const claimed = progressionStore.claimedCounts[i];
        const unclaimedCount = Math.max(0, totalEarned - claimed);

        // 3. Calculate current bar progress (0 to xpStep)
        let currentXP = 0;
        if (remainderXp >= unlockAt) {
            currentXP = reward.xpStep; 
        } else if (remainderXp > prevUnlock) {
            currentXP = remainderXp - prevUnlock; 
        } else {
            currentXP = 0; 
        }

        return {
            type: reward.type,
            label: reward.label,
            currentXP,
            targetXP: reward.xpStep,
            unclaimedCount,
            nextRewardAmount: reward.amount,
        };
    });

    return {
        collectionLevel: user.level,
        tracks
    };
};

