const getProgressionDataInternal = (user: UserProfile): ProgressionData => {
    // 1. Calculate how much total XP the user has earned via CL
    const totalXp = user.level * XP_PER_LEVEL;
    const fullCycles = Math.floor(totalXp / TOTAL_CYCLE_XP);
    const remainderXp = totalXp % TOTAL_CYCLE_XP;

    const tracks: ProgressionTrack[] = REWARD_SEQUENCE.map((reward, i) => {
        const unlockAtThreshold = CUMULATIVE_UNLOCKS[i];
        const prevUnlockThreshold = i === 0 ? 0 : CUMULATIVE_UNLOCKS[i-1];

        // 2. MATHEMATICAL CALCULATION: How many times has this slot actually been EARNED?
        const earnedInFullCycles = fullCycles;
        const earnedInRemainder = remainderXp >= unlockAtThreshold ? 1 : 0;
        const totalEarnedCount = earnedInFullCycles + earnedInRemainder;

        // 3. SERVER VARIABLE: How many has the user already clicked/claimed?
        const claimed = progressionStore.claimedCounts[i];
        const unclaimedCount = Math.max(0, totalEarnedCount - claimed);

        // 4. VISUAL CALCULATION: Current progress bar fill
        let currentXPInThisStep = 0;
        if (remainderXp >= unlockAtThreshold) {
            currentXPInThisStep = reward.xpStep; // This step is complete for the current cycle
        } else if (remainderXp > prevUnlockThreshold) {
            currentXPInThisStep = remainderXp - prevUnlockThreshold; // Partway through this step
        } else {
            currentXPInThisStep = 0; // Haven't reached this step yet in current cycle
        }

        return {
            type: reward.type,
            label: reward.label,
            currentXP: currentXPInThisStep,
            targetXP: reward.xpStep,
            unclaimedCount,
            nextRewardAmount: reward.amount,
        };
    });

    return {
        collectionLevel: user.level,
        tracks
    };
};

