export const ProgressionScreen: React.FC<{ onNavigate: (screen: ScreenKey) => void }> = ({ onNavigate }) => {
    const { user, progressionData, activityLog, isProgressionLoading, performSynchronizedAction, inspect } = useUser();
    const [logFilter, setLogFilter] = useState<LogCategory>('all');

    const [claimingIdx, setClaimingIdx] = useState<number | null>(null);
    const [successIdx, setSuccessIdx] = useState<number | null>(null);

    const filteredLog = useMemo(() => {
        const base = logFilter === 'all' ? activityLog : activityLog.filter(item => item.type === logFilter);
        return base.slice(0, 500);
    }, [activityLog, logFilter]);

    const nextHero = useMemo(() => {
        if (!progressionData) return null;
        // Find the track closest to being finished in its current step
        return [...progressionData.tracks]
            .map((t, idx) => ({ ...t, idx }))
            .sort((a, b) => (a.targetXP - a.currentXP) - (b.targetXP - b.currentXP))[0];
    }, [progressionData]);

    const handleInspect = (track: ProgressionTrack) => {
        inspect({
            type: track.type === 'box' ? 'box' : 'level_info',
            level: user.level + Math.ceil((track.targetXP - track.currentXP) / 5),
            rewardType: track.type,
            rewardAmount: track.nextRewardAmount,
            boxType: 'MEGA',
            title: track.label,
            description: 'Acquired through progression.'
        });
    };

    const handleClaim = async (type: ProgressionRewardType, idx: number) => {
        if (claimingIdx !== null || successIdx !== null) return;
        setClaimingIdx(idx);
        const success = await performSynchronizedAction(() => api.claimProgressionReward(user, type), { visualDelay: 600 });
        setClaimingIdx(null);
        if (success) {
            setSuccessIdx(idx);
            setTimeout(() => setSuccessIdx(null), 2500);
        }
    };

    const getScale = (type: string) => {
        if (type === 'tokens') return 'scale-[0.85]'; 
        if (type === 'gold') return 'scale-[0.44]'; // -20% from 0.55
        if (type === 'credits') return 'scale-[0.44]'; // -20% from 0.55
        if (type === 'booster') return 'scale-[0.7]'; 
        if (type === 'box') return 'scale-[0.88]'; // +10% from 0.8
        return 'scale-[1.0]';
    };

    const getVariant = (type: ProgressionRewardType) => {
        switch(type) {
            case 'booster': return 'success';
            case 'credits': return 'blue';
            case 'gold': return 'warning';
            case 'tokens': return 'danger';
            case 'box': return 'primary';
            default: return 'secondary';
        }
    };

    const getColors = (type: ProgressionRewardType) => {
        switch(type) {
            case 'booster': return { color: 'from-emerald-400 to-emerald-600', bgTrack: 'bg-[#064e3b]', borderColor: 'border-emerald-400/50' };
            case 'credits': return { color: 'from-blue-400 to-blue-600', bgTrack: 'bg-[#1e3a8a]', borderColor: 'border-blue-400/50' };
            case 'gold': return { color: 'from-amber-400 to-amber-600', bgTrack: 'bg-[#78350f]', borderColor: 'border-amber-400/50' };
            case 'tokens': return { color: 'from-red-400 to-red-600', bgTrack: 'bg-[#450a0a]', borderColor: 'border-red-400/50' };
            case 'box': return { color: 'from-indigo-400 to-indigo-600', bgTrack: 'bg-[#1e1b4b]', borderColor: 'border-indigo-400/50' };
            default: return { color: 'from-white to-slate-400', bgTrack: 'bg-[#334155]', borderColor: 'border-white/50' };
        }
    };

    const renderFilterIcon = (cat: LogCategory) => {
        switch(cat) {
            case 'all': return <span className="font-black text-[0.65rem] -skew-x-[9deg]">ALL</span>;
            case 'credits': return <CreditIcon size="sm" />;
            case 'gold': return <GoldIcon size="sm" />;
            case 'tokens': return <TokenIcon size="sm" />;
            case 'box': return <OmegaBoxIcon size="sm" />;
            case 'booster': return <BoosterIcon size="sm" />;
            default: return null;
        }
    };

    if (!progressionData && isProgressionLoading) {
        return (
            <div className="w-full h-full flex flex-col items-center justify-center bg-slate-950/20 backdrop-blur-md">
                <div className="w-8 h-8 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mb-4" />
                <span className="text-[0.6rem] font-black text-indigo-400 uppercase tracking-[0.3em] animate-pulse">Syncing Sector Data...</span>
            </div>
        );
    }

    if (!progressionData) return null;

    return (
        <div className="w-full h-full flex flex-col bg-transparent overflow-hidden relative">
            <StandardHeader 
                title="COLLECTION LEVEL" 
                leftContent={
                    <button onClick={() => onNavigate('DECK')} className="w-8 h-8 rounded-full bg-white/5 border border-white/10 flex items-center justify-center text-white active:scale-90 transition-transform">
                        <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 19l-7-7 7-7" /></svg>
                    </button>
                }
            />

            <div className="shrink-0 pt-6 pb-2 flex flex-col items-center">
                <span className="text-[0.75rem] font-black text-white uppercase tracking-[0.45em] mb-1.5 drop-shadow-[0_0_8px_rgba(255,255,255,0.3)]">Collection Level</span>
                <div className="h-10 w-full px-4">
                    <GameText text={progressionData.collectionLevel.toLocaleString()} baseFontSize={3.2} className="text-white font-black italic tracking-tighter drop-shadow-lg" />
                </div>
            </div>

            <div className="flex-1 overflow-y-auto px-4 space-y-8 pb-32 pt-6">
                {nextHero && (
                    <div className="space-y-4">
                        <h3 className="text-[0.6rem] font-black text-white uppercase tracking-[0.3em] px-1 text-center">Next Objective</h3>
                        <div className="relative h-24 flex items-center cursor-pointer group active:scale-[0.99] transition-transform" onClick={() => handleInspect(nextHero)}>
                            <div className="absolute top-[0.1em] left-[2.8rem] right-0 h-6 z-50 pointer-events-none">
                                <GameText text={`${nextHero.nextRewardAmount} ${nextHero.label}`} baseFontSize={1.0} className="text-white font-black italic uppercase drop-shadow-black tracking-widest text-left" />
                            </div>
                            <div className="absolute left-0 z-50 drop-shadow-[0_0_25px_rgba(79,70,229,0.4)]">
                                <HexBadge variant={getVariant(nextHero.type)} size="xl" glow>
                                    <div className="relative w-full h-full overflow-visible">
                                        <div className={`absolute inset-0 flex items-center justify-center ${getScale(nextHero.type)}`}>
                                            <RewardIconGraphic type={nextHero.type as any} size="xl" />
                                        </div>
                                    </div>
                                </HexBadge>
                            </div>
                            {(() => {
                                const styles = getColors(nextHero.type)!;
                                const percent = (nextHero.currentXP / nextHero.targetXP) * 100;
                                return (
                                    <div className={`absolute left-10 right-2 h-10 ${styles.bgTrack} border-2 ${styles.borderColor} rounded-full overflow-hidden shadow-[inset_0_2px_8px_rgba(0,0,0,0.8)] z-10`}>
                                        <div className={`h-full bg-gradient-to-r ${styles.color} transition-all duration-1000 ease-out relative`} style={{ width: `${percent}%` }}>
                                            <div className="absolute inset-0 bg-white/10 animate-[pulse_3s_infinite]" />
                                        </div>
                                        <div className="absolute inset-0 flex items-center justify-center pl-12 pr-4 py-0 pointer-events-none">
                                            <GameText text={`${nextHero.currentXP} / ${nextHero.targetXP} XP`} baseFontSize={1.3} className="text-white font-black italic tracking-widest uppercase drop-shadow-black" />
                                        </div>
                                    </div>
                                );
                            })()}
                        </div>
                    </div>
                )}

                <div className="space-y-4">
                    <h3 className="text-[0.6rem] font-black text-white uppercase tracking-[0.3em] px-1 text-center">Asynchronous Staggered Tracks</h3>
                    <div className="h-px w-full bg-white/10 relative">
                        <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 w-2 h-2 bg-slate-900 border border-white/20 rotate-45" />
                    </div>
                </div>

                <div className="space-y-8">
                    {progressionData.tracks.map((track, idx) => {
                        const styles = getColors(track.type)!;
                        const variant = getVariant(track.type);
                        const percent = (track.currentXP / track.targetXP) * 100;
                        const canClaim = track.unclaimedCount > 0;
                        const isClaimingThis = claimingIdx === idx;
                        const isSuccessThis = successIdx === idx;

                        return (
                            <div key={`${track.type}-${idx}`} className="grid grid-cols-[1fr_6.5rem] gap-2 items-end">
                                <div className="relative h-16 flex items-center cursor-pointer group" onClick={() => handleInspect(track)}>
                                    <div className="absolute top-[0.1em] left-[2.4rem] right-0 h-5 z-50 pointer-events-none">
