                                        onClick={(e) => { e.stopPropagation(); handleClaim(track.type, idx); }}
                                    >
                                        {isClaimingThis ? "CLAIMING..." : (isSuccessThis ? "SUCCESS" : `CLAIM ${track.nextRewardAmount}\n${track.label}`)}
