                <div className="pt-12 pb-12">
                    <div className="flex flex-col gap-4 mb-6 px-1">
                        <div className="flex items-center gap-3">
                            <h3 className="text-[0.65rem] font-black text-white uppercase tracking-[0.4em] whitespace-nowrap">Activity Log</h3>
