     */
    const renderClaimLabel = () => {
        if (isClaiming) {
            return (
                <div className="w-full h-full flex items-center justify-center">
                    <GameText 
                        text="CLAIMING..." 
                        baseFontSize={0.8} 
                        skewFactor={0.9}
                        className="text-white/60 font-black italic animate-pulse uppercase" 
                    />
                </div>
            );
        }

        if (isSuccess) {
            return (
                <div className="w-full h-full flex items-center justify-center">
                    <GameText 
                        text="SUCCESS!" 
                        baseFontSize={0.9} 
                        skewFactor={0.9}
                        className="text-white font-black italic uppercase" 
                    />
                </div>
            );
        }

        const rewardAmount = track.nextRewardAmount;
        const rewardLabel = track.type === 'box' ? track.label : track.label.toUpperCase();

        // Single multiline string for synced scaling
        const buttonText = track.type === 'box' 
            ? `CLAIM\n${rewardLabel}` 
            : `CLAIM\n${rewardAmount} ${rewardLabel}`;

        return (
            <div className="flex items-center justify-center w-full h-full pointer-events-none px-2 py-0.5">
                <GameText 
                    text={buttonText} 
                    baseFontSize={1.0} 
                    maxScale={1.3}
                    skewFactor={0.9}
                    className="font-black italic tracking-tighter uppercase drop-shadow-md" 
                />
            </div>
        );
    };

    return (
        /* 
           FIXED ALIGNMENT: 
           Changed 'items-end' to 'items-center' so the button column centers 
           vertically against the XP bar column.
        */
        <div className="grid grid-cols-[1fr_30vw] gap-3 items-center">
            <div className="relative h-18 flex items-center cursor-pointer group" onClick={onInspect}>
                <div className="absolute top-[0.1em] left-[2.4rem] right-0 h-5 z-50 pointer-events-none">
                    <GameText text={`${track.nextRewardAmount} ${track.label}`} baseFontSize={0.7} className="text-white/90 font-black italic uppercase drop-shadow-black tracking-tighter text-left" />
                </div>
                <div className="absolute left-0 z-40 transition-transform group-hover:scale-110 origin-center drop-shadow-xl">
                    <HexBadge variant={variant} size="lg">
                        <div className="relative w-full h-full overflow-visible">
                            <div className={`absolute inset-0 flex items-center justify-center ${getScale(track.type)}`}>
                                <RewardIconGraphic type={track.type as any} size="lg" />
                            </div>
                        </div>
                    </HexBadge>
                </div>
                <div className={`absolute left-8 right-0 h-8 ${styles.bgTrack} border-2 ${styles.borderColor} rounded-full overflow-hidden z-10 shadow-[inset_0_2px_4px_rgba(0,0,0,0.5)]`}>
                    <div className={`h-full bg-gradient-to-r ${styles.color} transition-all duration-1000 ease-out`} style={{ width: `${percent}%` }} />
                    <div className="absolute inset-0 flex items-center justify-center pl-10 pr-2 py-0 pointer-events-none">
                        <GameText text={`${track.currentXP} / ${track.targetXP} CL`} baseFontSize={1.1} className="text-white font-black italic tracking-widest drop-shadow-md" />
                    </div>
                </div>
            </div>

            {/* Button Column: Centered relative to the XP track */}
            <div className="flex flex-col items-center gap-1.5">
                <SlantedButton 
                    variant={isSuccess ? 'success' : (canClaim ? variant : 'secondary')}
                    size="xs"
                    className={`!w-[30vw] !h-9 shadow-lg ${(!canClaim || isClaiming) && !isSuccess ? 'opacity-40 grayscale' : ''} ${isSuccess ? 'scale-105' : ''}`}
                    disabled={(isClaiming || !canClaim) && !isSuccess}
                    onClick={(e) => { e.stopPropagation(); onClaim(); }}
                >
                    {renderClaimLabel()}
                </SlantedButton>
                <span className={`text-[0.45rem] font-black uppercase tracking-[0.2em] leading-none drop-shadow-sm whitespace-nowrap ${canClaim ? 'text-slate-300' : 'text-slate-600'}`}>
                    {track.unclaimedCount} UNCLAIMED
                </span>
            </div>
        </div>
    );
};

