interface ProgressionScreenProps {
    onClose: () => void;
}

export const ProgressionScreen: React.FC<ProgressionScreenProps> = ({ onClose }) => {
    const { user, progressionData, activityLog, isProgressionLoading, performSynchronizedAction, inspect } = useUser();

    const [claimingIdx, setClaimingIdx] = useState<number | null>(null);
    const [successIdx, setSuccessIdx] = useState<number | null>(null);

    const handleInspect = (track: ProgressionTrack) => {
        inspect({
            type: track.type === 'box' ? 'box' : 'level_info',
            level: user.level + Math.ceil((track.targetXP - track.currentXP) / 5),
            rewardType: track.type,
            rewardAmount: track.nextRewardAmount,
            boxType: 'MEGA',
            title: track.label,
            description: 'Acquired through progression.'
        });
    };

    const handleClaim = async (type: ProgressionRewardType, idx: number) => {
        if (claimingIdx !== null || successIdx !== null) return;
        setClaimingIdx(idx);
        const success = await performSynchronizedAction(() => api.claimProgressionReward(user, type), { visualDelay: 600 });
        setClaimingIdx(null);
        if (success) {
            setSuccessIdx(idx);
            setTimeout(() => setSuccessIdx(null), 2500);
        }
    };

    if (!progressionData && isProgressionLoading) {
        return (
            <div className="fixed inset-0 z-[200] flex flex-col items-center justify-center bg-slate-950 backdrop-blur-md">
                <div className="w-8 h-8 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mb-4" />
                <span className="text-[0.6rem] font-black text-indigo-400 uppercase tracking-[0.3em] animate-pulse">Syncing Sector Data...</span>
            </div>
        );
    }

    if (!progressionData) return null;

    return (
        <Portal>
            <div className="fixed inset-0 z-[200] flex flex-col bg-slate-950 animated-bg overflow-hidden animate-pop">
                {/* 1. Header */}
                <StandardHeader 
                    title="COLLECTION LEVEL" 
                    className="shrink-0"
                />

                {/* 2. Hero Level Display */}
                <div className="shrink-0 pt-8 pb-4 flex flex-col items-center">
                    <div className="h-12 w-full px-4">
                        <GameText text={progressionData.collectionLevel.toLocaleString()} baseFontSize={3.5} className="text-white font-black italic tracking-tighter drop-shadow-lg" />
                    </div>
                </div>

                {/* 3. Main Scroll Area - GPU Optimized */}
                <div className="flex-1 overflow-y-auto px-4 space-y-8 pb-40 pt-2 custom-scrollbar transform-gpu will-change-scroll">
                    <div className="space-y-4">
                        <h3 className="text-[0.6rem] font-black text-indigo-300/40 uppercase tracking-[0.4em] px-1 text-center">Reward Manifest</h3>
                        <div className="h-px w-full bg-indigo-500/10 relative">
                            <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 w-2 h-2 bg-slate-950 border border-indigo-500/20 rotate-45" />
                        </div>
                    </div>

                    <div className="space-y-8">
                        {progressionData.tracks.map((track, idx) => (
                            <ProgressionTrackRow 
                                key={`${track.type}-${idx}`}
                                track={track}
                                isClaiming={claimingIdx === idx}
                                isSuccess={successIdx === idx}
                                onClaim={() => handleClaim(track.type, idx)}
                                onInspect={() => handleInspect(track)}
                            />
                        ))}
                    </div>

                    <ActivityLogSection logs={activityLog} />
                </div>

                {/* 4. Bottom Interface Layer */}
                <div className="absolute bottom-0 inset-x-0 h-32 bg-gradient-to-t from-slate-950 via-slate-950/80 to-transparent pointer-events-none flex items-center justify-center z-50">
                    <div className="pointer-events-auto mt-8">
                        <button 
                            onClick={onClose}
                            className="group transition-transform active:scale-90"
                        >
                            <HexBadge variant="secondary" size="lg" glow className="ring-2 ring-white/5">
                                <div className="flex flex-col items-center justify-center scale-75">
                                    <svg className="w-8 h-8 text-slate-900" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3.5}>
                                        <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
                                    </svg>
                                </div>
                            </HexBadge>
                            <div className="absolute top-full mt-2 left-1/2 -translate-x-1/2 whitespace-nowrap">
                                <span className="text-[0.5rem] font-black text-white/30 uppercase tracking-[0.4em] group-hover:text-white/50 transition-colors">Close Manifest</span>
                            </div>
                        </button>
                    </div>
                </div>
            </div>

            <style>{`
                .custom-scrollbar::-webkit-scrollbar { width: 0px; }
                .transform-gpu { transform: translateZ(0); }
            `}</style>
        </Portal>
    );
};

