import React, { useState, useLayoutEffect, useRef } from 'react';

interface GameTextProps {
  text: string;
  className?: string;
  baseFontSize: number; // in rem
  maxScale?: number;
  minScale?: number;
  skewFactor?: number; 
  maxLines?: number;
}

const MEASUREMENT_CACHE: Record<string, { w: number, h: number }> = {};

export const GameText: React.FC<GameTextProps> = React.memo(({ 
  text, 
  className = '', 
  baseFontSize,
  maxScale = 1.0,
  minScale = 0.2,
  skewFactor = 1.0,
  maxLines = 1
}) => {
  const [scale, setScale] = useState(1);
  const containerRef = useRef<HTMLDivElement>(null);
  const textRef = useRef<HTMLDivElement>(null);
  const currentScaleRef = useRef(1);

  useLayoutEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const measure = () => {
      const containerW = container.clientWidth * skewFactor;
      const containerH = container.clientHeight;

      if (containerW <= 0 || containerH <= 0) return;

      const cacheKey = `${text}_${baseFontSize}_${skewFactor}_${maxLines}`;
      let dims = MEASUREMENT_CACHE[cacheKey];

      if (!dims) {
        const clone = document.createElement('div');
        clone.style.cssText = `
            position: absolute; visibility: hidden; left: -9999px; top: -9999px;
            font-size: ${baseFontSize}rem; line-height: 0.85; white-space: pre;
            font-family: "IBM Plex Sans Condensed", sans-serif; font-weight: 900; font-style: italic;
            text-transform: uppercase; letter-spacing: -0.05em;
        `;
        clone.innerText = text;
        document.body.appendChild(clone);
        dims = { w: clone.scrollWidth, h: clone.scrollHeight };
        document.body.removeChild(clone);
        MEASUREMENT_CACHE[cacheKey] = dims;
      }

      const scaleW = containerW / (dims.w || 1);
      const scaleH = containerH / (dims.h || 1);
      const targetScale = Math.min(maxScale, Math.max(minScale, Math.min(scaleW, scaleH)));

      // DIRTY CHECK: Only update state if scale change is significant (> 1%)
      // This prevents the "scroll jank" caused by micro-adjustments during container resizing.
      if (Math.abs(currentScaleRef.current - targetScale) > 0.01) {
          currentScaleRef.current = targetScale;
          setScale(targetScale);
      }
    };

    measure();

    const observer = new ResizeObserver(measure);
    observer.observe(container);
    return () => observer.disconnect();
  }, [text, baseFontSize, maxScale, minScale, skewFactor, maxLines]);

  return (
    <div 
        ref={containerRef}
        className={`w-full h-full flex justify-center items-center overflow-hidden pointer-events-none select-none ${className}`}
        style={{ fontSize: `${baseFontSize}rem` }}
    >
      <div 
        ref={textRef}
        style={{ 
          transform: scale < 0.99 ? `scale(${scale})` : 'none',
          transformOrigin: 'center center',
          display: 'flex', 
          width: 'max-content',
          lineHeight: 0.85,
          textAlign: 'center',
          whiteSpace: 'pre',
          willChange: 'transform'
        }} 
      >
        {text}
      </div>
    </div>
  );
});

