        primary: {
            fill: 'url(#bg_primary)',
            stroke: '#818cf8',
            innerStroke: '#c7d2fe',
            text: 'text-white',
            glowColor: 'rgba(99, 102, 241, 0.4)' // Reduced opacity for perf
