                    </linearGradient>
                    <linearGradient id="bg_success" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#064e3b" /><stop offset="100%" stopColor="#022c22" />
                    </linearGradient>
                    <linearGradient id="bg_danger" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#7f1d1d" /><stop offset="100%" stopColor="#450a0a" />
                    </linearGradient>
                    <linearGradient id="bg_warning" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#78350f" /><stop offset="100%" stopColor="#451a03" />
                    </linearGradient>
                    <linearGradient id="bg_blue" x1="0" y1="0" x2="0" y2="1">
                        <stop offset="0%" stopColor="#1e3a8a" /><stop offset="100%" stopColor="#172554" />
                    </linearGradient>

                    <clipPath id="hexClip">
                        <path d="M50 2 L95 25 L95 75 L50 98 L5 75 L5 25 Z" />
                    </clipPath>
                </defs>

                {/* Main Hex Body - Removed costly inner shadow filters */}
                <path 
                    d="M50 2 L95 25 L95 75 L50 98 L5 75 L5 25 Z" 
                    fill={v.fill}
                />

                {/* Outermost Stroke */}
                <path 
                    d="M50 2 L95 25 L95 75 L50 98 L5 75 L5 25 Z" 
                    fill="none" 
                    stroke={v.stroke} 
                    strokeWidth={s.strokeWidth} 
                    strokeLinejoin="round"
                />

                {/* Inner Accent Path */}
                <path 
                    d="M50 5 L91 26 L91 74 L50 95 L9 74 L9 26 Z" 
                    fill="none" 
                    stroke={v.innerStroke} 
                    strokeWidth="1.8" 
                    opacity="0.3"
                    strokeLinejoin="round"
                />
            </svg>

            <div className="relative z-10 w-full h-full flex items-center justify-center pointer-events-none">
                <div className="w-[82%] h-[82%] flex items-center justify-center">
                    {typeof children === 'string' || typeof children === 'number' ? (
                        <span className={`${v.text} font-black italic tracking-tighter uppercase drop-shadow-[0_1px_2px_rgba(0,0,0,1)] text-[0.85em]`}>
                            {children}
                        </span>
                    ) : (
                        <div className={`w-full h-full flex items-center justify-center ${v.text}`}>
                            {children}
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

import React, { useState } from 'react';
import { ProgressionRewardType, ProgressionTrack } from '../../types';
import { useUser } from '../../contexts/UserContext';
import { GameText } from '../ui/GameText';
import { api } from '../../services/api';
import { Portal } from '../ui/Portal';
import { AtmosphericGlow } from '../season/AtmosphericGlow';

// Modular Imports
import { ProgressionTrackRow } from '../progression/ProgressionTrackRow';
import { ActivityLogSection } from '../progression/ActivityLogSection';

interface ProgressionScreenProps {
    onClose: () => void;
}

export const ProgressionScreen: React.FC<ProgressionScreenProps> = ({ onClose }) => {
    const { user, progressionData, activityLog, isProgressionLoading, performSynchronizedAction, inspect } = useUser();

    const [claimingIdx, setClaimingIdx] = useState<number | null>(null);
    const [successIdx, setSuccessIdx] = useState<number | null>(null);

    const handleInspect = (track: ProgressionTrack) => {
        inspect({
            type: track.type === 'box' ? 'box' : 'level_info',
            level: user.level + Math.ceil((track.targetXP - track.currentXP) / 5),
            rewardType: track.type,
            rewardAmount: track.nextRewardAmount,
            boxType: 'MEGA',
            title: track.label,
            description: 'Acquired through progression.'
        });
    };

    const handleClaim = async (type: ProgressionRewardType, idx: number) => {
        if (claimingIdx !== null || successIdx !== null) return;
        setClaimingIdx(idx);
        const success = await performSynchronizedAction(() => api.claimProgressionReward(user, type), { visualDelay: 600 });
        setClaimingIdx(null);
        if (success) {
            setSuccessIdx(idx);
            setTimeout(() => setSuccessIdx(null), 2500);
        }
    };

    if (!progressionData && isProgressionLoading) {
        return (
            <div className="fixed inset-0 z-[200] flex flex-col items-center justify-center bg-slate-950/80 backdrop-blur-md">
                <div className="w-8 h-8 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mb-4" />
                <span className="text-[0.6rem] font-black text-indigo-400 uppercase tracking-[0.3em] animate-pulse">Syncing Sector Data...</span>
            </div>
        );
    }

    if (!progressionData) return null;

    return (
        <Portal>
            {/* 
                PERFORMANCE FIX: Removed 'animated-bg' from here. 
                AppShell already provides the background. Doubling it kills mobile FPS.
            */}
            <div className="fixed inset-0 z-[200] flex flex-col bg-slate-950/60 backdrop-blur-sm overflow-hidden animate-pop">

                {/* Simplified Theme Header - Matches Season Pass speed */}
                <div className="shrink-0 bg-slate-900/60 border-b border-white/5 pt-0.5 pb-1.5 px-3 z-40">
                    <h1 className="text-[1.2rem] font-black text-white italic tracking-tighter uppercase drop-shadow-lg leading-none">
                        COLLECTION LEVEL
                    </h1>
                </div>

                {/* Hero Display */}
                <div className="shrink-0 pt-8 pb-4 flex flex-col items-center relative z-10">
                    <AtmosphericGlow color="99, 102, 241" opacity={0.2} className="z-0" />
                    <div className="h-12 w-full px-4 relative z-10">
                        <GameText 
                            text={progressionData.collectionLevel.toLocaleString()} 
                            baseFontSize={3.5} 
                            className="text-white font-black italic tracking-tighter drop-shadow-[0_0_20px_rgba(99,102,241,0.6)]" 
                        />
                    </div>
                </div>

                {/* Main List Container */}
                <div className="flex-1 overflow-y-auto px-4 space-y-8 pb-40 pt-2 custom-scrollbar relative z-10 scrolling-touch">
                    <div className="space-y-4">
                        <h3 className="text-[0.6rem] font-black text-indigo-300/60 uppercase tracking-[0.4em] px-1 text-center">Reward Manifest</h3>
                        <div className="h-px w-full bg-indigo-500/10 relative">
                            <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 w-2 h-2 bg-slate-950 border border-indigo-500/40 rotate-45" />
                        </div>
                    </div>

                    <div className="space-y-8">
                        {progressionData.tracks.map((track, idx) => (
                            <ProgressionTrackRow 
                                key={`${track.type}-${idx}`}
                                track={track}
                                isClaiming={claimingIdx === idx}
                                isSuccess={successIdx === idx}
                                onClaim={() => handleClaim(track.type, idx)}
                                onInspect={() => handleInspect(track)}
                            />
                        ))}
                    </div>

                    <ActivityLogSection logs={activityLog} />
                </div>

                {/* Interface Footer - Simplified for zero scroll lag */}
                <div className="absolute bottom-0 inset-x-0 h-32 bg-gradient-to-t from-slate-950 via-slate-950/90 to-transparent pointer-events-none flex items-center justify-center z-50">
                    <div className="pointer-events-auto mt-6">
                        <button 
                            onClick={onClose}
                            className="group transition-transform active:scale-90 relative flex flex-col items-center gap-1.5"
                        >
                            {/* Simplified High-Speed Close Button (No SVG Filters) */}
                            <div className="w-12 h-12 rounded-full bg-slate-800 border-2 border-white/20 shadow-xl flex items-center justify-center group-hover:bg-slate-700 group-hover:border-white/40 transition-colors">
                                <svg className="w-6 h-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3.5}>
                                    <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
                                </svg>
                            </div>
                            <span className="text-[0.5rem] font-black text-white/40 uppercase tracking-[0.4em] group-hover:text-white/70 transition-colors">Close</span>
                        </button>
                    </div>
                </div>
            </div>

            <style>{`
                .custom-scrollbar::-webkit-scrollbar { width: 0px; }
            `}</style>
        </Portal>
    );
};

