        if (activeScreen === 'DECK') {
            setActiveTab('CARDS');
            setIsProgressionOpen(false);
        }
    }, [activeScreen]);

    const scrollRef = useRef<HTMLDivElement>(null);
    const vaultRef = useRef<HTMLDivElement>(null);
    const archiveRef = useRef<HTMLDivElement>(null);

    const handleAddCard = useCallback((cardId: string) => {
        if (activeDeck.length < 12 && !activeDeck.includes(cardId)) {
            updateDeck(user.activeDeckId, [...activeDeck, cardId]);
        }
    }, [activeDeck, user.activeDeckId, updateDeck]);

    const handleRemoveCard = useCallback((cardId: string) => {
        updateDeck(user.activeDeckId, activeDeck.filter(id => id !== cardId));
    }, [activeDeck, user.activeDeckId, updateDeck]);

    const { dragState, handlePointerDown } = useCollectionDrag({
        onAdd: handleAddCard,
        onRemove: handleRemoveCard,
        scrollRef: scrollRef,
        vaultRef: vaultRef,
        archiveRef: archiveRef
    });

    const deckCards = useMemo(() => {
        return activeDeck
            .map(id => CARDS.find(c => c.id === id))
            .filter((c): c is CardDefinition => !!c)
            .sort((a, b) => {
                if (a.baseCost !== b.baseCost) {
                    return a.baseCost - b.baseCost;
                }
                return a.name.localeCompare(b.name);
            });
    }, [activeDeck]);

    const renderContent = () => {
        switch(activeTab) {
            case 'COMICS': return <ComicArchive />;
            case 'INVENTORY': return <InventoryStash />;
            default:
                return (
                    <div className="flex flex-col h-full overflow-hidden">
                        <div 
                            ref={vaultRef}
                            className={`shrink-0 border-b border-slate-700/50 z-20 transition-all duration-300 ${dragState?.active && dragState.origin === 'archive' ? 'ring-2 ring-inset ring-indigo-500/50' : ''}`}
                            data-drop-zone="vault"
                        >
                            <DeckSelector 
                                activeDeckId={user.activeDeckId} 
                                onSelectDeck={setActiveDeck}
                            />

                            <div className="px-3 pb-2">
                                <DeckVault 
                                    cards={deckCards} 
                                    draggingCardId={dragState?.active && dragState.origin === 'vault' ? dragState.card.id : undefined}
                                    onPointerDown={(e, card) => handlePointerDown(e, card, 'vault')}
                                />
                            </div>
                        </div>

                        <div 
                            ref={archiveRef}
                            className={`flex-1 min-h-0 relative transition-all duration-300 ${dragState?.active && dragState.origin === 'vault' ? 'bg-indigo-500/5' : ''}`}
                            data-drop-zone="archive"
                        >
                            <CollectionGrid 
                                scrollRef={scrollRef}
                                ownedIds={user.collection}
                                activeDeckIds={activeDeck}
                                draggingCardId={dragState?.active && dragState.origin === 'archive' ? dragState.card.id : undefined}
                                onPointerDown={(e, card) => handlePointerDown(e, card, 'archive')}
                            />
                        </div>
                    </div>
                );
        }
    };

    return (
        <div className="w-full h-full flex flex-col bg-transparent overflow-hidden relative">
            {/* 
                PERFORMANCE ARCHITECTURE:
                When the progression manifest is open, we do NOT render the background content.
                This prevents the GPU from processing dozens of cards behind the opaque overlay.
            */}
            {!isProgressionOpen && (
                <>
                    <StandardHeader 
                        title="COLLECTION" 
                        className="!pl-0.5 !pr-1" 
                        leftContent={
                            <div className="flex items-center gap-1.5">
                                <GenomeBadge 
                                    level={user.level} 
                                    onClick={() => setIsProgressionOpen(true)}
                                />
                            </div>
                        }
                        rightContent={
                            <div className="flex items-center gap-1.5">
                                <SlantedButton 
                                    variant={activeTab === 'CARDS' ? 'primary' : 'secondary'} 
                                    size="xs"
                                    className="!w-[9vw] max-w-[2.3rem] !h-[1.65rem] shadow-lg"
                                    onClick={() => setActiveTab('CARDS')}
                                    icon={<svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" /></svg>}
                                />
                                <SlantedButton 
                                    variant={activeTab === 'COMICS' ? 'primary' : 'secondary'} 
                                    size="xs"
                                    className="!w-[9vw] max-w-[2.3rem] !h-[1.65rem] shadow-lg"
                                    onClick={() => setActiveTab('COMICS')}
                                    icon={<svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" /></svg>}
                                />
                                <SlantedButton 
                                    variant={activeTab === 'INVENTORY' ? 'primary' : 'secondary'} 
                                    size="xs"
                                    className="!w-[9vw] max-w-[2.3rem] !h-[1.65rem] shadow-lg"
                                    onClick={() => setActiveTab('INVENTORY')}
                                    icon={<svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M20 7l-8-4-8 4m16 0l-8 4m8-4v10l-8 4m0-10L4 7m8 4v10M4 7v10l8 4" /></svg>}
                                />
                            </div>
                        }
                    />

                    <CollectionDragOverlay dragState={dragState} />

                    <div className="flex-1 overflow-hidden">
                        {renderContent()}
                    </div>
                </>
            )}

            {/* Collection Level Modal Overlay */}
            {isProgressionOpen && (
                <ProgressionScreen onClose={() => setIsProgressionOpen(false)} />
            )}
        </div>
    );
};

import React, { useState } from 'react';
import { ProgressionRewardType, ProgressionTrack } from '../../types';
import { useUser } from '../../contexts/UserContext';
import { GameText } from '../ui/GameText';
import { api } from '../../services/api';
import { Portal } from '../ui/Portal';
import { AtmosphericGlow } from '../season/AtmosphericGlow';

// Modular Imports
import { ProgressionTrackRow } from '../progression/ProgressionTrackRow';
import { ActivityLogSection } from '../progression/ActivityLogSection';

interface ProgressionScreenProps {
    onClose: () => void;
}

export const ProgressionScreen: React.FC<ProgressionScreenProps> = ({ onClose }) => {
    const { user, progressionData, activityLog, isProgressionLoading, performSynchronizedAction, inspect } = useUser();

    const [claimingIdx, setClaimingIdx] = useState<number | null>(null);
    const [successIdx, setSuccessIdx] = useState<number | null>(null);

    const handleInspect = (track: ProgressionTrack) => {
        inspect({
            type: track.type === 'box' ? 'box' : 'level_info',
            level: user.level + Math.ceil((track.targetXP - track.currentXP) / 5),
            rewardType: track.type,
            rewardAmount: track.nextRewardAmount,
            boxType: 'MEGA',
            title: track.label,
            description: 'Acquired through progression.'
        });
    };

    const handleClaim = async (type: ProgressionRewardType, idx: number) => {
        if (claimingIdx !== null || successIdx !== null) return;
        setClaimingIdx(idx);
        const success = await performSynchronizedAction(() => api.claimProgressionReward(user, type), { visualDelay: 600 });
        setClaimingIdx(null);
        if (success) {
            setSuccessIdx(idx);
            setTimeout(() => setSuccessIdx(null), 2500);
        }
    };

    if (!progressionData && isProgressionLoading) {
        return (
            <div className="fixed inset-0 z-[200] flex flex-col items-center justify-center bg-slate-950">
                <div className="w-8 h-8 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin mb-4" />
                <span className="text-[0.6rem] font-black text-indigo-400 uppercase tracking-[0.3em] animate-pulse">Syncing Sector Data...</span>
            </div>
        );
    }

    if (!progressionData) return null;

    return (
        <Portal>
            {/* 
                PERFORMANCE ARCHITECTURE: 
                - Opaque bg-slate-950 base ensures NO background blending.
                - .animated-bg is the only moving layer.
            */}
            <div className="fixed inset-0 z-[200] flex flex-col bg-slate-950 overflow-hidden animate-pop">

                {/* Hardware-accelerated animated gradient layer */}
                <div className="absolute inset-0 animated-bg z-0" />

                {/* SOLID OPAQUE THEME HEADER */}
                <div className="shrink-0 bg-slate-950 border-b border-white/10 pt-1 pb-2 px-3 z-40">
                    <h1 className="text-[1.2rem] font-black text-white italic tracking-tighter uppercase drop-shadow-lg leading-none">
                        COLLECTION LEVEL
                    </h1>
                </div>

                {/* Hero Display */}
                <div className="shrink-0 pt-8 pb-4 flex flex-col items-center relative z-10 bg-black/40">
                    <AtmosphericGlow color="99, 102, 241" opacity={0.25} className="z-0" />
                    <div className="h-12 w-full px-4 relative z-10">
                        <GameText 
                            text={progressionData.collectionLevel.toLocaleString()} 
                            baseFontSize={3.5} 
                            className="text-white font-black italic tracking-tighter drop-shadow-[0_0_20px_rgba(99,102,241,0.6)]" 
                        />
                    </div>
                </div>

                {/* Main List Container - Optimized Scroll Layer */}
                <div className="flex-1 overflow-y-auto px-4 space-y-8 pb-40 pt-4 custom-scrollbar relative z-10 scrolling-touch overflow-x-hidden">
                    <div className="space-y-4">
                        <h3 className="text-[0.6rem] font-black text-indigo-300 uppercase tracking-[0.4em] px-1 text-center">Reward Manifest</h3>
                        <div className="h-px w-full bg-indigo-500/20 relative">
                            <div className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 w-2 h-2 bg-slate-950 border border-indigo-500/40 rotate-45" />
                        </div>
                    </div>

                    <div className="space-y-8">
                        {progressionData.tracks.map((track, idx) => (
                            <ProgressionTrackRow 
                                key={`${track.type}-${idx}`}
                                track={track}
                                isClaiming={claimingIdx === idx}
                                isSuccess={successIdx === idx}
                                onClaim={() => handleClaim(track.type, idx)}
                                onInspect={() => handleInspect(track)}
                            />
                        ))}
                    </div>

                    <ActivityLogSection logs={activityLog} />
                </div>

                {/* OPAQUE FOOTER BAR - Far Bottom Placement */}
                <div className="shrink-0 h-24 bg-slate-950 border-t border-white/10 flex items-center justify-center z-50">
                    <button 
                        onClick={onClose}
                        className="group transition-transform active:scale-90 relative flex flex-col items-center gap-1.5"
                    >
                        {/* High-Performance Close Button (No filters, No transparency) */}
                        <div className="w-11 h-11 rounded-full bg-slate-800 border-2 border-slate-600 flex items-center justify-center group-hover:bg-slate-700 group-hover:border-indigo-500 transition-colors">
                            <svg className="w-6 h-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={3.5}>
                                <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
                            </svg>
                        </div>
                        <span className="text-[0.5rem] font-black text-slate-500 uppercase tracking-[0.4em] group-hover:text-white transition-colors">Close Manifest</span>
                    </button>
                </div>
            </div>

            <style>{`
                .custom-scrollbar::-webkit-scrollbar { width: 0px; }
            `}</style>
        </Portal>
    );
};

