                        variant={activeFilter === f.id ? f.variant : 'secondary'}
                        size="xs"
                        className={`!w-[13vw] max-w-[3rem] shrink-0 transition-all duration-300 ${activeFilter === f.id ? 'scale-110 z-10' : 'opacity-60 scale-95'}`}
