import React, { useState, useMemo } from 'react';
import { ActivityLogEntry, ProgressionRewardType } from '../../types';
import { RewardIconGraphic } from '../ui/RewardItemVisual';
import { SlantedButton } from '../ui/SlantedButton';
import { BoosterIcon, CreditIcon, GoldIcon, TokenIcon, OmegaBoxIcon } from '../ui/CurrencyIcons';

type FilterType = 'all' | ProgressionRewardType;

const ActivityLogItem = React.memo(({ item }: { item: ActivityLogEntry }) => {
    let iconScale = 'scale-[1.45]'; 
    if (item.type === 'card') iconScale = 'scale-[0.6]'; 
    else if (item.type === 'credits' || item.type === 'gold' || item.type === 'tokens') iconScale = 'scale-[1.55]';

    return (
        <div className="flex items-center justify-between py-2 px-3 bg-slate-800/80 border border-slate-700/50 rounded-lg shadow-sm cursor-default">
            <div className="flex items-center gap-3">
                <div className="w-10 h-10 flex items-center justify-center overflow-visible">
                    <div className={iconScale}>
                        <RewardIconGraphic type={item.type as any} size="sm" cardDef={item.cardDef} />
                    </div>
                </div>
                <div>
                    <div className="font-black text-[0.75rem] tracking-tight text-white uppercase italic leading-tight">{item.title}</div>
                    <div className="text-[0.5rem] text-slate-400 font-bold uppercase tracking-[0.2em] mt-0.5">Manifest Claim</div>
                </div>
            </div>
            <div className="text-right flex flex-col items-end shrink-0">
                 <div className="text-[0.7rem] font-black text-white uppercase tracking-tighter tabular-nums leading-none mb-1">{item.date}</div>
                 <div className="text-[0.55rem] font-bold text-slate-500 uppercase tracking-widest tabular-nums leading-none">{item.time}</div>
            </div>
        </div>
    );
});

export const ActivityLogSection: React.FC<{ logs: ActivityLogEntry[] }> = ({ logs }) => {
    const [activeFilter, setActiveFilter] = useState<FilterType>('all');

    const filteredLogs = useMemo(() => {
        if (activeFilter === 'all') return logs;
        return logs.filter(log => log.type === activeFilter);
    }, [logs, activeFilter]);

    const filters: { id: FilterType; icon: React.ReactNode; variant: any }[] = [
        { id: 'all', icon: <span className="text-[0.6rem] font-black italic">ALL</span>, variant: 'secondary' },
        { id: 'booster', icon: <BoosterIcon size="xs" />, variant: 'success' },
        { id: 'credits', icon: <CreditIcon size="xs" />, variant: 'blue' },
        { id: 'gold', icon: <GoldIcon size="xs" />, variant: 'warning' },
        { id: 'tokens', icon: <TokenIcon size="xs" />, variant: 'danger' },
        { id: 'box', icon: <OmegaBoxIcon size="xs" />, variant: 'primary' },
    ];

    return (
        <div className="pb-10">
            {/* Header Area */}
            <div className="flex flex-col gap-4 mb-4 px-1">
                <div className="flex items-center gap-3">
                    <h3 className="text-[0.6rem] font-black text-white/40 uppercase tracking-[0.4em] whitespace-nowrap">Activity Archive</h3>
                    <div className="flex-1 h-px bg-white/5" />
                </div>
            </div>

            {/* Flat Filter Bar - No Scaling or Transitions */}
            <div className="flex items-center gap-1.5 mb-6 overflow-x-auto pb-2 scrollbar-hide px-1">
                {filters.map((f) => (
                    <SlantedButton
                        key={f.id}
                        variant={activeFilter === f.id ? f.variant : 'secondary'}
                        size="xs"
                        className={`!w-[13vw] max-w-[3rem] shrink-0 ${activeFilter === f.id ? 'opacity-100' : 'opacity-40'}`}
                        onClick={() => setActiveFilter(f.id)}
                    >
                        {f.icon}
                    </SlantedButton>
                ))}
            </div>

            {/* Log List */}
            <div className="space-y-2 min-h-[10rem]">
                {filteredLogs.length > 0 ? (
                    filteredLogs.map((item) => (
                        <ActivityLogItem key={item.id} item={item} />
                    ))
                ) : (
                    <div className="h-32 flex flex-col items-center justify-center border-2 border-dashed border-white/5 rounded-xl bg-white/5">
                        <div className="opacity-10 mb-2">
                             {filters.find(f => f.id === activeFilter)?.icon}
                        </div>
                        <span className="text-[0.55rem] font-black text-slate-800 uppercase tracking-[0.4em]">No {activeFilter} entries</span>
                    </div>
                )}
            </div>
        </div>
    );
};

