// Calculate the exact XP offset required for each bar to "pop" at the right linear interval
const CUMULATIVE_UNLOCKS = REWARD_SEQUENCE.reduce((acc, curr, i) => {
    const prev = i === 0 ? 0 : acc[i-1];
    acc.push(prev + curr.xpStep);
    return acc;
}, [] as number[]);

