        if (type === 'credits') updatedProfile.credits += rewardConfig.amount as number;
        else if (type === 'gold') updatedProfile.gold += rewardConfig.amount as number;
        else if (type === 'tokens') updatedProfile.tokens += rewardConfig.amount as number;

