const STORAGE_KEY = 'galactic_snap_mock_db_v1';

interface DbState {
    claimedCounts: number[];
    activityLog: ActivityLogEntry[];
    currentSeasonIndex: number;
    userProfile?: any; // Partial override for persistence
}

const DEFAULT_STATE: DbState = {
    claimedCounts: [0, 0, 0, 0, 0],
    activityLog: [
        { id: 'log_0', title: "1000 Tokens", type: 'tokens', date: "15 MAY", time: "10:30", amount: 1000 },
        { id: 'log_1', title: "Portal Mage", type: 'card', date: "14 MAY", time: "22:15", cardDef: CARDS[8] },
        { id: 'log_2', title: "Omega Box", type: 'box', date: "12 MAY", time: "14:20" },
        { id: 'log_3', title: "500 Credits", type: 'credits', date: "11 MAY", time: "09:45", amount: 500 },
    ],
    currentSeasonIndex: 0
};

// Load initial state
let state: DbState = (() => {
    try {
        const saved = localStorage.getItem(STORAGE_KEY);
        return saved ? JSON.parse(saved) : DEFAULT_STATE;
    } catch {
        return DEFAULT_STATE;
    }
})();

const save = () => {
    try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
    } catch (e) {
        console.warn("Could not persist mock state", e);
    }
};

export const progressionStore = {
    get claimedCounts() { return state.claimedCounts; },
    set claimedCounts(val) { state.claimedCounts = val; save(); },

    get activityLog() { return state.activityLog; },
    set activityLog(val) { state.activityLog = val; save(); }
};

