    get currentSeasonIndex() { return state.currentSeasonIndex; },
    set currentSeasonIndex(val) { state.currentSeasonIndex = val; save(); }
};

export const persistUserProfile = (profile: any) => {
    state.userProfile = profile;
    save();
};

