import { UserProfile, StoreData, PurchaseResponse } from '../../types';
import { MOCK_STORE_OFFERS } from './mockData';
import { simulateNetwork } from './apiUtils';
import { persistUserProfile } from './mockDb';

/**
 * STORE SERVICE
 * Handles offer filtering and authoritative transaction processing.
 */
export const storeService = {
    async getOffers(user: UserProfile): Promise<StoreData> {
        await simulateNetwork(300, 500); 
        const filteredOffers = MOCK_STORE_OFFERS.filter(offer => {
            if (offer.isOneTime && user.purchasedOfferIds.includes(offer.id)) return false;
            return true;
        });
        return { offers: [...filteredOffers], lastUpdated: Date.now(), refreshHintSeconds: 60 };
    },

    async purchaseOffer(user: UserProfile, offerId: string, transactionId: string): Promise<PurchaseResponse> {
        await simulateNetwork(800, 1200);
        const offer = MOCK_STORE_OFFERS.find(o => o.id === offerId);
        if (!offer) return { success: false, errorCode: 'ERR_OFFER_NOT_FOUND', transactionId };

        // --- AUTHORITATIVE BALANCE CHECK ---
        if (offer.priceType === 'gold' && user.gold < (offer.priceAmount || 0)) {
            return { success: false, errorCode: 'ERR_INSUFFICIENT_FUNDS', transactionId };
        }
        if (offer.priceType === 'tokens' && user.tokens < (offer.priceAmount || 0)) {
            return { success: false, errorCode: 'ERR_INSUFFICIENT_FUNDS', transactionId };
        }

        const updatedProfile: UserProfile = { ...user };

        // Deduct Price
        if (offer.priceType === 'gold') updatedProfile.gold -= (offer.priceAmount || 0);
        if (offer.priceType === 'tokens') updatedProfile.tokens -= (offer.priceAmount || 0);

        // Grant Rewards
        offer.contents.forEach(item => {
            if (item.type === 'currency') {
                if (item.currencyType === 'gold') updatedProfile.gold += item.amount;
                if (item.currencyType === 'credits') updatedProfile.credits += item.amount;
                if (item.currencyType === 'tokens') updatedProfile.tokens += item.amount;
            } else if (item.type === 'card' && !updatedProfile.collection.includes(item.definitionId)) {
                updatedProfile.collection = [...updatedProfile.collection, item.definitionId];
            }
        });

        updatedProfile.purchasedOfferIds = [...updatedProfile.purchasedOfferIds, offerId];

        persistUserProfile(updatedProfile);

        return { success: true, transactionId, updatedProfile };
    }
};

